          const byId=new Map(); [...server,...local].forEach(m=>{ if(m&&m.id&&!byId.has(m.id)) byId.set(m.id,m); });
          const mergedList=[...byId.values()].sort((x,y)=>String(x.at||"").localeCompare(String(y.at||""))).slice(-(typeof CHAT_MAX==="number"?CHAT_MAX:400));
