const IMPORTED_RATE_CARD_KEY = "bciq_imported_rate_card_assets";
function loadImportedRateCardAssets() { try { return JSON.parse(memStore.getItem(IMPORTED_RATE_CARD_KEY)) || []; } catch { return []; } }
function saveImportedRateCardAssets(list) { const s = JSON.stringify(list || []); memStore.setItem(IMPORTED_RATE_CARD_KEY, s); if (typeof pushSharedData === "function") pushSharedData("importedRateCardAssets", { value: s }); }
function rateCardAssetKey(asset) { return assetDetailsKey(asset && (asset.asset || asset.newName || asset.name || "")); }
function withAssetRateDefaults(asset) {
  const a = repairAssetName(asset || {});
  const d = assetDetailsFor(a.asset);
  if (d && d.displayName) a.displayName = d.displayName;
  if (d && d.rateCard !== undefined && d.rateCard !== "" && d.rateCard !== null) { a.rate = Number(d.rateCard); a.rate2026 = Number(d.rateCard); }
  else if (a.rate2026 !== undefined && a.rate2026 !== "" && a.rate2026 !== null) a.rate = Number(a.rate2026);
  if (d && d.rateCard2027 !== undefined && d.rateCard2027 !== null) a.rate2027 = d.rateCard2027;
  return a;
}
function getFullCatalog() {
  const imported = loadImportedRateCardAssets();
  const authoritative = [...RATE_CARD_2026_ASSETS, ...imported].map(withAssetRateDefaults).filter(r => !RETIRED_ASSET_IDS.has(r.id));
  const seen = new Set(authoritative.map(rateCardAssetKey));
  const legacy = ASSET_CATALOG.map(withAssetRateDefaults).filter(r => !RETIRED_ASSET_IDS.has(r.id) && !seen.has(rateCardAssetKey(r)));
  const legacySeen = new Set([...seen, ...legacy.map(rateCardAssetKey)]);
  const custom = CUSTOM_ASSETS.map(withAssetRateDefaults).filter(r => !RETIRED_ASSET_IDS.has(r.id) && !legacySeen.has(rateCardAssetKey(r)));
  return [...authoritative, ...legacy, ...custom];
}
