let BASE_DATA = window.SPONSOR_DATA || [];

/* This file is the sponsor database now — it does not read from or write to any Google Sheet.
   Everything below comes from the snapshot baked into this file at DATA_IMPORTED_ON. */
const DATA_IMPORTED_ON = "July 14, 2026";

const RATE_CARD = window.RATE_CARD || {};

const OUTLOOK_LABELS = {
  multiyear: "Multi-Year",
  confirmed: "In Contract",
  likely: "Likely",
  risk: "At Risk",
  lost: "Out",
  newpartner: "N/A - New Partner",
  unknown: "Not Yet Assessed"
};
const OUTLOOK_HEALTH = { multiyear: "multiyear", confirmed: "confirmed", likely: "likely", risk: "risk", lost: "lost", newpartner: "newpartner", unknown: "unknown" };
/* ============ DEAL STAGE (Score CRM-style sales pipeline) ============
   A separate concept from renewal outlook above: outlook is "will they resign",
   deal stage is "where is the current transaction right now" — the same distinction
   Score CRM's Sales/Deals pipeline draws. Reuses the outlook-picker CSS color classes
   (multiyear/confirmed/likely/risk/lost/unknown) so no new styling was needed. */
/* Each stage carries a close-probability (`prob`, 0–100). Probability Value =
   Σ(account value × stage prob) — the CRM-style weighted forecast SponsorCX shows
   in its Deals header. These %s are intentionally a single editable object here so
   they can later move into Settings → Values without hunting through the code. */
const DEAL_STAGES = {
  prospect: { label: "Prospecting", cls: "unknown", prob: 10 },
  meeting_set: { label: "First Meeting Set", cls: "unknown", prob: 20 },
  meeting_complete: { label: "First Meeting Complete", cls: "likely", prob: 35 },
  proposal: { label: "Proposal Sent/Shown", cls: "likely", prob: 50 },
  proposal_review: { label: "Proposal in Review", cls: "risk", prob: 65 },
  contract: { label: "Contract Out", cls: "confirmed", prob: 85 },
  signed: { label: "Signed/Active", cls: "multiyear", prob: 100 },
  lost: { label: "Lost/Passed", cls: "lost", prob: 0 }
};
/* Stage close-%s are editable in Settings (T7 — config-as-data). An override map in
   storage wins over the hardcoded defaults; the pipeline forecast reads through here. */
const STAGE_PROB_KEY = "bciq_stage_probs";
function loadStageProbs() { try { return JSON.parse(memStore.getItem(STAGE_PROB_KEY)) || {}; } catch (e) { return {}; } }
function saveStageProbs(map) { try { memStore.setItem(STAGE_PROB_KEY, JSON.stringify(map || {})); pushSharedData("stageProbs", { value: JSON.stringify(map || {}) }); } catch (e) {} } /* index211: stage weights are a team-level forecasting setting — now synced instead of per-browser */
function dealStageProb(key) {
  const ov = loadStageProbs();
  if (ov && typeof ov[key] === "number") return ov[key];
  return (DEAL_STAGES[key] && typeof DEAL_STAGES[key].prob === "number") ? DEAL_STAGES[key].prob : 0;
}
/* T9 — the SponsorCX "no next activity scheduled" nudge. An open pipeline account
   with no future-dated activity on file needs a follow-up logged. Closed stages
   (Signed / Lost) don't count. Shown as an icon+text tag (not colour alone). */
function bciqTodayIso() { const d = new Date(); return d.getFullYear() + "-" + String(d.getMonth() + 1).padStart(2, "0") + "-" + String(d.getDate()).padStart(2, "0"); }
function hasScheduledNextStep(r) {
  const t = bciqTodayIso();
  const log = Array.isArray(r.activityLog) ? r.activityLog : [];
  if (log.some(a => a && a.date && String(a.date).slice(0, 10) >= t)) return true;
  if (r.nextStepDate && String(r.nextStepDate) >= t) return true;
  return false;
}
function needsNextStep(r) {
  const st = dealStageOf(r);
  if (st === "lost" || st === "signed") return false;
  return !hasScheduledNextStep(r);
}

