function invNormName(s){ return String(s||"").toLowerCase().replace(/[^a-z0-9]+/g," ").trim(); }
const INVENTORY_BY_NAME = (function(){ var m={}; INVENTORY_2026.forEach(function(d){ m[invNormName(d.a)]=d; }); return m; })();
function inventoryAvailFor(name){
  var key = invNormName(name);
  if (INVENTORY_BY_NAME[key]) return INVENTORY_BY_NAME[key];
  var toks = key.split(" ").filter(Boolean).slice(0,3).join(" ");
  if (!toks) return null;
  return INVENTORY_2026.find(function(d){ return invNormName(d.a).indexOf(toks)===0; }) || null;
}
function inventoryStatus(d){
  if (!d) return null;
  var res = (d.r>0)?(" · "+d.r+" reserved"):"";
  if (d.av <= 0) return { key:"soldout", label:"Sold out"+res };
  if (d.av <= 2) return { key:"limited", label:d.av+" left"+res };
  return { key:"available", label:d.av+" left"+res };
}
/* Oversell: would requesting `qty` of `name` exceed what is still available? */
function oversellState(name, qty){
  var d = inventoryAvailFor(name); if (!d) return null;
  var want = Math.max(1, parseInt(qty,10)||1);
  return { over: want > d.av, want: want, avail: d.av, total: d.t, sold: d.c, asset: d.a };
}
function inventoryTotals(){
  return INVENTORY_2026.reduce(function(s,d){ s.total+=d.t; s.sold+=d.c; s.avail+=d.av; s.reserved+=(d.r||0); return s; }, {total:0,sold:0,avail:0,reserved:0});
}
function inventoryReportRows(year = sState.season) {
  return sortByCategoryThenRate(getFullCatalog(), a => resolvedRateForYear(a, year) || resolvedRate(a) || 0).map(a => {
    const detail = assetDetailsFor(a.asset);
    const base = inventoryAvailFor(a.asset);
    const total = Number(detail.totalQty || (base && base.t) || 0);
    const sold = activeSeasonRecords(year).reduce((sum, r) => sum + fulfillmentAssetsFor(r).filter(x => assetNameMatch(x.asset, a.asset)).reduce((s, x) => s + assetQtyNumber(x.qty), 0), 0);
    const assigned = String(year) === "2026" ? sold : 0;
    const proposed = loadOptions().reduce((sum, p) => sum + (p.options || []).reduce((os, o) => os + (o.items || []).filter(i => assetNameMatch(i.asset, a.asset)).reduce((is, i) => is + assetQtyNumber(i.qty), 0), 0), 0);
    const available = total ? Math.max(0, total - sold - proposed) : "";
    return { asset:a.asset, category:canonicalCategory(a.category), rate:resolvedRateForYear(a, year) || resolvedRate(a) || 0, total: total || "", sold, assigned, proposed, available };
  });
}
function dealStageOf(r) { return (r.dealStage && DEAL_STAGES[r.dealStage]) ? r.dealStage : (isActiveForSelectedSeason(r) ? "signed" : (r.active ? "prospect" : "lost")); }
const TYPE_COLORS = { "Cash": "#0971ce", "Trade": "#0d1d41", "MiLB": "#facd01", "Cash & Trade": "#c20f2f" };

/* =========================================================================
   index242 — ONE current season, derived, not typed.
   -------------------------------------------------------------------------
   Build 241 carried the string "2026" in seven separate pieces of logic: the
   default state, the season dropdown's floor and its fallback, the "current
   partner" cohort filter, the sponsor drawer's future-standing tags, and the
   Upper Tier board branches. None of them followed the season the rest of the
   app runs on, so the first day of the 2027 season the app would quietly
   misclassify every sponsor whose 2026 status differs from their 2027 one —
   while still showing the right year in the header, which is worse than
   showing the wrong one everywhere.

  CURRENT_SEASON is the only place the year is decided now. It rolls the day
   after the prior BlueClaws season ends, so the app follows the actual
   sponsorship/baseball season rather than the calendar year. Everything the
   user can re-point by hand still reads sState.season; only things that mean
   "the season we are actually in" read this.
   ========================================================================= */
const BLUECLAWS_SEASON_END_DATES = {
  "2026": "2026-09-06",
  "2027": "2027-09-05"
};
function localDateKey(value) {
  const d = value instanceof Date ? value : new Date(`${value}T12:00:00`);
  if (!(d instanceof Date) || Number.isNaN(d.getTime())) return 0;
  return Number(`${d.getFullYear()}${String(d.getMonth() + 1).padStart(2, "0")}${String(d.getDate()).padStart(2, "0")}`);
}
function defaultBlueClawsSeason(today = new Date()) {
  const todayKey = localDateKey(today);
  const seasons = Object.keys(BLUECLAWS_SEASON_END_DATES).sort();
  for (const season of seasons) {
    if (todayKey <= localDateKey(BLUECLAWS_SEASON_END_DATES[season])) return season;
  }
  const last = Number(seasons[seasons.length - 1] || today.getFullYear());
  return String(Number.isFinite(last) ? last + 1 : today.getFullYear());
}
const CURRENT_SEASON = (function () {
  try {
    return defaultBlueClawsSeason(new Date());
  } catch (e) { return "2026"; }
})();
let sState = { search: "", active: "all", type: "all", rep: "all", outlook: "all", sort: "status-name", season: CURRENT_SEASON, view: "3" };
let rState = { search: "", stage: "all", dealStage: "all", sort: "risk" };
let pState = { view: "all", search: "", newSearch: "", tab: "week" };
let aState = { mode: "folders", category: null, search: "", pickedSponsor: "" };
let oState = { pickerSearch: "", pickerCategory: "all", pickerLanguage: "covered", pickerRateYear: "2026" };
let fState = { search: "", sponsorId: "" };

const RATES_KEY = "bciq_asset_rates";
const ASSET_DETAILS_KEY = "bciq_asset_details";
const OPTIONS_KEY = "bciq_options";
const LINKS_KEY = "bciq_quicklinks";
const CURRENT_OPTION_KEY = "bciq_current_option";

const FOLDER_ICONS = {
  "Signage & Displays": "▣", "Gameday": "▦", "Hospitality": "★", "Weekly Promotion": "↻",
  "Marketing - Digital & Broadcast": "◈", "Marketing - Print": "▤", "Sponsor Programs": "$",
  "Fan Engagement & Community": "◆", "Game Sponsor": "◉", "Miscellaneous & Other": "▪",
  "Food & Beverage": "▢", "Non-Gameday": "○", "Special Events": "◈"
};
function folderIcon(cat) { return FOLDER_ICONS[cat] || "▪"; }

/* ---------------- persistence ---------------- */
function loadOverrides() { try { return JSON.parse(memStore.getItem(STORAGE_KEY)) || {}; } catch { return {}; } }
/* index242 — this used to swallow a failed write and log it to a console nobody has open,
   while the drawer went straight on to a green "Saved". It now reports what actually
   happened so the caller can stop claiming a save that didn't occur. */
function saveOverrides(o) {
  const stored = durableSet(STORAGE_KEY, JSON.stringify(o), "your sponsor edit");
  if (typeof invalidateRecordCache === "function") invalidateRecordCache();
  return stored;
}
/* ================= EMBEDDED VIEWS ================= */
function loadCustom() { try { return JSON.parse(memStore.getItem(CUSTOM_KEY)) || []; } catch { return []; } }
function saveCustom(c) { const s = JSON.stringify(c); durableSet(CUSTOM_KEY, s, "your sponsor list"); if (typeof invalidateRecordCache === "function") invalidateRecordCache(); pushSharedData("customSponsors", { value: s }); }
const QUICK_LINK_DEFAULTS = { score: "https://scorecrm.mtpsoftware.com/Sales/Assets", gameday: "https://docs.google.com/spreadsheets/d/1UYYe7PuzQhJe4BBAwfH-kURSGkE-PMjKR4okufXewtw/edit?gid=89081563#gid=89081563" };
/* index211: the embed views used to keep their own copy of the Score CRM / Gameday links in a
   second store (bciq_quick_links) whose name sat one underscore away from the topbar's
   bciq_quicklinks — editing a link in one place silently left the other stale. Both paths now
   read and write the ONE topbar links store; anything customized in the old store migrates over
   once, and the old store/channel is left in place so older builds on other machines still work. */
function loadQuickLinks() {
  try {
    const legacy = JSON.parse(memStore.getItem(QUICK_LINKS_KEY)) || {};
    const links = loadLinks();
    let migrated = false;
    Object.entries(legacy).forEach(([k, v]) => {
      /* index257: migrate only when the live store has never held this key at all.
         `links[k] === ""` is a deliberate clear ("Change URL") and the legacy store
         must not resurrect the old address on the next render. */
      if (v && v !== QUICK_LINK_DEFAULTS[k] && (links[k] === undefined || links[k] === defaultLinks()[k])) { links[k] = v; migrated = true; }
    });
    if (migrated) saveLinks(links);
    return links;
  } catch { return loadLinks(); }
}
function saveQuickLinks(links) { saveLinks({ ...loadLinks(), ...links }); }
function renderEmbedView(key) {
  const container = document.querySelector(`#embed-${key}View .embed-wrap`);
  if (!container) return;
  const links = loadQuickLinks();
  const url = (links[key] || "").trim();
  const label = container.dataset.embedLabel;

  if (!url) {
    container.innerHTML = `
      <div class="embed-setup">
        <strong style="display:block; font-size:13px; margin-bottom:var(--space-6);">Add a link for ${esc(label)}</strong>
        <p style="color:var(--muted); font-size:var(--text-xs);">Paste the URL once and it's saved — synced across the team like everything else here.</p>
        <input type="url" id="embedUrlInput-${key}" placeholder="https://...">
        <button class="primary-button" id="embedSaveBtn-${key}">Save &amp; open</button>
      </div>`;
    document.getElementById(`embedSaveBtn-${key}`).addEventListener("click", () => {
      const val = document.getElementById(`embedUrlInput-${key}`).value.trim();
      if (!val) return;
      const l = loadQuickLinks(); l[key] = val; saveQuickLinks(l);
      renderEmbedView(key);
    });
    return;
  }

  container.innerHTML = `
    <div class="embed-toolbar">
      <span style="font-size:var(--text-xs); color:var(--muted);">${esc(url)}</span>
      <div style="display:flex; gap:var(--space-8);">
        <a class="secondary-button" href="${esc(url)}" target="_blank" rel="noopener">Open in new tab ↗</a>
        <button class="secondary-button" id="embedChangeBtn-${key}">Change URL</button>
      </div>
    </div>
    <div class="embed-frame-box" id="embedFrameBox-${key}">
      <iframe id="embedFrame-${key}" src="${esc(url)}" title="${esc(label)}" referrerpolicy="no-referrer" sandbox="allow-scripts allow-same-origin allow-forms allow-popups"></iframe>
    </div>`;
  document.getElementById(`embedChangeBtn-${key}`).addEventListener("click", () => {
    const l = loadQuickLinks(); l[key] = ""; saveQuickLinks(l);
    renderEmbedView(key);
  });

  /* Best-effort block detection only — browsers deliberately don't let JS see whether an
     iframe's content actually rendered when a site sets X-Frame-Options / CSP frame-ancestors,
     so this can't be 100% reliable. It catches the common case (load never fires at all) and
     backs it up with the always-visible "open in new tab" link above for everything else. */
  const frame = document.getElementById(`embedFrame-${key}`);
  let loaded = false;
  frame.addEventListener("load", () => { loaded = true; });
  setTimeout(() => {
    if (loaded) return;
    const box = document.getElementById(`embedFrameBox-${key}`);
    if (!box) return;
    box.innerHTML = `
      <div class="embed-fallback">
        <div style="font-size:28px;">▣</div>
        <strong style="font-size:12px;">${esc(label)} won't load in an embedded view</strong>
        <p style="color:var(--muted); font-size:var(--text-xs); max-width:360px;">That site is blocking embedding on its end (an X-Frame-Options or CSP header it controls) — that's not something fixable from here.</p>
        <a class="primary-button" href="${esc(url)}" target="_blank" rel="noopener">Open in new tab ↗</a>
      </div>`;
  }, 4000);
}
