function deleteContractFromServer(key) { try { return fetch(contractServerUrl(key), { method: "DELETE" }).then(() => true).catch(() => false); } catch (e) { return Promise.resolve(false); } }
function loadContracts() { try { return JSON.parse(memStore.getItem(CONTRACT_KEY)) || {}; } catch { return {}; } }
