          r.unrecoverable.forEach(removeAgreementByMetaId);
          toast("Cleared", `${r.unrecoverable.length} unrecoverable agreement${r.unrecoverable.length === 1 ? "" : "s"} removed — re-upload when ready.`, true);
          if (typeof refreshCurrentView === "function") refreshCurrentView();
