/* Board item #35 — structured contacts migration (decision: migrate primary -> contacts[0],
   keep primary synced going forward). Runs once per shared dataset: for every sponsor
   (base + custom) that has no contacts[] yet but does have a primary name and/or email,
   seed contacts = [{name: primary, email, phone: ""}] as an override so it syncs cross-browser
   like everything else. Idempotent — only fills records that are still missing contacts, so it's
   safe even if it runs again before the "done" flag has propagated to every browser. Editing
   contacts[0] in the Sponsor Ledger drawer already writes primary/email back in sync (see
   openDrawer's save handler) — that part didn't need new code. */
const CONTACTS_MIGRATION_KEY = "bciq_contacts_migrated_v1";
(function migrateContactsFromPrimary() {
  if (memStore.getItem(CONTACTS_MIGRATION_KEY) === "1") return;
  const overrides = loadOverrides();
  const custom = loadCustom();
  const allBase = [...BASE_DATA, ...custom];
  let migrated = false;
  allBase.forEach(base => {
    const existing = overrides[base.id] || {};
    const hasContacts = Array.isArray(existing.contacts) && existing.contacts.length
      ? true
      : Array.isArray(base.contacts) && base.contacts.length;
    if (hasContacts) return;
    const primary = existing.primary !== undefined ? existing.primary : base.primary;
    const email = existing.email !== undefined ? existing.email : base.email;
    if (!primary && !email) return;
    overrides[base.id] = { ...existing, contacts: [{ name: primary || "", email: email || "", phone: "" }] };
    migrated = true;
  });
  if (migrated) {
    saveOverrides(overrides);
    /* DATA-SAFETY FIX (v2026.08.07) — DO NOT broadcast this migration to the shared server.
       The old code pushed { __state: overrides[id] } (a whole-record REPLACE) for EVERY sponsor,
       synchronously at boot, before the first pull ever landed. On a fresh browser `overrides`
       is seed-derived (contacts synthesized from primary/email), so those ~96 whole-record writes
       reached the server and silently overwrote colleagues' real edited sponsor records ~40s after
       load — reproduced last night (4 of 5 edited sponsors destroyed). This migration is a LOCAL,
       deterministic derivation: every browser computes the same contacts from the same seed, so it
       never needed to sync. Removing the push keeps colleagues' edits safe AND clears the permanent
       "Saving 0 of 96…" pill those queued writes caused. Any genuine future edit still syncs the
       normal way via updateOverride. */
    try { window.PatchLog && PatchLog.log("contacts migration ran locally (not broadcast to server)", { area: "persist", migrated: true }); } catch (e) {}
  }
  memStore.setItem(CONTACTS_MIGRATION_KEY, "1");
})();

