function loadAssetDetails() { try { return JSON.parse(memStore.getItem(ASSET_DETAILS_KEY)) || {}; } catch { return {}; } }
function saveAssetDetails(d) { memStore.setItem(ASSET_DETAILS_KEY, JSON.stringify(d)); pushSharedData("assetDetails", { value: JSON.stringify(d) }); }
function assetDetailsKey(name) { return String(name || "").trim().toLowerCase(); }
function assetDetailsFor(name) { return loadAssetDetails()[assetDetailsKey(name)] || {}; }
