function computePortfolioTrend() {
  // Realized history only — future season years only carry the handful of
  // accounts with multi-year deals already signed, so their totals are
  // structurally partial and would read as a fake "decline" if charted
  // alongside fully-booked past seasons.
  const ceiling = Number(sState.season) || new Date().getFullYear();
  const totals = new Map();
  getAllRecords().forEach(r => {
    seasonRecordsFor(r).forEach(({ year, total }) => {
      if (!total || Number(year) > ceiling) return;
      totals.set(year, (totals.get(year) || 0) + total);
    });
  });
  return [...totals.entries()].map(([year, total]) => ({ year, total })).sort((a, b) => Number(a.year) - Number(b.year)).slice(-6);
}
function renderTrendChart() {
  const body = document.getElementById("trendChartBody");
  const summary = document.getElementById("trendSummary");
  if (!body || !summary) return;
  const data = computePortfolioTrend();
  if (data.length < 2) {
    body.innerHTML = `<p style="color:var(--muted); font-size:var(--text-xs); margin:0;">Not enough season history on file yet to chart a trend — add prior-season values to sponsor records to populate this.</p>`;
    summary.innerHTML = "";
    return;
  }
  const W = 640, H = 190, padL = 8, padR = 8, padT = 10, padB = 24;
  const max = Math.max(...data.map(d => d.total));
  const min = Math.min(0, ...data.map(d => d.total));
  const xStep = (W - padL - padR) / (data.length - 1);
  const yFor = v => H - padB - ((v - min) / (max - min || 1)) * (H - padT - padB);
  const pts = data.map((d, i) => [padL + i * xStep, yFor(d.total)]);
  const linePath = pts.map((p, i) => (i === 0 ? "M" : "L") + p[0].toFixed(1) + " " + p[1].toFixed(1)).join(" ");
  const areaPath = linePath + ` L${pts[pts.length - 1][0].toFixed(1)} ${H - padB} L${pts[0][0].toFixed(1)} ${H - padB} Z`;
  /* art-direct: one ruled ground, in ink, at the true zero — not three faint library gridlines
     nobody reads a value off. */
  const baseY = yFor(0).toFixed(1);
  const gridLines = `<line class="zero-line" x1="${padL}" x2="${W - padR}" y1="${baseY}" y2="${baseY}" />`;
  const lineLen = Math.round(pts.reduce((s, p, i) => i ? s + Math.hypot(p[0] - pts[i - 1][0], p[1] - pts[i - 1][1]) : 0, 0)) || W;
  const points = pts.map((p, i) => `<circle class="chart-point" cx="${p[0].toFixed(1)}" cy="${p[1].toFixed(1)}" r="4" style="animation-delay:${(0.55 + i * 0.09).toFixed(2)}s"></circle>`).join("");
  /* Year labels and hit targets live in HTML, not in the stretched SVG, so they render at
     the real font and a hover reads out the value immediately instead of waiting on a
     native tooltip. Positioned as a percentage of the same x-scale the line uses. */
  const xPct = i => ((pts[i][0] - padL) / (W - padL - padR)) * 100;
  const yPct = i => (pts[i][1] / H) * 100;
  const labels = data.map((d, i) =>
    `<span class="trend-year" style="left:${xPct(i).toFixed(2)}%">${esc(d.year)}</span>`).join("");
  const hits = data.map((d, i) => {
    const prior = i ? data[i - 1].total : null;
    const delta = prior ? Math.round(((d.total - prior) / prior) * 100) : null;
    return `<button type="button" class="trend-hit" data-trend="${i}"
      style="left:${xPct(i).toFixed(2)}%; top:${yPct(i).toFixed(2)}%"
      aria-label="${esc(d.year)}: ${esc(fmtMoney(d.total))}">
      <span class="trend-readout">
        <b>${esc(d.year)}</b>
        <em>${esc(fmtMoney(d.total))}</em>
        ${delta === null ? "" : `<i class="trend-delta-${delta >= 0 ? "up" : "down"}">${delta >= 0 ? "+" : ""}${delta}% vs ${esc(data[i - 1].year)}</i>`}
      </span>
    </button>`;
  }).join("");
  const lastPt = pts[pts.length - 1];
  const lastData = data[data.length - 1];
  /* art-direct: print the value where the line actually ends, in the plot itself, so the number
     is read off the mark rather than an axis or a hover-only tooltip. */
  const endLabel = `<span class="trend-endlabel" style="left:${xPct(pts.length - 1).toFixed(2)}%; top:${yPct(pts.length - 1).toFixed(2)}%">${esc(fmtMoneyShort(lastData.total))}</span>`;
  body.innerHTML = `<div class="trend-plot">`
    + `<svg viewBox="0 0 ${W} ${H - padB}" preserveAspectRatio="none" aria-hidden="true">${gridLines}`
    + `<path class="area" fill="var(--blue)" d="${areaPath}" />`
    + `<path class="line" style="--line-len:${lineLen}" d="${linePath}" />${points}</svg>`
    + `${hits}${endLabel}</div><div class="trend-axis">${labels}</div>`;
  const latest = data[data.length - 1], prior = data[data.length - 2];
  const delta = prior.total ? Math.round((latest.total - prior.total) / prior.total * 100) : null;
  summary.innerHTML = `<strong>${fmtMoneyShort(latest.total)}</strong><span class="${delta === null ? "neutral" : delta >= 0 ? "positive" : "negative"}">${delta === null ? latest.year + " season" : (delta >= 0 ? "+" : "") + delta + "% vs " + prior.year}</span>`;
  animateNumberEl(summary.querySelector("strong"));
}
function hasPriorSeasonRecord(r) {
  // "Prior season" = any season record (historicalValues or seasons[]) strictly before
  // the currently selected season. Used to auto-flag brand-new partners who have no
  // season on file before this one, so Renewal Outlook doesn't default them into a
  // renewal-probability bucket that assumes a track record.
  const current = Number(sState.season) || new Date().getFullYear();
  const years = new Set();
  getHistoricalValues(r).forEach(h => { const y = String(h.year || "").trim(); if (/^\d{4}$/.test(y)) years.add(Number(y)); });
  (Array.isArray(r.seasons) ? r.seasons : []).forEach(y => { const yr = String(y || "").trim(); if (/^\d{4}$/.test(yr)) years.add(Number(yr)); });
  return [...years].some(y => y < current);
}
