function selectedSeasonRecord(r) { return agreementSeasonRecordsFor(r).find(s => String(s.year) === String(sState.season)); }
function selectedSeasonTotal(r) { const rec = selectedSeasonRecord(r); return rec ? Number(rec.total || 0) : 0; }
