  if (!anyTotal) gaps.push({ key: "totals", label: "Agreement total", hint: "Add the season row and its value." });
  if (!(r.paymentSchedule && r.paymentSchedule.length)) gaps.push({ key: "payments", label: "Payment schedule", hint: "Dates and amounts from the agreement." });
