  const chartEl = document.getElementById("sponsorTimelineChart");
  if (!statsEl || !chartEl) return;
  const entries = getHistoricalValues(r).filter(h => h.year).map(h => ({ year: parseInt(h.year, 10), value: historicalValueNum(h) })).filter(h => !isNaN(h.year)).sort((a, b) => a.year - b.year);
