  const notes = [];
  if (!isNaN(override)) return { score: clampPct(override), overridden: true, notes: ["Manual override in sponsor drawer"] };
  const outlook = outlookOf(r);
  // New partners have no prior season to measure a renewal rate against — showing a
  // number here would imply a track record that doesn't exist yet.
  if (outlook === "newpartner") return { score: null, overridden: false, notes: ["New partner — no prior season on file, renewal odds not applicable"] };
  let score = OUTLOOK_PROBABILITY[outlook] ?? 50;
  notes.push(`${OUTLOOK_LABELS[outlook]} base: ${score}%`);
  if (isMultiYearForSelectedSeason(r)) { score += 8; notes.push("Multi-year season record: +8"); }
  if (hasSeason(r, String(Number(sState.season) + 1))) { score += 10; notes.push(`Future ${Number(sState.season) + 1} season already on file: +10`); }
  if (isActiveForSelectedSeason(r)) { score += 4; notes.push(`Active Partner in ${sState.season}: +4`); }
  else { score -= 8; notes.push(`No ${sState.season} season row yet: -8`); }
