  if (profile && profile.streak >= 3) { score += Math.min(10, profile.streak * 2); notes.push(`${profile.streak}-season relationship streak: +${Math.min(10, profile.streak * 2)}`); }
  // Tenure + lifetime value (item #21) — a 10-year relationship or a high-dollar
