  if (profile && profile.seasons >= 8) { score += 8; notes.push(`${profile.seasons}-season tenure: +8`); }
  else if (profile && profile.seasons >= 5) { score += 5; notes.push(`${profile.seasons}-season tenure: +5`); }
  else if (profile && profile.seasons >= 3) { score += 2; notes.push(`${profile.seasons}-season tenure: +2`); }
  if (profile && profile.lifetime >= 200000) { score += 5; notes.push(`Lifetime value $200K+: +5`); }
