function toast(title, msg, isInfo) {
  const t = document.getElementById("toast");
  document.getElementById("toastTitle").textContent = title;
  document.getElementById("toastMessage").textContent = msg || "";
  document.getElementById("toastIcon").className = isInfo ? "info-ico" : "";
  /* index213: error/status toasts now announce assertively to screen readers and stay 7s;
     info confirmations stay 3.5s. Hovering pauses the timer so nothing vanishes mid-read. */
  t.setAttribute("role", isInfo ? "status" : "alert");
  t.classList.add("show");
  clearTimeout(toast._tm);
  clearTimeout(toast._hardTm);
  const dur = isInfo ? 3500 : 7000;
  toast._tm = setTimeout(() => t.classList.remove("show"), dur);
  if (!t.dataset.hoverWired) {
    t.dataset.hoverWired = "1";
    /* index243: hovering paused the dismiss timer with no ceiling, so a toast the pointer
       happened to rest on stayed up forever — and while it was up it covered whatever was
       underneath it. Hover still pauses, but never past 30 seconds total. */
    t.addEventListener("mouseenter", () => {
      clearTimeout(toast._tm);
      clearTimeout(toast._hardTm);
      toast._hardTm = setTimeout(() => t.classList.remove("show"), 30000);
    });
    t.addEventListener("mouseleave", () => {
      clearTimeout(toast._hardTm);
      toast._tm = setTimeout(() => t.classList.remove("show"), 1800);
    });
  }
}
