/* ---- site map, generated LIVE from the view list so it never goes stale ---- */
const SITEMAP_CHAPTERS = [
  ["overview-hub","Executive Overview"],
  ["accounts-hub","Ledgers"],
  ["sales-hub","Sales Center"],
  ["service-hub","Service Center"],
  ["assets-hub","Ballpark & Allocation"],
  ["tasks-hub","Tasks & Approvals"],
  ["agreements-hub","Agreements"]
];
function buildSitemapDoc(){
  /* index213: the map is now a MAP — a top-down metro-style diagram. The two bases sit at the
     top as termini of two colored rails (blue = sponsor base, gold = asset base); every page in
     the app is a station on the rails it actually reads, with its page-specific synced stores as
     chips. Still 100% introspected from the running code the moment it opens:
       - pages from VIEW_TITLES / VIEW_CHAPTER (add a view, it appears as a station);
       - what each page reads by scanning that page's own render functions via showView's source;
       - channels + live byte counts from the whole-store registry and this browser's store;
       - the build number from the BUILD_VERSION marker the deploy pipeline stamps.
     Nothing here is hand-written page data; it cannot go stale. */
  var esc=function(x){return String(x==null?"":x).replace(/[&<>]/g,function(c){return {"&":"&amp;","<":"&lt;",">":"&gt;"}[c];});};

  var build="";
  try{ for(var i=0;i<document.childNodes.length;i++){ var n=document.childNodes[i]; if(n.nodeType===8){ var m=String(n.nodeValue).match(/BUILD_VERSION:\s*(\d+)/); if(m){ build=m[1]; break; } } } }catch(e){}

  /* which data a chunk of code touches, by the identifiers it uses.
     kind: s = sponsor rail · a = asset rail · c = chip (page-specific store) · d = derived/live · x = external */
  var TOKENS=[
    [/getAllRecords|getRecord\(|SPONSOR_DATA|loadOverrides\(|updateOverride/,"Sponsor base","s","Sponsor base"],
    [/loadLogos|logoFor\(|LOGO_KEY/,"Sponsor logos","s","Logos"],
    [/getFullCatalog|ASSET_CATALOG|loadCustomAssets/,"Asset catalog","a","Asset catalog"],
    [/lookupRate|loadRates\(|RATES_KEY/,"Asset rates","a","Rates"],
    [/assetDetailsFor|ASSET_DETAILS_KEY/,"Asset details","a","Details"],
    [/assetSpecFor|ASSET_SPEC_KEY|asset_specs_v2|alLibEntryFor/,"Asset specs","a","Specs"],
    [/PREP_TEMPLATE_KEY|prep_templates/,"Prep templates","a","Prep templates"],
    [/agFindTemplate|AGREEMENT_TEMPLATES_KEY/,"Agreement templates","a","Contract language"],
    [/loadOptions\(|OPTIONS_KEY|CURRENT_OPTION_KEY/,"Proposals","c","Proposals"],
    [/loadDecks|DECKS_KEY/,"Digideck links","c","Decks"],
    [/REPORT_OVERRIDES_KEY|reportOverride/,"Report checklist","c","Report checklist"],
    [/loadRequests|REQUESTS_KEY|APPROVAL_CONFIG_KEY|loadApprovalConfig/,"Requests & approvals","c","Requests & approvals"],
    [/STAFF_SCHEDULE_KEY|staff_schedule/,"Staff schedule","c","Staff schedule"],
    [/SQUAD_KEY|squad_schedule|squadLoad/,"Squad schedule","c","Squad schedule"],
    [/scoreboard_layout|SCOREBOARD_KEY/,"Scoreboard layout","c","Board layout"],
    [/marquee_schedule|MARQUEE_KEY/,"Marquee schedule","c","Marquee schedule"],
    [/enews_schedule|ENEWS_KEY/,"E-news schedule","c","E-news schedule"],
    [/asset_alloc_v1|AA_STORE_KEY/,"Asset-allocation board","c","Allocation board"],
    [/loadPhotoLibrary|PHOTO_LIBRARY_KEY|PHOTO_CHECK_KEY/,"Photo library","c","Photos"],
    [/loadBallparkDisplays|BALLPARK_KEY/,"Ballpark boards","c","Ballpark boards"],
    [/CONTRACT_KEY|CONTRACT_BODIES_KEY|sponsor_contracts/,"Contracts","c","Contracts"],
    [/bciq_daily_notes|dailyNotes/,"Daily notes","c","Daily notes"],
    [/STAGE_PROB_KEY|stage_probs|loadStageProbs/,"Stage weights","c","Stage weights"],
    [/BLUECLAWS_2026_GAMES|gatherCalendarEvents/,"Game schedule seed","d","live game schedule"],
    [/bciqRecent\(|bciqChanged\(|bciqNeedsAttention\(|renderHistory\b/,"Change feed","d","live change feed — no store"],
    [/renderEmbedView/,"External embed","x","external site in a frame"]
  ];
  function fnSource(name){ try{ var f=window[name]; return typeof f==="function"?String(f):""; }catch(e){ return ""; } }
  function expandSource(src,depth,seen){
    if(!src||depth<=0||seen.__n>2500) return src||"";
    var out=src, ids=src.match(/\b[a-zA-Z_$][\w$]{2,40}(?=\s*\()/g)||[];
    for(var i=0;i<ids.length;i++){
      var id=ids[i]; if(seen[id])continue; seen[id]=1; seen.__n=(seen.__n||0)+1;
      /* follow READ paths only — cutting at interaction/write functions (open a drawer, save,
         push, toast) keeps a page's dots honest: what it DISPLAYS, not everywhere a click
         could eventually lead. */
      if(/^(open|close|toast|refresh|show|save|push|queue|flush|export|import|delete|reset|persist|bc[A-Z])/.test(id)) continue;
      var s=fnSource(id); if(s) out+="\n"+expandSource(s,depth-1,seen);
    }
    return out;
  }
  var viewSrc={};
  String(showView).split(/(?=if\s*\(\s*name\s*===)/).forEach(function(line){
    var views=[], vm, vre=/name\s*===\s*"([a-z-]+)"/g, head=line.slice(0,220);
    while((vm=vre.exec(head))) views.push(vm[1]);
    if(!views.length) return;
    var ids=(line.match(/\b[a-zA-Z_$][\w$]*(?=\s*\()/g)||[]).filter(function(id){
      return !/^(if|name|showView|String|console|setTimeout|requestAnimationFrame|escDisplay|getElementById|collapseSidebar|typeof)$/.test(id) && typeof window[id]==="function";
    });
    views.forEach(function(v){ viewSrc[v]=(viewSrc[v]||"")+"\n"+ids.map(function(id){ return expandSource(fnSource(id),4,{}); }).join("\n"); });
  });
  function readsFor(view){
    var src=viewSrc[view]||"", out=[];
    for(var i=0;i<TOKENS.length;i++){ if(TOKENS[i][0].test(src)) out.push({label:TOKENS[i][1],kind:TOKENS[i][2],short:TOKENS[i][3]}); }
    return out;
  }

  var channels={}; try{ channels=getWholeStoreChannels(); }catch(e){}
  var allViewSrc=Object.keys(viewSrc).map(function(v){return viewSrc[v];}).join("\n");
  ["renderSideChat","renderChatRooms","renderQuickLinks","renderFavoriteActions","updateTaskAlert"].forEach(function(id){ allViewSrc+="\n"+fnSource(id); });
  function kb(n){ return n>=1024?(n/1024).toFixed(1)+" KB":(n+" B"); }
  var chanRows=Object.keys(channels).sort().map(function(id){
    var key=channels[id], raw=null; try{ raw=memStore.getItem(key); }catch(e){}
    var size=raw?raw.length:0;
    var claimed=allViewSrc.indexOf(key)>=0||allViewSrc.indexOf(id)>=0;
    return '<tr><td><b>'+esc(id)+'</b><br><code>'+esc(key)+'</code></td><td>'+(raw===null?'<span class="dim">empty here</span>':kb(size))+'</td><td>'+(claimed?'page-wired':'<span class="dim">background / app-wide</span>')+'</td></tr>';
  }).join("");

  /* ---- the rails map ---- */
  var stations="";
  stations+='<div class="st term term-s"><span class="dot s on"></span><div><b>Sponsor base</b><small>One master record per sponsor — 2026 master sheet seed + your edits + custom sponsors + logos. Edited only in the Sponsor Ledger drawer; every blue-dot page below just reads it.</small></div></div>';
  stations+='<div class="st term term-a"><span class="dot a on"></span><div><b>Asset base</b><small>One record per sellable asset — 274-item catalog + rates + details + specs + contract language. Edited only in the Asset Ledger; every gold-dot page below just reads it.</small></div></div>';
  /* index227: the chapter list is now READ OFF THE LIVE NAV, not the hardcoded SITEMAP_CHAPTERS
     constant. Rename a chapter, reorder it, or add a whole new one in the sidebar markup and the
     map follows on its own — the constant is only a fallback for the case where the nav has not
     rendered yet. Any view that owns a section but is not reachable from the nav is collected
     afterwards and shown under "Not in the nav", so orphan pages can never hide from the map. */
  var chapterPairs=(function(){
    var fromDom=[].slice.call(document.querySelectorAll('.nav-chapter[data-chapter]')).map(function(node){
      var id=node.getAttribute('data-chapter')||"";
      var head=node.querySelector('.chapter-head');
      var label=head?String(head.textContent||"").replace(/\s+/g," ").trim():"";
      return (id&&label)?[id,label]:null;
    }).filter(Boolean);
    return fromDom.length?fromDom:SITEMAP_CHAPTERS;
  })();
  var mappedViews={};
  chapterPairs.forEach(function(pair){
    var id=pair[0], label=pair[1];
    var views=Object.keys(VIEW_TITLES).filter(function(v){ return VIEW_CHAPTER[v]===id && document.getElementById(v+"View"); });
    if(!views.length) return;
    views.forEach(function(v){ mappedViews[v]=1; });
    stations+='<div class="chap">'+esc(label)+'</div>';
    views.forEach(function(v){
      var reads=readsFor(v);
      var hasS=reads.some(function(r){return r.kind==="s";});
      var hasA=reads.some(function(r){return r.kind==="a";});
      var chips=reads.filter(function(r){return r.kind==="c";}).map(function(r){return '<span class="chip">'+esc(r.short)+'</span>';}).join("");
      var derived=reads.filter(function(r){return r.kind==="d"||r.kind==="x";}).map(function(r){return '<em class="drv">'+esc(r.short)+'</em>';}).join(" ");
      var dots='<span class="dot s'+(hasS?' on':'')+'"></span><span class="dot a'+(hasA?' on':'')+'"></span>';
      return stations+=('<div class="st">'+dots+'<b>'+esc(VIEW_TITLES[v])+'</b><code>'+esc(v)+'</code>'+chips+derived+'</div>');
    });
  });
  /* Orphans: a real section in the document that no nav chapter claims. These are reachable only
     by deep link, quick search or a chat ref, so the map is the only place they surface at all. */
  (function(){
    var orphans=[].slice.call(document.querySelectorAll('.view[id$="View"]')).map(function(sec){
      return String(sec.id).replace(/View$/,"");
    }).filter(function(v){
      return v && v!=="x" && !mappedViews[v] && document.getElementById(v+"View");
    });
    if(!orphans.length) return;
    stations+='<div class="chap">Not in the nav</div>';
    orphans.forEach(function(v){
      var reads=readsFor(v);
      var hasS=reads.some(function(r){return r.kind==="s";});
      var hasA=reads.some(function(r){return r.kind==="a";});
      var chips=reads.filter(function(r){return r.kind==="c";}).map(function(r){return '<span class="chip">'+esc(r.short)+'</span>';}).join("");
      var dots='<span class="dot s'+(hasS?' on':'')+'"></span><span class="dot a'+(hasA?' on':'')+'"></span>';
      stations+='<div class="st"><span class="dot s'+(hasS?' on':'')+'"></span><span class="dot a'+(hasA?' on':'')+'"></span><b>'+esc(VIEW_TITLES[v]||v)+'</b><code>'+esc(v)+'</code>'+chips+'</div>';
    });
  })();

  var spine='<div class="spinewrap"><div class="eyebrow2">How a save travels</div><div class="spine">'
    +'<div class="sn"><b>Your browser</b><small>saves instantly — works offline</small></div><span class="arr">→</span>'
    +'<div class="sn"><b>Save queue</b><small>retries until it lands; a 30s grace window stops the poll from undoing you</small></div><span class="arr">→</span>'
    +'<div class="sn"><b>Netlify Blobs</b><small>overrides every 8s · logos / displays / photos / contracts every 60s · '+Object.keys(channels).length+' channels ride overrides</small></div><span class="arr">→</span>'
    +'<div class="sn"><b>Every teammate</b><small>polls, merges race-safe, and repaints the open page</small></div>'
    +'</div><p class="note">Opened as a plain file (no server), everything still works and quietly stays on that browser — by design.</p></div>';

  var frontPage='<section class="front"><h2>The front page, traced</h2><table>'
    +'<tr><th>Front-page box</th><th>Where it comes from</th><th>Where it saves</th></tr>'
    +'<tr><td><b>Needs attention</b></td><td>Computed live: renewal-risk wording, open to-dos and low fulfillment on active sponsor records</td><td>Nothing — it&rsquo;s a live read, no store</td></tr>'
    +'<tr><td><b>Recently updated</b></td><td>Each record&rsquo;s <code>updatedAt</code>, diffed field-by-field against the seed — edits from any browser surface here</td><td>Nothing — derived on every 30s refresh</td></tr>'
    +'<tr><td><b>Daily notes</b></td><td>Shared <code>dailyNotes</code> channel (overrides bucket)</td><td>This browser instantly, the server within seconds — follows the team to every browser</td></tr>'
    +'<tr><td><b>History log</b></td><td>Same change feed as &ldquo;Recently updated&rdquo;, full-length, grouped by day, searchable</td><td>Nothing — derived; a true event stream is a known future upgrade</td></tr>'
    +'<tr><td><b>Schedule rail</b></td><td>Rolling 14-day rail with the real 2026 home games marked from the game-schedule seed</td><td>Nothing</td></tr>'
    +'</table></section>';

  var chanSection='<details class="front chdet"><summary><h2 style="display:inline;">Every synced channel, live</h2> <span class="dim">(what&rsquo;s actually in this browser right now)</span></summary><table style="margin-top:10px;"><tr><th>Channel</th><th>In this browser now</th><th>Read by</th></tr>'+chanRows+'</table></details>';

  /* index257 — THE HANDOFF SECTION.
     This document already explains how the app works. It never explained how to ship it, which
     is the part that dies with the person who built it. Everything below is what a successor
     needs on day one and cannot infer from the code. */
  var handoff='<section class="front"><h2>If you are taking this over</h2>'
    +'<p class="dim" style="margin:0 0 10px;">This app is one HTML file. There is no build step, no framework and no server of its own — everything you need is in the file you are reading about, plus three small Netlify Functions.</p>'
    +'<h3 style="margin:14px 0 4px;">Shipping a change</h3>'
    +'<ol class="cav">'
    +'<li>Every file handed back is named <code>indexNN.html</code>, exactly one higher than the file it was worked from. Never edit <code>index.html</code> by hand.</li>'
    +'<li>Commit the new <code>indexNN.html</code> to <code>mitchellzavoda123/blueclaws</code>. A GitHub Action runs <code>promote-index.sh</code>, which copies the highest-numbered index file over <code>index.html</code>, and Netlify deploys it to <b>blueclaws26.netlify.app</b>.</li>'
    +'<li>Use <code>[skip actions]</code> in a commit message to skip the promote step. Do <b>not</b> use <code>[skip ci]</code> — that also skips the Netlify deploy, so nothing ships.</li>'
    +'<li>Update <code>&lt;!-- BUILD_VERSION: NN --&gt;</code> on line 2 and add an entry to <code>BUILD_NOTES</code>. Three surfaces print that number; if you skip it they all describe the wrong build.</li>'
    +'</ol>'
    +'<h3 style="margin:14px 0 4px;">Where the data actually is</h3>'
    +'<ul class="cav">'
    +'<li>Nothing is in the HTML except the original seed import. Live data lives in <b>Netlify Blobs</b>, reached through <code>/.netlify/functions/data</code> (and <code>/media</code>, <code>/contracts</code>). This browser keeps a copy in localStorage and IndexedDB.</li>'
    +'<li>Real buckets: <code>overrides</code>, <code>logos</code>, <code>photos</code>, <code>displays</code>. Around two dozen whole-store channels ride the <code>overrides</code> bucket. <b>Every bucket must be listed in the deployed function\'s <code>VALID_BUCKETS</code> allowlist</b> — if it is not, pulls fail silently and it looks like a sync bug in the app.</li>'
    +'<li>Contract PDFs are the exception: bodies go to <code>/.netlify/functions/contracts</code> and the metadata rides the sponsor override record. There is no <code>contracts</code> bucket on the data function.</li>'
    +'<li>Sync only works from the deployed URL. Opening the file from your desktop (<code>file://</code>) falls back to this browser only and <b>says nothing about it</b>. Before chasing any sync bug, confirm which one you are looking at.</li>'
    +'<li>Photos are in IndexedDB, not localStorage — hundreds of base64 images used to blow the quota and cause partial saves. Logos have their own key and must never be written into sponsor overrides.</li>'
    +'</ul>'
    +'<h3 style="margin:14px 0 4px;">Before you change anything</h3>'
    +'<ul class="cav">'
    +'<li>Take a Backup (the &#8635; in the topbar) first. Claude and any other tool can only see the seed baked into the file — live edits, logos and overrides are invisible without that export.</li>'
    +'<li>Ctrl+Shift+L opens the PatchLog: every error this browser has recorded, exportable as JSON. Start there when something is wrong.</li>'
    +'<li>The design rules are not preferences. Four colours (navy #0d1d41, blue #0971ce, red #c20f2f, gold #facd01) on warm paper, no green, two typefaces (Manrope and DM Sans), borders instead of shadows, and one gradient — the blue/gold/red stripe.</li>'
    +'</ul></section>';

  var caveats='<section class="front"><h2>Honest footnotes</h2><ul class="cav">'
    +'<li>Asset rates still live in two stores (<code>bciq_asset_rates</code> vs the rate inside asset details). Display prefers the detail rate. Build 257 routed the picker\'s sort and its &ldquo;+ Add&rdquo; price through one <code>resolvedRate()</code> helper so all three agree, but the two stores are still two stores. Merging them changes proposal math — parked for a decision.</li>'
    +'<li>Digidecks link to sponsors by <b>name</b>; requests, agreements and photos link by <b>id</b>. The deck/proposal sponsor fields are dropdowns so the names can&rsquo;t drift.</li>'
    +'<li>The two near-identical quick-link stores were unified in build 211; the old store remains only so older builds elsewhere keep working. Build 257 stopped the legacy store re-filling a link you deliberately cleared.</li>'
    +'</ul></section>';

  return '<!DOCTYPE html><html><head><meta charset="utf-8">'
    +'<link rel="preconnect" href="https://fonts.googleapis.com"><link href="https://fonts.googleapis.com/css2?family=Manrope:wght@700;800&family=DM+Sans:wght@400;500;700&display=swap" rel="stylesheet">'
    +'<style>'
    +'body{margin:0;padding:22px;background:#f5f3ee;color:#0d1d41;font:13.5px/1.5 "DM Sans",system-ui,sans-serif;}'
    +'h1{font:800 20px/1.2 "Manrope",sans-serif;margin:0 0 2px;}p.lede{margin:0 0 14px;color:#5b6472;font-size:12px;}'
    +'.buildpill{display:inline-block;background:#0d1d41;color:#fff;font:700 10px "DM Sans";padding:2px 8px;border-radius:999px;margin-left:8px;vertical-align:2px;}'
    +'.legend{display:flex;gap:14px;flex-wrap:wrap;align-items:center;font-size:11px;color:#33415e;margin:0 0 12px;}'
    +'.legend .dot{position:static;display:inline-block;vertical-align:-1px;margin-right:4px;}'
    +'.map{position:relative;padding-left:58px;margin:0 0 20px;}'
    +'.map::before{content:"";position:absolute;left:16px;top:18px;bottom:10px;width:3px;background:#0971ce;border-radius:0;opacity:.85;}'
    +'.map::after{content:"";position:absolute;left:38px;top:64px;bottom:10px;width:3px;background:#facd01;border-radius:0;}'
    +'.st{position:relative;margin:0 0 6px;background:#fff;border:1px solid rgba(13,29,65,.14);border-radius:8px;padding:7px 12px;display:flex;align-items:baseline;gap:8px;flex-wrap:wrap;}'
    +'.dot{position:absolute;top:12px;width:9px;height:9px;border-radius:50%;background:#f5f3ee;border:2.5px solid rgba(13,29,65,.15);box-sizing:content-box;}'
    +'.dot.s{left:-46px;}.dot.a{left:-24px;}'
    +'.dot.s.on{background:#0971ce;border-color:#0a4f8f;}'
    +'.dot.a.on{background:#facd01;border-color:#b8860b;}'
    +'.st b{font:700 13px "DM Sans";}'
    +'.st code{background:#eef1f8;color:#0971ce;padding:1px 5px;border-radius:var(--radius-xs);font-size:10px;}'
    +'.st .chip{display:inline-block;background:#f5f3ee;border:1px solid rgba(13,29,65,.12);border-radius:6px;padding:0 7px;font-size:10.5px;color:#33415e;}'
    +'.st .drv{font-size:10.5px;color:#8a93a6;}'
    +'.st.term{border-width:2px;padding:10px 14px;align-items:flex-start;}'
    +'.st.term-s{border-color:#0971ce;}.st.term-a{border-color:#b8860b;}'
    +'.st.term .dot{top:15px;width:13px;height:13px;}.st.term .dot.s{left:-48px;}.st.term.term-a .dot.a{left:-26px;}'
    +'.st.term b{font:800 15px "Manrope",sans-serif;display:block;}'
    +'.st.term small{color:#5b6472;font-size:11.5px;line-height:1.45;display:block;margin-top:2px;}'
    +'.st.term-s .dot.a,.st.term-a .dot.s{display:none;}'
    +'.chap{font:800 10px "DM Sans";letter-spacing:.13em;text-transform:uppercase;color:#c20f2f;margin:14px 0 6px;}'
    +'.eyebrow2{font:800 10px "DM Sans";letter-spacing:.13em;text-transform:uppercase;color:#0971ce;margin:0 0 8px;}'
    +'.spinewrap{border:1px solid rgba(13,29,65,.14);border-radius:10px;background:#fff;padding:14px 16px;margin:0 0 16px;}'
    +'.spine{display:flex;gap:10px;align-items:stretch;flex-wrap:wrap;}'
    +'.sn{flex:1 1 150px;min-width:140px;border:1px solid rgba(13,29,65,.14);border-radius:8px;background:#f5f3ee;padding:8px 10px;}'
    +'.sn b{font:700 12.5px "DM Sans";display:block;}'
    +'.sn small{color:#5b6472;font-size:10.5px;line-height:1.4;}'
    +'.arr{align-self:center;color:#0971ce;font-weight:800;font-size:16px;}'
    +'.front{border:1px solid rgba(13,29,65,.14);border-radius:10px;background:#fff;padding:14px 16px;margin:0 0 16px;}'
    +'.front h2{font:800 14px "Manrope",sans-serif;margin:0 0 8px;}'
    +'table{width:100%;border-collapse:collapse;font-size:12px;}'
    +'th,td{text-align:left;padding:7px 8px;border-bottom:1px solid rgba(13,29,65,.08);vertical-align:top;}'
    +'th{font:700 10px "DM Sans";text-transform:uppercase;letter-spacing:.05em;color:#5b6472;}'
    +'tr:last-child td{border-bottom:0;}.dim{color:#8a93a6;font-size:11px;}'
    +'code{background:#eef1f8;color:#0971ce;padding:1px 5px;border-radius:var(--radius-xs);font-size:10.5px;}'
    +'.note{font-size:11.5px;color:#33415e;margin:10px 0 0;}'
    +'.cav{margin:0;padding-left:18px;}.cav li{font-size:12px;margin:0 0 7px;}'
    +'.chdet summary{cursor:pointer;}'
    +'</style></head><body>'
    +'<h1>How BlueClaws IQ connects.'+(build?'<span class="buildpill">BUILD '+esc(build)+'</span>':'')+'</h1>'
    +'<p class="lede">Top down: two bases feed everything. Generated live from the running code every time this opens — pages, connections, channels, and the build number are all read out of the app itself, so this map cannot go stale.</p>'
    +'<div class="legend"><span><span class="dot s on"></span>reads the Sponsor base</span><span><span class="dot a on"></span>reads the Asset base</span><span><span class="chip" style="position:static;">chip</span> = the page&rsquo;s own synced store</span><span><em class="drv">italic</em> = computed live, stored nowhere</span></div>'
    +'<div class="map">'+stations+'</div>'
    +spine
    +frontPage
    +chanSection
    +handoff
    +caveats
    +'</body></html>';
}


/* ===== index208 morning-glance: reads its own edit history in plain English ===== */
function bciqEsc(x){ try{ return esc(x); }catch(e){ return String(x==null?"":x).replace(/[&<>]/g,function(c){return {"&":"&amp;","<":"&lt;",">":"&gt;"}[c];}); } }
function bciqPct(v){ var m=String(v==null?"":v).match(/\d+/); return m?parseInt(m[0],10):0; }
function bciqAgo(iso){ try{ var t=new Date(iso).getTime(); var s=Math.floor((Date.now()-t)/1000); if(s<60)return "just now"; var m=Math.floor(s/60); if(m<60)return m+"m ago"; var h=Math.floor(m/60); if(h<24)return h+"h ago"; return Math.floor(h/24)+"d ago"; }catch(e){ return ""; } }
function bciqAllRecs(){ try{ return getAllRecords(); }catch(e){ return (window.SPONSOR_DATA||[]); } }
function bciqBase(id){ try{ return (window.SPONSOR_DATA||[]).find(function(b){return b.id===id;}); }catch(e){ return null; } }
var BCIQ_FIELDS=[["total","value"],["fulfillmentPct","fulfillment"],["renewalOutlook","renewal outlook"],["rep","rep"],["status","status"],["todo","to-do"],["active","active status"],["notes","notes"],["primary","contact"],["email","contact"],["assets","assets"],["seasons","seasons"]];
function bciqChanged(r){
  var b=bciqBase(r.id); if(!b) return [];
  var out=[], seen={};
  BCIQ_FIELDS.forEach(function(p){ var k=p[0], lab=p[1];
    try{ if(JSON.stringify(r[k])!==JSON.stringify(b[k]) && !seen[lab]){ seen[lab]=1; out.push(lab); } }catch(e){}
  });
  return out;
}
function bciqNeedsAttention(){
  var recs=bciqAllRecs().filter(function(r){ return r && (r.active || r.dealStage==="signed"); });
  return recs.map(function(r){
    var pct=bciqPct(r.fulfillmentPct);
    var risk=/risk|unlikely|lost|not yet|declin|churn/i.test(String(r.renewalOutlook||""));
    var todo=!!(r.todo && String(r.todo).trim());
    var score=(risk?100:0)+(todo?40:0)+(100-pct);
    var why=risk?"renewal risk":(todo?"open to-do":"fulfillment "+pct+"%");
    return {r:r, score:score, keep:(risk||todo||pct<60), why:why};
  }).filter(function(x){return x.keep;}).sort(function(a,b){return b.score-a.score;}).slice(0,2);
}
function bciqRecent(){
  return bciqAllRecs().filter(function(r){ return r && r.updatedAt; })
    .sort(function(a,b){ return String(b.updatedAt).localeCompare(String(a.updatedAt)); }).slice(0,2);
}
function bciqRenderSchedule(){
  var el=document.getElementById("glanceSchedule"); if(!el) return;
  /* index213: the rail now marks the REAL 2026 home games from the game-schedule seed —
     the front page reads the same source the Schedule calendar and Gameday page use. */
  var games={};
  try{
    ((typeof gamesForSeason==="function"?gamesForSeason():BLUECLAWS_2026_GAMES)||[]).forEach(function(g){
      var iso=(typeof gameLabelToIsoForSeason==="function")?gameLabelToIsoForSeason(g.label, sState.season):((typeof gameLabelToIso==="function")?gameLabelToIso(g.label):null);
      if(iso&&!games[iso]) games[iso]={opp:g.opp||"", time:g.time||""};
    });
  }catch(e){}
  var today=new Date(); today.setHours(0,0,0,0);
  var wd=["Sun","Mon","Tue","Wed","Thu","Fri","Sat"], html="";
  /* index226: seven days, not fourteen. Two back for context, today, four forward — that is the
     whole window anyone acts on, and the fortnight rail was both redundant against the sidebar
     homestand card and wide enough to push the real content below the fold. */
  for(var i=-2;i<=4;i++){ var d=new Date(today); d.setDate(today.getDate()+i);
    var isT=d.getTime()===today.getTime(), we=(d.getDay()===0||d.getDay()===6);
    var iso=d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0")+"-"+String(d.getDate()).padStart(2,"0");
    var g=games[iso];
    var gameHtml=g?'<span class="sch-game" title="'+bciqEsc("BlueClaws vs "+(g.opp||"?")+(g.time?" · "+g.time:""))+'">vs '+bciqEsc(g.opp||"—")+'</span>':"";
    html+='<div class="sch-day'+(isT?" today":"")+(we?" we":"")+(g?" has-game":"")+'"><span class="sch-wd">'+wd[d.getDay()]+'</span><span class="sch-dt">'+d.getDate()+'</span>'+(isT?'<span class="sch-tag">Today</span>':gameHtml)+'</div>';
  }
  el.innerHTML=html;
  /* index226: the rail no longer scrolls (7 fixed columns), so the old scrollIntoView on "today"
     is dead weight — and it could nudge the page on load. Removed deliberately. */
}
function bciqLoadNotes(){
  /* index211: daily notes now ride the shared "dailyNotes" channel (overrides bucket) so they
     follow the team across browsers, like everything else. One-time migration pulls whatever
     was in the old this-device localStorage store. Refreshes from sync on every renderGlance
     tick — but never overwrites the box while someone is typing in it. */
  var t=document.getElementById("glanceNotes"); if(!t) return;
  var stored=null;
  try{ stored=memStore.getItem("bciq_daily_notes"); }catch(e){}
  if(stored===null||stored===undefined){
    try{ stored=localStorage.getItem("bciq_daily_notes")||""; if(stored){ memStore.setItem("bciq_daily_notes",stored); pushSharedData("dailyNotes",{value:stored}); } }catch(e){ stored=""; }
  }
  if(document.activeElement!==t && t.value!==(stored||"")) t.value=stored||"";
  if(t.dataset.wired) return;
  t.dataset.wired="1";
  var deb=null;
  /* index242 — this is the app's only true "just type and it saves" field: there is no save
     button to fall back on and no confirmation to notice the absence of. Both writes were
     empty catches, so during a storage problem someone could type a full set of notes and
     lose every word of it in silence. The write is durable now, and the field says so
     inline rather than through a toast that would fire on every keystroke. */
  var noteFlag=document.getElementById("glanceNotesState");
  if(!noteFlag){
    noteFlag=document.createElement("span");
    noteFlag.id="glanceNotesState";
    noteFlag.style.cssText="display:none; font-size:11px; color:var(--red); margin-top:4px;";
    if(t.parentNode) t.parentNode.appendChild(noteFlag);
  }
  t.addEventListener("input",function(){
    var stored=durableSet("bciq_daily_notes",t.value,"your daily notes");
    if(noteFlag){
      noteFlag.style.display = stored==="none" ? "block" : "none";
      if(stored==="none") noteFlag.textContent="Not saved — this browser is out of storage. Copy this text somewhere safe.";
    }
    clearTimeout(deb);
    deb=setTimeout(function(){ try{ pushSharedData("dailyNotes",{value:t.value}); }catch(e){} },900);
  });
}
/* index226: pace to budget. Reads ORG_REVENUE_METRICS, which is real and already in the file
   (sourced from 2026 Budget Build / Deal Analyzer) but was only ever surfaced as a percentage tile.
   The dollar gap is the number that actually gets repeated out loud, so it leads here. Renders
   nothing at all rather than inventing a figure if the metrics block is missing. */
function bciqRenderPace(){
  var el=document.getElementById("pacePanel"); if(!el) return;
  el.style.display="";
  var money=(typeof fmtMoneyShort==="function")?fmtMoneyShort:function(v){return "$"+Math.round(v||0).toLocaleString();};
  var season=String((typeof sState==="object"&&sState.season)||CURRENT_SEASON||"2026");
  var active=(typeof activeSeasonRecords==="function"?activeSeasonRecords(season):[]);
  var signed=active.reduce(function(sum,r){return sum + (typeof selectedSeasonTotal==="function"?selectedSeasonTotal(r):parseTotal(r.total));},0);
  var budget=(typeof budgetForSeason==="function"?budgetForSeason(season):0);
  if(!budget){
    el.classList.remove("is-clear");
    el.innerHTML =
      '<span class="pace-kicker">Pace to budget</span>'+
      '<div class="pace-figure"><span class="pace-num">Budget not set</span></div>'+
      '<div class="pace-bar"><span class="pace-fill" style="width:0%"></span></div>'+
      '<p class="pace-sub"><b>'+bciqEsc(money(signed))+'</b> signed for '+bciqEsc(season)+'. Add a '+bciqEsc(season)+' budget in Settings when ready.</p>';
    return;
  }
  var gap=Math.max(0,budget-signed);
  var pct=budget?Math.min(100,Math.round((signed/budget)*100)):0;
  var pipeline=(typeof pipelineSeasonRecords==="function"?pipelineSeasonRecords(season):[]).filter(function(r){return !active.includes(r)&&/likely|confirmed|contract/i.test(String((typeof outlookOf==="function"?outlookOf(r):r.renewalOutlook)||"")+String(r.dealStage||""));}).reduce(function(sum,r){return sum+(typeof displayValueForSeason==="function"?displayValueForSeason(r,season):parseTotal(r.total));},0);
  var clear=gap<=0;
  el.classList.toggle("is-clear",clear);
  var lead=clear
    ? '<span class="pace-num">'+bciqEsc(money(signed))+'</span><span class="pace-unit">signed — budget cleared.</span>'
    : '<span class="pace-num">'+bciqEsc(money(gap))+'</span><span class="pace-unit">left to close.</span>';
  var tail=pipeline>0&&!clear
    ? ' <b>'+bciqEsc(money(pipeline))+'</b> sits in likely pipeline.'
    : "";
  el.innerHTML =
    '<span class="pace-kicker">Pace to budget</span>'+
    '<div class="pace-figure">'+lead+'</div>'+
    '<div class="pace-bar"><span class="pace-fill" style="width:'+pct+'%"></span></div>'+
    '<p class="pace-sub"><b>'+bciqEsc(money(signed))+'</b> of <b>'+bciqEsc(money(budget))+'</b> · '+pct+'% for '+bciqEsc(season)+'.'+tail+'</p>';
}
/* index231: What's new box + full patch-notes dialog, both fed by BUILD_NOTES. */
function bciqRenderWhatsNew(){
  var box = document.getElementById("glanceWhatsNew");
  if (!box) return;
  var notes = (typeof BUILD_NOTES !== "undefined" && BUILD_NOTES) || [];
  var tag = document.getElementById("glanceBuildTag");
  if (!notes.length){ box.innerHTML = '<p class="glance-empty">No release notes recorded yet.</p>'; if (tag) tag.textContent = ""; return; }
  var latest = notes[0];
  if (tag) tag.textContent = "Build " + latest.build;
  box.innerHTML =
    '<p class="wn-title">' + bciqEsc(latest.title || ("Build " + latest.build)) + '</p>' +
    '<ul class="wn-list">' + (latest.items||[]).slice(0,3).map(function(i){ return "<li>" + bciqEsc(i) + "</li>"; }).join("") + '</ul>' +
    ((latest.items||[]).length > 3 ? '<p class="wn-more">+' + ((latest.items.length)-3) + ' more in this build</p>' : "");
  var btn = document.getElementById("glanceWhatsNewMore");
  if (btn && !btn.dataset.wired){
    btn.dataset.wired = "1";
    btn.addEventListener("click", function(){
      var html = notes.map(function(n){
        return '<section class="pn-build"><header><h3>Build ' + bciqEsc(n.build) + '</h3><span>' + bciqEsc(n.date||"") + '</span></header>' +
          '<p class="pn-title">' + bciqEsc(n.title||"") + '</p><ul>' +
          (n.items||[]).map(function(i){ return "<li>" + bciqEsc(i) + "</li>"; }).join("") + "</ul></section>";
      }).join("");
      var back = document.getElementById("patchNotesBackdrop");
      if (back){ document.getElementById("patchNotesBody").innerHTML = html; back.classList.add("show"); }
    });
  }
}
function renderGlance(){
  bciqRenderSchedule();
  bciqRenderPace();
  bciqRenderWhatsNew();
  var a=document.getElementById("glanceAttention");
  if(a){ var at=bciqNeedsAttention(); a.innerHTML = at.length ? at.map(function(x){ return '<li><b>'+bciqEsc(x.r.sponsor)+'</b><span>'+bciqEsc(x.why)+'</span></li>'; }).join("") : '<li class="glance-empty">Nothing flagged right now.</li>'; }
  var rc=document.getElementById("glanceRecent");
  /* index231: name the editor. Records written from build 231 on carry updatedBy; anything older
     has no author, and says so rather than guessing. */
  if(rc){ var ru=bciqRecent(); rc.innerHTML = ru.length ? ru.map(function(r){ var ch=bciqChanged(r); var what=ch.length?(ch.slice(0,3).join(", ")+" updated"):"updated"; var who=r.updatedBy?(" by "+bciqEsc(r.updatedBy)):""; return '<li><b>'+bciqEsc(r.sponsor)+'</b><span>'+bciqEsc(what)+who+' · '+bciqAgo(r.updatedAt)+'</span></li>'; }).join("") : '<li class="glance-empty">No edits yet — changes appear here in plain English as sponsors are edited on any browser.</li>'; }
  bciqLoadNotes();
}


/* ===== index209 Activity history (full log, reuses bciqChanged) ===== */
/* index227: the activity log is live. It used to paint once when you opened it and then sit there
   going stale while edits arrived from other browsers on the 8s sync poll. This re-renders it on a
   timer, but ONLY while the history view is actually on screen and only when the underlying record
   set has genuinely changed — a cheap signature of ids + updatedAt stamps — so it never fights a
   filter you just set or re-renders for nothing. Also refreshes the moment the tab regains focus. */
var __bciqHistSig = "";
function bciqHistorySignature(){
  try{
    return bciqAllRecs().map(function(r){ return (r&&r.id)+":"+(r&&r.updatedAt||""); }).join("|");
  }catch(e){ return String(Date.now()); }
}
function bciqHistoryTick(force){
  var view = document.getElementById("historyView");
  if(!view || !view.classList.contains("active")) return;
  var sig = bciqHistorySignature();
  if(!force && sig === __bciqHistSig) return;
  __bciqHistSig = sig;
  try{ renderHistory(); }catch(e){}
}
try{
  setInterval(function(){ bciqHistoryTick(false); }, 6000);
  window.addEventListener("focus", function(){ bciqHistoryTick(false); });
  document.addEventListener("visibilitychange", function(){ if(!document.hidden) bciqHistoryTick(false); });
}catch(e){}
function renderHistory(){
  /* index213: the log now reads like a diary — grouped under day headers (Today, Yesterday,
     then dates), with one-tap filters for the kind of change. Still fully derived from each
     record's updatedAt; nothing new is stored. */
  var el=document.getElementById("historyList"); if(!el) return;
  var srch=document.getElementById("historyModalSearch");
  if(srch && !srch.dataset.wired){ srch.dataset.wired="1"; srch.addEventListener("input",function(){ try{renderHistory();}catch(e){} }); }
  if(window.__bciqHistFilter==null) window.__bciqHistFilter="all";
  var q=((srch||{}).value||"").trim().toLowerCase();
  var recs=bciqAllRecs().filter(function(r){ return r && r.updatedAt; })
    .sort(function(a,b){ return String(b.updatedAt).localeCompare(String(a.updatedAt)); });
  if(q) recs=recs.filter(function(r){ var ch=bciqChanged(r).join(" "); return ((r.sponsor||"")+" "+ch).toLowerCase().indexOf(q)>=0; });
  var FILTERS=[["all","All"],["value","Value"],["status","Status & stage"],["fulfillment","Fulfillment"],["contact","Contacts"],["notes","Notes & to-dos"]];
  var FMATCH={value:/value/,status:/status|stage|renewal|active/,fulfillment:/fulfillment|assets/,contact:/contact/,notes:/notes|to-do/};
  if(window.__bciqHistFilter!=="all"){ var re=FMATCH[window.__bciqHistFilter]; if(re) recs=recs.filter(function(r){ return re.test(bciqChanged(r).join(" ")); }); }
  var chips='<div class="hist-filters">'+FILTERS.map(function(f){ return '<button type="button" class="hist-chip'+(window.__bciqHistFilter===f[0]?" on":"")+'" data-histf="'+f[0]+'">'+f[1]+'</button>'; }).join("")+'<span class="hist-count">'+recs.length+' change'+(recs.length===1?"":"s")+'</span></div>';
  function dayLabel(iso){
    try{
      var d=new Date(iso); d.setHours(0,0,0,0);
      var t=new Date(); t.setHours(0,0,0,0);
      var diff=Math.round((t-d)/86400000);
      if(diff===0) return "Today";
      if(diff===1) return "Yesterday";
      return d.toLocaleDateString("en-US",{weekday:"long",month:"long",day:"numeric"});
    }catch(e){ return ""; }
  }
  var out="", lastDay=null;
  recs.forEach(function(r){
    var day=dayLabel(r.updatedAt);
    if(day!==lastDay){ out+='<div class="hist-day">'+bciqEsc(day)+'</div>'; lastDay=day; }
    /* index232: who did what WHERE. Each entry now names the person who made the edit (from the
       updatedBy stamp added in 231), spells the changed fields out individually as chips rather
       than mashing them into one sentence, and says which part of the app owns that field — so a
       fulfilment change reads as Sponsor Fulfillment and a stage change reads as Sales Center.
       Edits made before authorship existed say "unattributed" rather than guessing a name. */
    var ch=bciqChanged(r); var what=ch.length?(ch.join(", ")+" updated"):"updated";
    var when=""; try{ when=new Date(r.updatedAt).toLocaleTimeString("en-US",{hour:"numeric",minute:"2-digit"}); }catch(e){}
    var who = r.updatedBy ? bciqEsc(r.updatedBy) : "unattributed";
    var whoCls = r.updatedBy ? "hist-who" : "hist-who hist-who-none";
    var WHERE=[[/fulfillment|assets/i,"Sponsor Fulfillment","fulfillment"],[/stage|pipeline|proposal/i,"Sales Center","prospecting"],[/renewal|outlook/i,"Renewal Center","renewals"],[/contact|rep/i,"Ledger","sponsors"],[/to-?do|task/i,"Service Center","service"],[/value|total|budget/i,"Ledger","sponsors"],[/logo|photo|artwork/i,"Ballpark & Allocation","assetalloc"]];
    var placeLabel="", placeView="";
    for(var wi=0; wi<WHERE.length; wi++){ if(WHERE[wi][0].test(ch.join(" "))){ placeLabel=WHERE[wi][1]; placeView=WHERE[wi][2]; break; } }
    var fields = ch.length ? ch.map(function(c){ return '<em class="hist-field">'+bciqEsc(c)+'</em>'; }).join("") : '<em class="hist-field">record</em>';
    var place = placeLabel ? '<button type="button" class="hist-where" data-hist-jump="'+bciqEsc(placeView)+'">in '+bciqEsc(placeLabel)+' &rarr;</button>' : "";
    out+='<div class="hist-row"><span class="hist-dot"></span><div class="hist-body"><strong>'+bciqEsc(r.sponsor)+'</strong>'
      +'<span class="hist-meta"><b class="'+whoCls+'">'+who+'</b> changed '+fields+place+'</span>'
      +'</div><time class="hist-time">'+bciqEsc(bciqAgo(r.updatedAt))+'<small>'+bciqEsc(when)+'</small></time></div>';
  });
  el.innerHTML = chips + (recs.length ? out : '<div class="hist-empty">No edits match. As sponsors are changed on any browser, every change shows here in plain English.</div>');
  el.querySelectorAll("[data-histf]").forEach(function(b){ b.addEventListener("click",function(){ window.__bciqHistFilter=b.dataset.histf; renderHistory(); }); });
  /* index232: the "in <section>" link on each entry navigates to the page that owns the changed
     field, and closes the history dialog on the way. */
  el.querySelectorAll("[data-hist-jump]").forEach(function(b){
    b.addEventListener("click",function(ev){
      ev.stopPropagation();
      var v=b.getAttribute("data-hist-jump");
      try{ if(typeof showView==="function") showView(v); }catch(e){}
      var back=document.getElementById("historyBackdrop"); if(back) back.classList.remove("show");
    });
  });
}

function showView(name) {
  if (name === "inventory") { name = "assetledger"; window.__pendingAssetTab = "inventory"; }
  document.querySelectorAll(".view").forEach(v => v.classList.remove("active"));
  document.getElementById(name + "View").classList.add("active");
  document.querySelectorAll(".nav-item").forEach(b => b.classList.toggle("active", b.dataset.view === name));
  const chapterId = VIEW_CHAPTER[name];
  document.querySelectorAll(".nav-chapter").forEach(ch => ch.setAttribute("data-open", String(ch.dataset.chapter === chapterId)));
  document.querySelectorAll(".chapter-head").forEach(h => h.classList.toggle("chapter-active", h.closest(".nav-chapter").dataset.chapter === chapterId));
  document.getElementById("breadcrumbTitle").textContent = VIEW_TITLES[name] || name;
  document.getElementById("sidebar").classList.remove("open");
  /* index242 — every view fills its season badge on the way in. Previously only the views
     whose render function happened to call this got a correct year. */
  try { updateSeasonBadges(); } catch (e) {}
  /* index242 — the clause library only ever rendered after a save, so opening the view fresh
     showed an empty card. It paints on the way in now. */
  if (name === "assetledger" && typeof renderContractLanguageLibrary === "function") {
    try { renderContractLanguageLibrary(); } catch (e) { console.error("clause library", e); }
  }
  /* index242 — the staffing table had no load-time render at all; its only callers were
     listeners on filters that did not exist. */
  if (name === "schedule" && typeof renderStaffSchedule === "function") {
    try { renderStaffSchedule(); } catch (e) { console.error("staff schedule", e); }
  }
  window.scrollTo(0, 0);
  if (name === "brief") { try { renderBriefView(); } catch(e){ console.error("Executive Brief render failed", e); } }
  if (name === "overview") { renderOverview(); try{ renderGlance(); }catch(e){ console.error("glance",e); } }
  if (name === "sponsors") renderSponsorGrid();
  if (name === "statusview") renderStatusView();
  if (name === "renewals") renderRenewalCenter();
  if (name === "categories") renderCategoryInsights();
  if (name === "assetledger" || name === "inventory") { setAssetTab(name === "inventory" ? "inventory" : (window.__pendingAssetTab || (typeof alState!=="undefined" && alState.subtab) || "ledger")); window.__pendingAssetTab = null; }
  if (name === "displays") { initBallparkControls(); try { renderBallparkDisplays(); } catch(e) { console.error("Ballpark Displays render failed",e); const b=document.getElementById("displayBoard"); if(b)b.innerHTML=`<div class="display-empty"><strong>Ballpark Displays could not render.</strong><br>${escDisplay(e?.message||e)}<br><button onclick="resetBallparkView()">Restore sourced board layout</button></div>`; } }
  if (name === "fulfillment") renderFulfillmentView();
  if (name === "process") renderProcessView();
  if (name === "breakdown") renderBreakdownView();
  if (name === "gameday") renderGamedayView();
  if (name === "options") renderOptionsView();
  if (name === "agreements") renderAgreementGeneratorView();
  if (name === "digideck") { renderDigideckView(); renderReportTracker(); }
  if (name === "reports") renderReportGrid();
  if (name === "stadiummap") {
    if (typeof renderStadiumMap === "function") renderStadiumMap();
    if (typeof sizeStadiumWrap === "function") requestAnimationFrame(sizeStadiumWrap);
  }
  if (name === "schedule") { renderScheduleCalendar(); }
  if (name === "history") renderHistoryView();
  if (name === "prospecting") renderProspectingView();
  if (name === "service") renderServiceView();
  if (name === "squad") { try { renderSquadView(); } catch(e){ console.error("Squad schedule render failed", e); } }
  if (name === "assetprep") renderAssetPrepView();
  if (name === "requests") renderRequestsView();
  if (name === "mytasks") renderMyTasksView();
  /* index257: the Asset Allocation embeds re-use the scoreboard / marquee / e-news ids. Views are
     hidden, not removed, and the embed markup sits EARLIER in the document, so once it has been
     rendered every later getElementById resolves into the hidden copy and the real board paints
     into a node nobody can see. Empty the embed whenever Asset Allocation is not the open view. */
  if (name !== "assetalloc") { const _aab = document.getElementById("assetallocBody"); if (_aab) _aab.innerHTML = ""; }
  if (name === "scoreboard") { try { renderScoreboardView(); } catch(e){ console.error("Scoreboard render failed", e); } }
  if (name === "assetalloc") { try { renderAssetAllocView(); } catch(e){ console.error("Asset Allocation render failed", e); } }
  if (name === "marquee") { try { renderMarqueeView(); } catch(e){ console.error("Marquee render failed", e); } }
  if (name === "enews") { try { renderEnewsView(); } catch(e){ console.error("E-news render failed", e); } }
  if (name === "agreementhub") { try { renderAgreementHubView(); } catch(e){ console.error("Agreement hub render failed", e); } }
  if (name === "embed-blueclaws") { renderEmbedView("blueclaws"); collapseSidebar(); }
  if (name === "embed-gameschedule") { renderEmbedView("gameschedule"); collapseSidebar(); }
  if (name === "embed-score") { renderEmbedView("score"); collapseSidebar(); }

  runCountUps(name);
}
function quickSearchItems() {
  const items = [];
  try {
    getAllRecords().forEach(r => items.push({
      kind: "Sponsor",
      title: r.sponsor || "Unnamed sponsor",
      sub: [r.rep, r.type, r.department, (Array.isArray(r.seasons) ? r.seasons.join(", ") : "")].filter(Boolean).join(" - "),
      hay: [r.sponsor, r.rep, r.type, r.department, r.primary, r.email, r.assets, r.notes].filter(Boolean).join(" "),
      action: () => openDrawer(r.id)
    }));
  } catch (e) {}
  try {
    getFullCatalog().forEach(a => items.push({
      kind: "Asset",
      title: assetDisplayName(a.asset),
      sub: [a.category, a.frequency, a.formerName].filter(Boolean).join(" - "),
      hay: [a.asset, assetDisplayName(a.asset), a.category, a.frequency, a.notes, a.formerName].filter(Boolean).join(" "),
      action: () => {
        showView("assetledger");
        setTimeout(() => {
          try {
            alState.search = a.asset || "";
            if (a.category) alState.catOpen[a.category] = true;
            const search = document.getElementById("assetLedgerSearch");
            if (search) search.value = a.asset || "";
            renderAssetLedger();
          } catch (e) {}
        }, 80);
      }
    }));
  } catch (e) {}
  Object.entries(VIEW_TITLES).forEach(([key, title]) => {
    if (!document.getElementById(key + "View")) return;
    items.push({
      kind: "Page",
      title,
      sub: "Open app section",
      hay: [key, title, VIEW_CHAPTER[key]].filter(Boolean).join(" "),
      action: () => showView(key)
    });
  });
  return items;
}
function quickSearchScore(item, q) {
  /* index213: multi-word queries used to require one contiguous substring — "rob vota laundry"
     matched nothing even when every word was present. Every token must now match somewhere,
     and ranking runs off the first token. */
  const title = String(item.title || "").toLowerCase();
  const hay = String(item.hay || "").toLowerCase();
  const toks = q.split(/\s+/).filter(Boolean);
  if (!toks.length) return 99;
  if (toks.length > 1 && !toks.every(t => hay.includes(t) || title.includes(t))) return 99;
  const q0 = toks.length > 1 ? toks[0] : q;
  if (title === q) return 0;
  if (title.startsWith(q0)) return 1;
  if (title.includes(q0)) return 2;
  if (toks.every(t => hay.includes(t) || title.includes(t))) return 3;
  return 99;
}
function renderQuickSearchResults() {
  const input = document.getElementById("globalSearchInput");
  const box = document.getElementById("globalSearchResults");
  if (!input || !box) return;
  const q = input.value.trim().toLowerCase();
  if (q === "blueclaws iq" || q === "blueclawsiq") {
    input.value = "";
    box.classList.remove("show");
    box.innerHTML = "";
    return;
  }
  if (!q) { box.classList.remove("show"); box.innerHTML = ""; return; }
  const list = quickSearchItems()
    .map(item => ({ item, score: quickSearchScore(item, q) }))
    .filter(x => x.score < 99)
    .sort((a, b) => a.score - b.score || (a.item.kind === "Sponsor" ? -1 : b.item.kind === "Sponsor" ? 1 : 0) || a.item.title.localeCompare(b.item.title))
    .slice(0, 12)
    .map(x => x.item);
  box.innerHTML = list.length ? list.map((item, i) => `
    <button type="button" class="global-search-result ${i === 0 ? "is-active" : ""}" data-qidx="${i}" role="option">
      <small>${esc(item.kind)}</small>
      <div><strong>${esc(item.title)}</strong><span>${esc(item.sub || "")}</span></div>
    </button>`).join("") : `<div class="global-search-empty">No matches yet.</div>`;
  box.classList.add("show");
  box.querySelectorAll("[data-qidx]").forEach(btn => btn.onclick = () => runQuickSearchAction(list[+btn.dataset.qidx]));
  box._quickItems = list;
}
function runQuickSearchAction(item) {
  if (!item) return;
  document.getElementById("globalSearchResults")?.classList.remove("show");
  const input = document.getElementById("globalSearchInput");
  if (input) input.value = "";
  item.action();
}
function initQuickSearch() {
  const input = document.getElementById("globalSearchInput");
  const box = document.getElementById("globalSearchResults");
  if (!input || !box || input.dataset.wired) return;
  input.dataset.wired = "1";
  const clearBadAutofill = () => {
    if (/^blueclaws\s*iq$/i.test((input.value || "").trim())) {
      input.value = "";
      box.classList.remove("show");
      box.innerHTML = "";
      return true;
    }
    return false;
  };
  clearBadAutofill();
  [50, 150, 350, 700, 1500, 3000, 5000].forEach(ms => setTimeout(clearBadAutofill, ms));
  const autofillWatch = setInterval(clearBadAutofill, 400);
  setTimeout(() => clearInterval(autofillWatch), 6500);
  window.addEventListener("pageshow", clearBadAutofill);
  document.addEventListener("visibilitychange", clearBadAutofill);
  input.addEventListener("change", clearBadAutofill);
  input.addEventListener("input", () => { if (!clearBadAutofill()) renderQuickSearchResults(); });
  input.addEventListener("focus", () => { clearBadAutofill(); renderQuickSearchResults(); });
  input.addEventListener("keydown", e => {
    const items = box._quickItems || [];
    const buttons = [...box.querySelectorAll("[data-qidx]")];
    let active = buttons.findIndex(b => b.classList.contains("is-active"));
    if (e.key === "ArrowDown" || e.key === "ArrowUp") {
      e.preventDefault();
      if (!buttons.length) return;
      const delta = e.key === "ArrowDown" ? 1 : -1;
      active = ((active < 0 ? (delta > 0 ? -1 : 0) : active) + delta + buttons.length) % buttons.length;
      buttons.forEach((b, i) => b.classList.toggle("is-active", i === active));
      try { buttons[active].scrollIntoView({ block: "nearest" }); } catch (err) {}
    } else if (e.key === "Enter") {
      e.preventDefault();
      runQuickSearchAction(items[Math.max(0, active)]);
    } else if (e.key === "Escape") {
      if (input.value) { input.value = ""; renderQuickSearchResults(); }
      else { box.classList.remove("show"); input.blur(); }
    }
  });
  document.addEventListener("click", e => {
    if (!e.target.closest("#globalSearchWrap")) box.classList.remove("show");
  });
  /* index213: real shortcuts — Ctrl/Cmd+K anywhere, or "/" when not already typing. */
  document.addEventListener("keydown", e => {
    const k = (e.key || "").toLowerCase();
    const typing = /^(input|textarea|select)$/i.test((document.activeElement || {}).tagName || "") || (document.activeElement && document.activeElement.isContentEditable);
    if (((e.metaKey || e.ctrlKey) && k === "k") || (!typing && !e.metaKey && !e.ctrlKey && !e.altKey && k === "/")) {
      e.preventDefault();
      input.focus(); input.select();
    }
  });
  input.setAttribute("placeholder", "Quick search — press /");
}
