function loadStaffSchedule() {
  try {
    const raw = memStore.getItem(STAFF_SCHEDULE_KEY);
    if (raw === null) { const seeded = seedStaffScheduleData(); saveStaffSchedule(seeded); return seeded; }
    return JSON.parse(raw) || [];
  } catch { return []; }
}
function saveStaffSchedule(arr) { memStore.setItem(STAFF_SCHEDULE_KEY, JSON.stringify(arr)); pushSharedData("staffSchedule", { value: JSON.stringify(arr) }); }
let stfState = { staff: "all", week: "all" };
/* index242 — this parenthetical was typed by hand as "(4 full-time, 7 interns)". It happened
   to be right, because STAFF_ROSTER holds exactly 4 and 7 today. Add or remove one person and
   the total beside it updates while the breakdown quietly keeps claiming the old split. It is
   counted from the roster now. */
function staffRosterBreakdown() {
  const roster = (typeof STAFF_ROSTER !== "undefined" && Array.isArray(STAFF_ROSTER)) ? STAFF_ROSTER : [];
  const counts = {};
  roster.forEach(s => { const role = String(s.role || "Unspecified"); counts[role] = (counts[role] || 0) + 1; });
  /* "Full-time" is an adjective, not a countable noun — pluralising it gives "4 full-times".
     Anything hyphenated or already ending in s is left as written. */
  const parts = Object.keys(counts).sort().map(role => {
    const n = counts[role], label = role.toLowerCase();
    const plural = (n === 1 || label.includes("-") || label.endsWith("s")) ? label : label + "s";
    return n + " " + plural;
  });
  return parts.length ? parts.join(", ") : "nobody on file";
}
function renderStaffSchedule() {
  const wrap = document.getElementById("staffScheduleWrap");
  if (!wrap) return;
  let rows = loadStaffSchedule();
  const staffSel = document.getElementById("staffFilterStaff");
  const weekSel = document.getElementById("staffFilterWeek");
  const staffNames = STAFF_ROSTER.map(s => s.name);
  const weekLabels = [...new Set(rows.map(r => r.week))];
  if (staffSel) staffSel.innerHTML = `<option value="all">All staff</option>` + staffNames.map(n => `<option value="${esc(n)}" ${stfState.staff === n ? "selected" : ""}>${esc(n)}</option>`).join("");
  if (weekSel) weekSel.innerHTML = `<option value="all">All weeks</option>` + weekLabels.map(w => `<option value="${esc(w)}" ${stfState.week === w ? "selected" : ""}>${esc(w)}</option>`).join("");
  let list = rows;
  if (stfState.staff !== "all") list = list.filter(r => r.staff === stfState.staff);
  if (stfState.week !== "all") list = list.filter(r => r.week === stfState.week);
  list.sort((a, b) => a.date.localeCompare(b.date) || a.staff.localeCompare(b.staff));
  const fullTimeHrs = list.filter(r => r.role === "Full-time").reduce((s, r) => s + (Number(r.hours) || 0), 0);
  const internHrs = list.filter(r => r.role === "Intern").reduce((s, r) => s + (Number(r.hours) || 0), 0);
  document.getElementById("staffScheduleKpis").innerHTML = `
    <div class="mini-kpi"><span>Shifts shown</span><strong>${list.length}</strong></div>
    <div class="mini-kpi"><span>Full-time hours</span><strong>${fullTimeHrs.toFixed(1)}</strong></div>
    <div class="mini-kpi"><span>Intern hours</span><strong>${internHrs.toFixed(1)}</strong></div>
    <div class="mini-kpi"><span>Staff on file</span><strong>${STAFF_ROSTER.length} (${staffRosterBreakdown()})</strong></div>`;
  wrap.innerHTML = list.length ? list.map(r => `
    <div class="fulfillment-row" data-staff-row="${esc(r.id)}" style="grid-template-columns: 90px 1fr 90px 88px 90px 90px 1.4fr 28px; align-items:center;">
      <div style="font-size:var(--text-xs); color:var(--muted);">${esc(r.day)} ${esc(r.date.slice(5))}</div>
      <select data-stf-field="staff" data-stf-id="${esc(r.id)}" aria-label="Staff member">${(() => {
        /* index214: the name is picked from the roster — a typed variant used to vanish from its
           own person's filter. Unknown legacy values still show, marked. */
        const names = (typeof STAFF_ROSTER !== "undefined" ? STAFF_ROSTER : []).map(s => s.name);
        const cur = String(r.staff || "").trim();
        const known = names.some(n => n.toLowerCase() === cur.toLowerCase());
        return `<option value=""></option>` + (cur && !known ? `<option value="${esc(cur)}" selected>${esc(cur)} (not on roster)</option>` : "") + names.map(n => `<option value="${esc(n)}"${n.toLowerCase() === cur.toLowerCase() ? " selected" : ""}>${esc(n)}</option>`).join("");
      })()}</select>
      <select data-stf-field="role" aria-label="Employment type" data-stf-id="${esc(r.id)}">
        <option value="Full-time" ${r.role === "Full-time" ? "selected" : ""}>Full-time</option>
        <option value="Intern" ${r.role === "Intern" ? "selected" : ""}>Intern</option>
      </select>
      <label style="display:flex; align-items:center; gap:2px; font-size:var(--text-xs); white-space:nowrap;"><input type="checkbox" data-stf-field="working" data-stf-id="${esc(r.id)}" ${r.working ? "checked" : ""}> Working</label>
      <input data-stf-field="start" data-stf-id="${esc(r.id)}" value="${esc(r.start || "")}" placeholder="Start" aria-label="Shift start time on ${esc(r.day)} ${esc(r.date.slice(5))}">
      <input data-stf-field="hours" data-stf-id="${esc(r.id)}" type="number" step="0.5" value="${esc(r.hours ?? "")}" placeholder="Hrs" aria-label="Hours on ${esc(r.day)} ${esc(r.date.slice(5))}">
      <input data-stf-field="notes" data-stf-id="${esc(r.id)}" value="${esc(r.notes || "")}" placeholder="Notes (e.g. exact shift time, theme night)" aria-label="Notes for ${esc(r.day)} ${esc(r.date.slice(5))}">
      <button type="button" data-stf-remove="${esc(r.id)}" style="border:0; background:transparent; color:var(--muted); cursor:pointer;" title="Remove" aria-label="Remove the ${esc(r.day)} ${esc(r.date.slice(5))} shift">x</button>
    </div>`).join("") : `<div style="padding:var(--space-18); color:var(--muted); font-size:var(--text-xs);">No shifts match this filter.</div>`;
  wrap.innerHTML = `<datalist id="staffNameChoices">${staffNames.map(n => `<option value="${esc(n)}"></option>`).join("")}</datalist>` + wrap.innerHTML;

  wrap.querySelectorAll("[data-stf-field]").forEach(el => {
    const evt = el.type === "checkbox" ? "change" : (el.tagName === "SELECT" ? "change" : "blur");
    el.addEventListener(evt, () => {
      const all = loadStaffSchedule();
      const row = all.find(x => x.id === el.dataset.stfId);
      if (!row) return;
      const field = el.dataset.stfField;
      row[field] = field === "working" ? el.checked : (field === "hours" ? Number(el.value) || 0 : el.value);
      saveStaffSchedule(all);
      updateStaffScheduleKpisOnly();
    });
  });
  wrap.querySelectorAll("[data-stf-remove]").forEach(btn => {
    btn.addEventListener("click", () => {
      const all = loadStaffSchedule().filter(x => x.id !== btn.dataset.stfRemove);
      saveStaffSchedule(all);
      renderStaffSchedule();
    });
  });
}
function updateStaffScheduleKpisOnly() {
  const rows = loadStaffSchedule();
  let list = rows;
  if (stfState.staff !== "all") list = list.filter(r => r.staff === stfState.staff);
  if (stfState.week !== "all") list = list.filter(r => r.week === stfState.week);
  const fullTimeHrs = list.filter(r => r.role === "Full-time").reduce((s, r) => s + (Number(r.hours) || 0), 0);
  const internHrs = list.filter(r => r.role === "Intern").reduce((s, r) => s + (Number(r.hours) || 0), 0);
  const kpis = document.getElementById("staffScheduleKpis");
  if (kpis) kpis.innerHTML = `
    <div class="mini-kpi"><span>Shifts shown</span><strong>${list.length}</strong></div>
    <div class="mini-kpi"><span>Full-time hours</span><strong>${fullTimeHrs.toFixed(1)}</strong></div>
    <div class="mini-kpi"><span>Intern hours</span><strong>${internHrs.toFixed(1)}</strong></div>
    <div class="mini-kpi"><span>Staff on file</span><strong>${STAFF_ROSTER.length} (${staffRosterBreakdown()})</strong></div>`;
}
function addStaffShift() {
  const all = loadStaffSchedule();
  const today = new Date().toISOString().slice(0, 10);
  all.push({ id: "shift-" + Date.now(), staff: STAFF_ROSTER[0].name, role: STAFF_ROSTER[0].role, week: "Custom", date: today, day: "", working: true, start: "", end: "", hours: 0, notes: "" });
  saveStaffSchedule(all);
  renderStaffSchedule();
}

/* ================= SPONSORSHIP HISTORY / STARTER WORKFLOW SECTIONS ================= */
let hState = { search: "", sort: "lifetime" };
function historyProfile(r) {
  const rows = seasonRecordsFor(r).filter(x => x.year);
  const years = rows.map(x => Number(x.year)).filter(Boolean).sort((a, b) => a - b);
  const lifetime = rows.reduce((s, x) => s + Number(x.total || 0), 0);
  let longest = 0, current = 0, prev = null;
  years.forEach(y => { current = prev !== null && y === prev + 1 ? current + 1 : 1; longest = Math.max(longest, current); prev = y; });
  return { sponsor: r.sponsor, id: r.id, first: years[0] || null, recent: years[years.length - 1] || null, seasons: years.length, streak: longest, lifetime, avg: years.length ? lifetime / years.length : 0, active: isActiveForSelectedSeason(r), outlook: outlookOf(r) };
}
function renderHistoryView() {
  let rows = getAllRecords().map(historyProfile).filter(p => p.seasons);
  const q = hState.search.trim().toLowerCase();
  if (q) rows = rows.filter(p => p.sponsor.toLowerCase().includes(q));
  const sorters = { lifetime: (a, b) => b.lifetime - a.lifetime, years: (a, b) => b.seasons - a.seasons, recent: (a, b) => (b.recent || 0) - (a.recent || 0), name: (a, b) => a.sponsor.localeCompare(b.sponsor) };
  rows.sort(sorters[hState.sort] || sorters.lifetime);
  /* art-direct scale: the one number this whole view is really about — total lifetime value on
     file across every partner with season history — promoted above the search bar instead of
     making a reader add sixty rows by eye. */
  const leadEl = document.getElementById("historyLeadStat");
  if (leadEl) {
    const lifetimeAll = rows.reduce((s, p) => s + p.lifetime, 0);
    leadEl.innerHTML = rows.length
      ? `<strong>${fmtMoneyShort(lifetimeAll)}</strong><div><p>Lifetime sponsorship value on file.</p><small>across ${rows.length} partner${rows.length === 1 ? "" : "s"} with season history</small></div>`
      : "";
    if (rows.length) animateNumberEl(leadEl.querySelector("strong"));
  }
  /* art-direct signature object: a tenure strip per partner, plotted from that partner's own
     first/most-recent season against the real year span of the whole book on file. Nothing
     stock here — the axis bounds and every bar are recomputed from historyProfile() above. */
  const axisYears = rows.flatMap(p => [p.first, p.recent]).filter(Boolean);
  const axisMin = axisYears.length ? Math.min(...axisYears) : new Date().getFullYear();
  const axisMax = axisYears.length ? Math.max(...axisYears) : new Date().getFullYear();
  const axisSpan = Math.max(1, axisMax - axisMin);
  const tenureBar = p => {
    if (!p.first || !p.recent) return `<div class="hist-tenure"></div><small>—</small>`;
    const left = ((p.first - axisMin) / axisSpan) * 100;
    const width = Math.max(4, ((p.recent - p.first) / axisSpan) * 100);
    return `<div class="hist-tenure" title="${esc(p.first)}–${esc(p.recent)} on the book"><span style="left:${left.toFixed(1)}%; width:${width.toFixed(1)}%"></span></div><small>${esc(p.first)}–${esc(p.recent)}</small>`;
  };
  document.getElementById("historyRowsView").innerHTML = rows.length ? rows.slice(0, 160).map(p => `
    <div class="tracker-row" data-id="${esc(p.id)}" style="cursor:pointer; grid-template-columns: 1.2fr 1fr repeat(4,.7fr) 40px;">
      <div><strong>${esc(p.sponsor)}</strong><small>${p.active ? "Active Partner" : "Inactive Partner"} · ${OUTLOOK_LABELS[p.outlook]}</small></div>
      <div>${tenureBar(p)}</div>
      <div><small>Total seasons</small><strong style="font-size:var(--text-xs);">${p.seasons}</strong></div>
      <div><small>Longest streak</small><strong style="font-size:var(--text-xs);">${p.streak} yr${p.streak === 1 ? "" : "s"}</strong></div>
      <div><small>Lifetime value</small><strong style="font-size:var(--text-xs);">${fmtMoney(p.lifetime)}</strong></div>
      <div><small>Avg annual</small><strong style="font-size:var(--text-xs);">${fmtMoney(p.avg)}</strong></div>
      <button class="row-action" title="Open" aria-label="Open ${esc(p.sponsor || "this sponsor")}">→</button>
    </div>`).join("") : `<div style="padding:var(--space-40); text-align:center; color:var(--muted);">No history matches.</div>`;
  document.querySelectorAll("#historyRowsView .tracker-row").forEach(row => row.addEventListener("click", () => openDrawer(row.dataset.id)));
}
// item #25: new prospects sourced from the import audit's unmatched-sponsor names —
// real company names from the source files that never matched an existing sponsor
// record (GEICO, Texas Roadhouse, TD Bank, Rutgers Athletics, etc.). Not fabricated —
// every name and its source file is exactly what's in window.IMPORT_AUDIT.unmatched.
function newProspectNames() {
  const a = window.IMPORT_AUDIT;
  if (!a || !Array.isArray(a.unmatched)) return [];
  const bySource = {};
  a.unmatched.filter(u => u.type === "unmatched sponsor" && u.name).forEach(u => {
    if (!bySource[u.name]) bySource[u.name] = new Set();
    bySource[u.name].add(u.source);
  });
  return Object.entries(bySource).map(([name, sources]) => ({ name, sources: [...sources] })).sort((a, b) => a.name.localeCompare(b.name));
}
const PTAB_PANELS = { week: "ptabWeek", sheet: "ptabSheet", potential: "ptabPotential", new: "ptabNew" };
/* Board columns for "New Prospects" — reuses the SAME r.dealStage field the Renewal Center's
   dealStageFilter reads, so dragging a card here and changing the stage filter there always agree.
   No parallel "temperature" field — that would just drift out of sync with dealStage. */
const PROSPECT_BOARD_STAGES = ["prospect", "meeting_set", "meeting_complete", "proposal", "proposal_review", "contract", "lost"];

function renderProspectingView() {
  const allRecs = getAllRecords();
  const prospects = allRecs.filter(r => isProspect(r));
  /* index213: the KPIs used to count a list already capped at 80 — with 96 lapsed accounts the
     tile said 80 and the dollar figure was short by 16 accounts, silently. The full set is now
     counted and valued; only the DISPLAY caps, and it caps to the 80 most valuable. */
  const lapsedAll = allRecs.filter(r => !isActiveForSelectedSeason(r) && !isInProgressForSelectedSeason(r) && dealStageOf(r) !== "signed" && !isProspect(r))
    .map(r => ({ r, v: displayValueForSeason(r) || 0 }));
  lapsedAll.sort((a, b) => b.v - a.v);
  const lapsed = lapsedAll.slice(0, 80).map(x => x.r);
  const newProspects = newProspectNames();
  const potentialValue = lapsedAll.reduce((s, x) => s + x.v, 0);

  document.getElementById("prospectingKpis").innerHTML = `<div class="mini-kpi"><span>Prospects</span><strong>${prospects.length}</strong></div><div class="mini-kpi" title="Not active or in progress for the selected season"><span>Lapsed Accounts</span><strong>${lapsedAll.length}</strong></div><div class="mini-kpi" title="Company names from the import files that never matched a sponsor record"><span>Unmatched Names</span><strong>${newProspects.length}</strong></div><div class="mini-kpi"><span>Lapsed Value</span><strong>${fmtMoney(potentialValue)}</strong></div>${lapsedAll.length > 80 ? `<div class="readonly-note" style="flex-basis:100%;">Showing the 80 most valuable lapsed accounts of ${lapsedAll.length}.</div>` : ""}`;

  const tab = pState.tab || "week";
  document.querySelectorAll("#prospectingTabs [data-ptab]").forEach(b => b.classList.toggle("active", b.dataset.ptab === tab));
  document.querySelectorAll(".ptab-panel").forEach(p => p.classList.toggle("active", p.id === PTAB_PANELS[tab]));

  if (tab === "week") renderProspectWeek(lapsedAll, prospects, newProspects);
  else if (tab === "sheet") { renderProspectCoverage(allRecs); renderCategoryManager(); }
  else if (tab === "potential") renderProspectPotential(lapsed);
  else if (tab === "new") renderProspectBoard(prospects, newProspects);
}

/* ---- THIS WEEK: a short, ranked "do these first" list — no new fields, just the sharpest
   signals already sitting in the records above. ---- */
function renderProspectWeek(lapsedAll, prospects, newProspects) {
  const items = [];
  if (lapsedAll[0]) {
    items.push({ id: lapsedAll[0].r.id, cls: "risk", label: "Highest-value lapsed account", text: `${lapsedAll[0].r.sponsor} — ${fmtMoney(lapsedAll[0].v)} on the table, worth a re-approach call.` });
  }
  const nearClose = prospects.filter(r => ["proposal", "proposal_review", "contract"].includes(dealStageOf(r)));
  nearClose.slice(0, 2).forEach(r => items.push({ id: r.id, cls: "confirmed", label: DEAL_STAGES[dealStageOf(r)].label, text: `${r.sponsor} is at "${DEAL_STAGES[dealStageOf(r)].label}" — move it forward before it goes stale.` }));
  const unassigned = prospects.find(r => !r.rep);
  if (unassigned) items.push({ id: unassigned.id, cls: "unknown", label: "Unassigned prospect", text: `${unassigned.sponsor} has no rep assigned yet.` });
  if (newProspects.length) items.push({ id: null, cls: "unknown", label: "Unmatched names", text: `${newProspects.length} company name${newProspects.length === 1 ? "" : "s"} from imports never matched a sponsor record — worth a look on New Prospects.` });

  const html = items.slice(0, 5).map(it => `
    <div class="tracker-row" ${it.id ? `data-id="${esc(it.id)}" style="cursor:pointer;"` : ""} style="grid-template-columns: 1fr 40px;">
      <div><span class="risk-badge ${it.cls}" style="margin-bottom:var(--space-4);">${esc(it.label)}</span><div style="font-size:var(--text-xs); margin-top:var(--space-4);">${esc(it.text)}</div></div>
      ${it.id ? `<button class="row-action" title="Open" aria-label="Open ${esc(it.label)}">→</button>` : `<span></span>`}
    </div>`).join("");
  document.getElementById("prospectWeekList").innerHTML = html || `<div style="padding:var(--space-40); text-align:center; color:var(--muted);">Nothing urgent right now.</div>`;
  document.querySelectorAll("#prospectWeekList .tracker-row[data-id]").forEach(row => row.addEventListener("click", () => openDrawer(row.dataset.id)));
}

/* ---- SPONSOR SHEET: coverage by Business Category, reusing the same bar-row look used
   elsewhere (Reports → By type/By rep) instead of inventing a new visual. ---- */
function renderProspectCoverage(allRecs) {
  const cats = (typeof loadCategories === "function" ? loadCategories() : DEFAULT_SPONSOR_CATEGORIES).filter(c => c !== "Inactive" && c !== "Other");
  const activeSponsors = allRecs.filter(isActiveForSelectedSeason);
  const categorized = activeSponsors.filter(r => r.businessCategory);
  const activeByCat = {};
  categorized.forEach(r => { activeByCat[r.businessCategory] = (activeByCat[r.businessCategory] || 0) + 1; });
  const rows = cats.map(c => ({ cat: c, count: activeByCat[c] || 0 })).sort((a, b) => b.count - a.count);
  const maxCount = Math.max(1, ...rows.map(r => r.count));
  /* index217: businessCategory is only set when someone picks it in the sponsor drawer — across
     the real 2026 master sheet it's populated for a small minority of active sponsors. Treating
     an unset category as "Open" would be actively misleading (it'd flag categories that already
     have a paying sponsor as gaps just because nobody's categorized them yet). So below a rough
     coverage threshold, this shows neutral "no data" badges and an explanation instead of
     red/amber/blue judgments it can't actually back up. */
  const dataIsThin = categorized.length < Math.max(10, activeSponsors.length * 0.15);

  const banner = dataIsThin
    ? `<div class="mock-note" style="margin-bottom:var(--space-16);"><b>Heads up:</b> only ${categorized.length} of ${activeSponsors.length} active sponsors have a Business Category set, so this isn't reliable coverage data yet — most "no data" rows below just mean nobody's categorized that sponsor, not that the category is actually open. Business Category is set from each sponsor's drawer. Once more accounts are categorized, this view gets accurate.</div>`
    : "";

  const statusFor = n => {
    if (dataIsThin) return n > 0 ? { label: `${n} categorized`, cls: "unknown" } : { label: "No data yet", cls: "unknown" };
    return n === 0 ? { label: "Open", cls: "risk" } : n === 1 ? { label: "Thin", cls: "likely" } : { label: "Covered", cls: "confirmed" };
  };
  const rowHtml = rows.map(r => {
    const st = statusFor(r.count);
    const barColor = st.cls === "risk" ? "var(--red)" : st.cls === "likely" ? "var(--amber)" : st.cls === "confirmed" ? "var(--blue)" : "var(--ink-300, var(--line))";
    return `<div class="category-bar-row"><span>${esc(r.cat)}</span><div class="bar-track"><div class="bar-fill" style="width:${(r.count / maxCount * 100).toFixed(1)}%; background:${barColor};"></div></div><span class="risk-badge ${st.cls}" style="width:fit-content; justify-self:end;">${st.label}</span></div>`;
  }).join("");
  document.getElementById("prospectCoverage").innerHTML = `${banner}<article class="insight-card" style="grid-column:1 / -1;"><h3>Category coverage (active sponsors)</h3>${rowHtml}</article>`;
}

/* ---- POTENTIAL PROSPECTS: the lapsed-account list, same layout as before, now with its
   own tab and its own search box instead of sharing one three-way toggle. ---- */
function renderProspectPotential(lapsed) {
  const q = (pState.search || "").trim().toLowerCase();
  const shown = lapsed.filter(r => !q || r.sponsor.toLowerCase().includes(q));
  const html = shown.map(r => `
    <div class="tracker-row" data-id="${esc(r.id)}" style="cursor:pointer; grid-template-columns: 1.15fr .6fr .6fr .6fr 128px 40px;">
      <div><strong>${esc(r.sponsor)}</strong><small>${esc(r.businessCategory || "Uncategorized")} · ${esc(r.rep || "Unassigned")} · Lapsed sponsor</small></div>
      <div><small>Stage</small><strong style="font-size:var(--text-xs);">${DEAL_STAGES[dealStageOf(r)].label}</strong></div>
      <div><small>Estimated value</small><strong style="font-size:var(--text-xs);">${displayValueForSeason(r) ? fmtMoney(displayValueForSeason(r)) : "—"}</strong></div>
      <span class="risk-badge ${OUTLOOK_HEALTH[outlookOf(r)]}">${OUTLOOK_LABELS[outlookOf(r)]}</span>
      <button class="row-action" data-start-pursuing="${esc(r.id)}" title="Move to the New Prospects pipeline" style="width:auto; padding:0 var(--space-10); font-size:var(--text-xs); font-weight:700; white-space:nowrap; color:var(--blue-text); border-color:var(--blue);">Start pursuing →</button>
      <button class="row-action" title="Open" aria-label="Open ${esc(r.sponsor || "this sponsor")}">→</button>
    </div>`).join("");
  document.getElementById("prospectPotentialRows").innerHTML = html || `<div style="padding:var(--space-40); text-align:center; color:var(--muted);">No lapsed sponsors match.</div>`;
  document.querySelectorAll("#prospectPotentialRows .tracker-row[data-id]").forEach(row => {
    row.addEventListener("click", e => { if (!e.target.closest("[data-start-pursuing]")) openDrawer(row.dataset.id); });
  });
  document.querySelectorAll("#prospectPotentialRows [data-start-pursuing]").forEach(btn => {
    btn.addEventListener("click", e => {
      e.stopPropagation();
      startPursuing(btn.dataset.startPursuing);
    });
  });
}

/* One click, one clear effect: flips a lapsed account into the same dealStage pipeline the
   New Prospects board reads, then jumps the person straight there so the move is visible
   immediately instead of being a silent background change. */
function startPursuing(id) {
  const rec = getRecord(id);
  updateOverride(id, { prospect: true, dealStage: rec && rec.dealStage && rec.dealStage !== "lost" ? rec.dealStage : "prospect" });
  toast("Moved to New Prospects", `${rec ? rec.sponsor : "Sponsor"} is now tracked in the pipeline.`, true);
  pState.tab = "new";
  renderProspectingView();
}

/* ---- NEW PROSPECTS: a drag-and-drop board over the existing dealStage pipeline, plus the
   unmatched import names listed underneath (read-only — they have no record id to drag yet). ---- */
function renderProspectBoard(prospects, newProspects) {
  const catSel = document.getElementById("prospectResearchCategory");
  if (catSel && catSel.options.length <= 1) {
    const cats = (typeof loadCategories === "function" ? loadCategories() : DEFAULT_SPONSOR_CATEGORIES).filter(c => c !== "Inactive");
    catSel.innerHTML = `<option value="">—</option>` + cats.map(c => `<option value="${esc(c)}">${esc(c)}</option>`).join("");
  }
  const q = (pState.newSearch || "").trim().toLowerCase();
  const shown = prospects.filter(r => !q || r.sponsor.toLowerCase().includes(q));
  const byStage = {};
  PROSPECT_BOARD_STAGES.forEach(s => byStage[s] = []);
  shown.forEach(r => { const s = dealStageOf(r); (byStage[s] || (byStage[s] = [])).push(r); });
  document.getElementById("prospectBoard").innerHTML = PROSPECT_BOARD_STAGES.map(stageKey => {
    const list = byStage[stageKey] || [];
    const cards = list.map(r => `
      <div class="pboard-card" draggable="true" data-id="${esc(r.id)}">
        <div class="pboard-card-head">
          <strong>${esc(r.sponsor)}</strong>
          <button type="button" class="pboard-remove" data-remove="${esc(r.id)}" title="Remove from pipeline" aria-label="Remove ${esc(r.sponsor)} from pipeline">×</button>
        </div>
        <small>${esc(r.businessCategory || "Uncategorized")} · ${displayValueForSeason(r) ? fmtMoney(displayValueForSeason(r)) : "—"}</small>
      </div>`).join("");
    return `<div class="prospect-board-col${stageKey === "lost" ? " stage-lost" : ""}" data-stage="${stageKey}">
      <h4>${DEAL_STAGES[stageKey].label}<span>${list.length}</span></h4>
      ${cards}
    </div>`;
  }).join("");

  document.querySelectorAll("#prospectBoard .pboard-card").forEach(card => {
    card.addEventListener("click", e => { if (!e.target.closest("[data-remove]")) openDrawer(card.dataset.id); });
    card.addEventListener("dragstart", e => { card.classList.add("dragging"); e.dataTransfer.setData("text/plain", card.dataset.id); });
    card.addEventListener("dragend", () => card.classList.remove("dragging"));
  });
  document.querySelectorAll("#prospectBoard [data-remove]").forEach(btn => {
    btn.addEventListener("click", e => { e.stopPropagation(); removeFromPipeline(btn.dataset.remove); });
  });
  document.querySelectorAll("#prospectBoard .prospect-board-col").forEach(col => {
    col.addEventListener("dragover", e => { e.preventDefault(); col.classList.add("drag-over"); });
    col.addEventListener("dragleave", () => col.classList.remove("drag-over"));
    col.addEventListener("drop", e => {
      e.preventDefault();
      col.classList.remove("drag-over");
      const id = e.dataTransfer.getData("text/plain");
      if (id) { updateOverride(id, { dealStage: col.dataset.stage }); renderProspectingView(); }
    });
  });

  const unmatchedQ = newProspects.filter(p => !q || p.name.toLowerCase().includes(q));
  document.getElementById("prospectUnmatchedCard").innerHTML = `
    <div class="table-toolbar"><strong style="font:700 14px var(--font-display);">Unmatched names from import files</strong></div>
    <div class="tracker-list">${unmatchedQ.map(p => `
      <div class="tracker-row" style="grid-template-columns: 1.2fr 1.4fr 40px;">
        <div><strong>${esc(p.name)}</strong><small>Never a sponsor on file</small></div>
        <div><small>Source</small><strong style="font-size:var(--text-xs); font-weight:400; color:var(--muted);">${esc(p.sources.join(" · "))}</strong></div>
        <span class="risk-badge unknown">New</span>
      </div>`).join("") || `<div style="padding:var(--space-24); text-align:center; color:var(--muted);">No unmatched names.</div>`}</div>`;
}

/* Removing a card means two different things depending on where the record came from:
   - A real sponsor pulled from lapsed history (flipped via "Start pursuing") still has real
     contract/value data worth keeping — removing it from the board just clears prospect/
     dealStage so it drops back out of the pipeline. Nothing is destroyed.
   - A prospect added purely from outside research (_prospectOnly) never had any sponsor
     history to protect, so removing it hides it outright, same as the existing hidden-sponsor
     mechanism elsewhere in the app (reversible from the Hidden Sponsors panel if needed). */
async function removeFromPipeline(id) {
  const rec = getRecord(id);
  if (!rec) return;
  const researchOnly = !!rec._prospectOnly;
  const msg = researchOnly
    ? `Remove ${rec.sponsor} from New Prospects? It was added from outside research, so this removes it entirely.`
    : `Remove ${rec.sponsor} from the pipeline? Their sponsor history stays on file — you can start pursuing them again anytime from Potential Prospects.`;
  const ok = await bcConfirm(msg, { title: "Remove from pipeline", ok: "Remove", danger: true });
  if (!ok) return;
  if (researchOnly) updateOverride(id, { hidden: true });
  else updateOverride(id, { prospect: false, dealStage: null });
  toast("Removed", `${rec.sponsor} is no longer in the pipeline.`, true);
  renderProspectingView();
}

/* Static apps can't run a live search inline, so this opens real search results in a new
   tab (Google / Google Maps / LinkedIn) instead of faking a results panel. The person picks
   whichever's most useful, does their own look-around, then adds what's worth pursuing. */
function openResearchSearch(kind) {
  const q = (document.getElementById("prospectResearchQuery")?.value || "").trim();
  if (!q) { toast("Type a search term first", "Enter a company name, industry, or area to search."); return; }
  const urls = {
    google: `https://www.google.com/search?q=${encodeURIComponent(q + " sponsorship")}`,
    maps: `https://www.google.com/maps/search/${encodeURIComponent(q)}`,
    linkedin: `https://www.linkedin.com/search/results/companies/?keywords=${encodeURIComponent(q)}`
  };
  window.open(urls[kind], "_blank", "noopener");
}
function addProspectFromResearch() {
  const nameEl = document.getElementById("prospectAddName");
  const name = (nameEl?.value || "").trim();
  if (!name) { toast("Type a company name first", "Enter the specific company you found, then add it."); nameEl?.focus(); return; }
  const category = document.getElementById("prospectResearchCategory")?.value || null;
  const custom = loadCustom();
  const existingIds = new Set([...BASE_DATA, ...custom].map(r => r.id));
  const slug = name.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "") || "prospect";
  let id = slug, n = 1;
  while (existingIds.has(id)) id = `${slug}-${n++}`;
  const rec = {
    id, active: false, prospect: true, dealStage: "prospect", type: "Cash", sponsor: name,
    department: "Sponsorship", lastContact: null, rep: null, service: null, seasons: [], total: null,
    primary: null, assets: null, assetsReports: null, status: null, todo: null,
    notes: "Added from outside research (Find new prospects).", category: null, businessCategory: category,
    businessSubCategory: null, industryCategory: null, industry: null, createdAt: new Date().toISOString(),
    _custom: true, _prospectOnly: true
  };
  custom.push(rec); saveCustom(custom);
  toast("Added to New Prospects", `${name} is now on the board.`, true);
  const catEl = document.getElementById("prospectResearchCategory");
  if (nameEl) nameEl.value = "";
  if (catEl) catEl.value = "";
  renderProspectingView();
  document.getElementById("prospectAddName")?.focus();
}

/* Sponsor Categories manager — lets reps see how the category dropdown (used in the
   sponsor drawer's Account Info section) is actually being used, and add/remove entries
   without touching code. Usage counts are informational only; removing a category here
   doesn't clear it off sponsors already using it. */
function renderCategoryManager() {
  const card = document.getElementById("categoryManagerCard");
  if (!card) return;
  const categories = loadCategories();
  const counts = {};
  getAllRecords().forEach(r => { const c = (r.category || "").trim(); if (c) counts[c] = (counts[c] || 0) + 1; });
  card.innerHTML = `
    <div class="table-toolbar"><strong style="font-size:12px;">Sponsor Categories</strong><span style="color:var(--muted); font-size:var(--text-xs);">Used by the Category dropdown in each sponsor's Account Info</span></div>
    <div id="categoryManagerRows">${categories.map(c => `
      <div class="renewal-row" style="grid-template-columns: 1fr auto auto; align-items:center;">
        <div><strong>${esc(c)}</strong></div>
        <small style="color:var(--muted);">${counts[c] || 0} sponsor${counts[c] === 1 ? "" : "s"}</small>
        <button type="button" class="secondary-button" data-remove-category="${esc(c)}" style="padding:var(--space-4) var(--space-8); font-size:var(--text-xs);" title="Remove category">x</button>
      </div>`).join("") || `<p style="color:var(--muted); font-size:var(--text-xs); padding:var(--space-10) 0;">No categories yet — add one below.</p>`}</div>
    <div class="sfield-grid" style="grid-template-columns: 1fr auto; gap:var(--space-8); align-items:end; margin-top:var(--space-10);">
      <div class="sfield" style="margin:0;"><label>New category</label><input id="categoryManagerNew" placeholder="e.g. Healthcare" aria-label="e.g. Healthcare"></div>
      <button type="button" class="secondary-button" id="categoryManagerAdd">+ Add</button>
    </div>`;
  card.querySelectorAll("[data-remove-category]").forEach(btn => btn.addEventListener("click", async () => {
    const c = btn.dataset.removeCategory;
    if (!(await bcConfirm(`Remove "${c}" from the category list? Sponsors already using it keep it until edited.`, {title:"Remove category", ok:"Remove", danger:true}))) return;
    saveCategories(loadCategories().filter(x => x !== c));
    renderCategoryManager();
  }));
  const addBtn = card.querySelector("#categoryManagerAdd");
  const nameField = card.querySelector("#categoryManagerNew");
  const addCategory = () => {
    const name = nameField.value.trim();
    if (!name) return;
    saveCategories(addChoiceIfMissing(loadCategories(), name));
    nameField.value = "";
    renderCategoryManager();
  };
  if (addBtn) addBtn.addEventListener("click", addCategory);
  if (nameField) nameField.addEventListener("keydown", e => { if (e.key === "Enter") { e.preventDefault(); addCategory(); } });
}
function renderServiceView() {
  const tasks = [];
  getAllRecords().forEach(r => { (r.todo || "").split("\n").map(t => t.trim()).filter(Boolean).forEach((t, lineIdx) => tasks.push({ sponsor: r.sponsor, id: r.id, task: t, rep: r.service || r.rep || "Unassigned", cat: "Sponsor Activation", lineIdx, checkable: true })); });
  getAllReportRows().forEach(r => {
    if (!reportCompletedFor(r, "mid")) tasks.push({ sponsor: r.sponsor, id: r.id, task: `Advance Mid-Season Report from ${reportStatusFor(r, "mid")}`, rep: "Service", cat: "Reports", checkable: false });
    if (!reportCompletedFor(r, "annual")) tasks.push({ sponsor: r.sponsor, id: r.id, task: `Advance Annual Report from ${reportStatusFor(r, "annual")}`, rep: "Service", cat: "Reports", checkable: false });
  });
  tasks.sort((a, b) => (a.sponsor || "").localeCompare(b.sponsor || ""));
  document.getElementById("serviceKpis").innerHTML = `<div class="mini-kpi"><span>Open tasks</span><strong>${tasks.length}</strong></div><div class="mini-kpi"><span>Report tasks</span><strong>${tasks.filter(t => t.cat === "Reports").length}</strong></div><div class="mini-kpi"><span>Activation tasks</span><strong>${tasks.filter(t => t.cat !== "Reports").length}</strong></div><div class="mini-kpi"><span>Assignees</span><strong>${new Set(tasks.map(t => t.rep)).size}</strong></div>`;
  document.getElementById("serviceRows").innerHTML = tasks.slice(0, 180).map(t => `
    <div class="tracker-row" data-id="${esc(t.id)}" style="cursor:pointer; grid-template-columns: 28px 1fr 1.4fr .7fr .7fr 40px;">
      <span onclick="event.stopPropagation()">${t.checkable ? `<input type="checkbox" class="service-task-check" aria-label="Mark this to-do complete" data-id="${esc(t.id)}" data-tasktext="${esc(t.task)}" title="Mark this to-do complete">` : ""}</span>
      <div><strong>${esc(t.sponsor)}</strong><small>${esc(t.cat)}</small></div>
      <div><strong style="font-size:var(--text-xs);">${esc(t.task)}</strong></div>
      <div><small>Assigned to</small><strong style="font-size:var(--text-xs);">${esc(t.rep)}</strong></div>
      <span class="risk-badge medium">Open</span>
      <button class="row-action" title="Open" aria-label="Open ${esc(t.sponsor || "this to-do")}">→</button>
    </div>`).join("") || `<div style="padding:var(--space-40); text-align:center; color:var(--muted);">No open service tasks found.</div>`;
  document.querySelectorAll("#serviceRows .tracker-row").forEach(row => row.addEventListener("click", () => openDrawer(row.dataset.id)));
  document.querySelectorAll("#serviceRows .service-task-check").forEach(cb => {
    cb.addEventListener("click", e => e.stopPropagation());
    cb.addEventListener("change", e => {
      e.stopPropagation();
      const id = cb.dataset.id;
      const r = getRecord(id);
      if (!r) return;
      /* index213: completing used to splice by the index captured at render time — if the 8s
         poll or a teammate reordered the to-dos in between, the WRONG task was deleted, silently
         and permanently. Now it removes the exact text, and refuses if the text is gone. */
      const lines = (r.todo || "").split("\n").map(t => t.trim()).filter(Boolean);
      const ti = lines.indexOf(String(cb.dataset.tasktext || "").trim());
      if (ti < 0) { toast("That to-do changed", "The list was updated elsewhere — refreshing"); refreshCurrentView(); return; }
      lines.splice(ti, 1);
      updateOverride(id, { todo: lines.join("\n") || null });
      toast("To-do completed", r.sponsor);
      refreshCurrentView();
    });
  });
}
/* ================= ASSET PREP HUB ================= */
const apState = { tab: "run", sponsorId: "", status: "New sponsor", timing: null, recipients: "", assets: "", notes: "", tplStatus: "New sponsor", tplTiming: "In-season", tplDraft: null, specDraft: null };
function apSponsorList() {
  return getAllRecords().filter(r => r.sponsor && !r.hidden).sort((a, b) => (a.sponsor || "").localeCompare(b.sponsor || ""));
}
function apGuessStatus(r) {
  if (!r) return "New sponsor";
  try { if (r._custom || !(r.seasons && r.seasons.length) && !(r.historicalValues && r.historicalValues.length)) return "New sponsor"; } catch (e) {}
  return "Returning sponsor";
}
function apDealAssetLines(r) {
  if (!r) return [];
  // Email/prefill names use the clean bracket CATEGORY (e.g. "Digital Marquee", "Upper Tier
  // Billboard") so the deal list reads as canonical asset names that map 1:1 to the Asset Spec
  // Library — not the messy master-sheet free-text/notes. Underlying deal data is untouched.
  // Lines with no [bracket] fall back to the note-stripped label (assetLabelOf).
  let names = [];
  try {
    const lines = parseSponsorAssetLines(r.assets || "");
    if (lines.length) names = lines.map(l => ({ nm: (l.category || assetLabelOf(l.text) || "").trim(), qty: "" }));
  } catch (e) {}
  if (!names.length) {
    let rows = [];
    try { rows = dealAssetsFor(r) || []; } catch (e) { rows = []; }
    names = rows.map(a => ({ nm: assetLabelOf(String(a.asset || a.name || "").trim()), qty: String(a.qty || "").trim() }));
  }
  return [...new Set(names.map(a => {
    if (!a.nm) return "";
    return a.qty && a.qty !== "1" ? `${a.nm} (${a.qty})` : a.nm;
  }).filter(Boolean))];
}
function apPrefillFromSponsor(r) {
  apState.assets = apDealAssetLines(r).join("\n");
  // Recipient: first contact with an email, else primary/email on the record.
  let rec = "";
  const c = (r.contacts || []).find(x => x && x.email) || (r.contacts || [])[0];
  if (c) rec = c.email ? (c.name ? `${c.name} <${c.email}>` : c.email) : (c.name || "");
  else if (r.email) rec = r.primary ? `${r.primary} <${r.email}>` : r.email;
  else if (r.primary) rec = r.primary;
  apState.recipients = rec;
  apState.status = apGuessStatus(r);
}
function apRequestObj() {
  const r = apState.sponsorId ? getRecord(apState.sponsorId) : null;
  return { sponsorName: r ? r.sponsor : "", sponsorId: apState.sponsorId,
    fields: { recipients: apState.recipients || "", tone: apState.status, timing: apState.timing || currentPrepTiming(), assets: apState.assets || "", notes: apState.notes || "" } };
}
function assetPrepEmailYear() {
  return String((typeof sState === "object" && sState.season) || new Date().getFullYear());
}
function assetPrepSubject(sponsorName) {
  return `${assetPrepEmailYear()} Jersey Shore BlueClaws Asset Prep - ${sponsorName || "Sponsor"}`;
}
function assetPrepCcList(record) {
  const senderName = (typeof currentUser === "function" ? currentUser() : "") || "";
  const senderEmail = typeof blueclawsEmail === "function" ? blueclawsEmail(senderName) : "";
  const base = ["Zack Nicol", "Tommy Shara", "Greg Millaway", "Rob Vota"];
  const rep = String(record?.rep || "").trim();
  if (rep && !/^rob\s+vota$/i.test(rep)) base.push(rep);
  const seen = new Set();
  return base
    .map(name => ({ name, email: typeof blueclawsEmail === "function" ? blueclawsEmail(name) : "" }))
    .filter(x => x.email && x.email !== senderEmail && x.name.toLowerCase() !== senderName.toLowerCase())
    .filter(x => { const key = x.email.toLowerCase(); if (seen.has(key)) return false; seen.add(key); return true; })
    .map(x => x.email)
    .join(",");
}
function emailAddressesFromText(text) {
  return [...new Set(String(text || "").match(/[^\s<>,;()]+@[^\s<>,;()]+/g) || [])].join(",");
}
function assetPrepToList(record, recipientsText) {
  const typed = emailAddressesFromText(recipientsText);
  if (typed) return typed;
  const contacts = Array.isArray(record?.contacts) ? record.contacts : [];
  const savedContacts = contacts.map(c => c && c.email).filter(Boolean).join(",");
  return emailAddressesFromText(savedContacts || record?.email || "");
}
function apUpdatePreview() {
  const el = document.getElementById("apPreview");
  if (!el) return;
  if (!apState.sponsorId) { el.textContent = "Pick a sponsor above to build the email."; return; }
  el.innerHTML = apEmailPreviewHTML(buildAssetPrepEmail(apRequestObj()));
}
function apEmailPreviewHTML(text) {
  return esc(text)
    .replace(/\*\*([^*\n]+)\*\*/g, '<strong>$1</strong>')
    .replace(/(\({0,1}_{2,}\){0,1})/g, '<mark class="ap-placeholder-mark">$1</mark>');
}
function assetPrepPlainEmail(text) {
  return String(text || "").replace(/\*\*([^*\n]+)\*\*/g, "$1");
}
function assetPrepRichEmailHTML(text) {
  return `<div>${esc(text).replace(/\*\*([^*\n]+)\*\*/g, '<strong>$1</strong>').replace(/\n/g, "<br>")}</div>`;
}
function copyAssetPrepEmail(bodyText) {
  return copyRichToClipboard(assetPrepRichEmailHTML(bodyText), assetPrepPlainEmail(bodyText));
}
function assetPrepAttachmentNote() {
  return "Attachments to add before sending: JSB Primary Logo.png and 2027 BlueClaws Schedule.pdf";
}
function renderAssetPrepView() {
  if (apState.timing == null) apState.timing = currentPrepTiming();
  document.querySelectorAll("#assetPrepTabs [data-ap-tab]").forEach(b => b.classList.toggle("is-active", b.dataset.apTab === apState.tab));
  const body = document.getElementById("assetPrepBody");
  if (!body) return;
  if (apState.tab === "run") renderApRun(body);
  else if (apState.tab === "templates") renderApTemplates(body);
  else renderApSpecs(body);
}
document.addEventListener("click", e => {
  const tab = e.target.closest("#assetPrepTabs [data-ap-tab]");
  if (tab) { apState.tab = tab.dataset.apTab; renderAssetPrepView(); }
});
function renderApRun(body) {
  const sponsors = apSponsorList();
  const opts = `<option value="">Select sponsor…</option>` + sponsors.map(r => `<option value="${esc(r.id)}"${r.id === apState.sponsorId ? " selected" : ""}>${esc(r.sponsor)}</option>`).join("");
  const statusOpts = PREP_STATUSES.map(s => `<option value="${esc(s)}"${s === apState.status ? " selected" : ""}>${esc(s)}</option>`).join("");
  const timingOpts = PREP_TIMINGS.map(t => `<option value="${esc(t)}"${t === (apState.timing || currentPrepTiming()) ? " selected" : ""}>${esc(t)}${t === currentPrepTiming() ? " (now)" : ""}</option>`).join("");
  body.innerHTML = `
    <div class="table-card" style="padding:var(--space-18); margin-bottom:var(--space-14);">
      <div class="sfield-grid" style="grid-template-columns:1.4fr 1fr 1fr; gap:var(--space-12);">
        <div class="sfield"><label for="apSponsor">Sponsor</label><select id="apSponsor">${opts}</select></div>
        <div class="sfield"><label for="apStatus">Template — partner type</label><select id="apStatus">${statusOpts}</select></div>
        <div class="sfield"><label for="apTiming">Time of year</label><select id="apTiming">${timingOpts}</select></div>
      </div>
      <div class="sfield" style="margin-top:var(--space-10);"><label for="apRecipients">Client recipient(s)</label><input id="apRecipients" placeholder="Name &lt;email@company.com&gt;, second@company.com" value="${esc(apState.recipients)}"></div>
      <div class="sfield-grid" style="grid-template-columns:1fr 1fr; gap:var(--space-12); margin-top:var(--space-6);">
        <div class="sfield"><label for="apAssets">All assets in the deal <span style="color:var(--muted); font-weight:400;">(one per line - prefilled from the sponsor)</span></label><textarea id="apAssets" style="min-height:150px;">${esc(apState.assets)}</textarea></div>
        <div class="sfield"><label for="apNotes">Extra notes (optional)</label><textarea id="apNotes" style="min-height:150px;" placeholder="Anything specific to add at the end of the email">${esc(apState.notes)}</textarea></div>
      </div>
      <div style="display:flex; flex-wrap:wrap; gap:var(--space-8); margin-top:var(--space-12);">
        <button class="primary-button" id="apOpenMail" type="button">Open in mail + save to sponsor</button>
        <button class="secondary-button" id="apCopy" type="button">Copy email</button>
        <button class="secondary-button" id="apSaveOnly" type="button">Save contact + assets to sponsor</button>
      </div>
      <div class="readonly-note" style="margin-top:var(--space-8);">Opening or saving adds the recipient as a contact and any new assets to this sponsor's deal &amp; fulfillment lists — existing entries are never overwritten.</div>
    </div>
    <div class="table-card" style="padding:var(--space-18);">
      <div class="table-toolbar" style="padding:0 0 var(--space-10);"><strong style="font-size:14px;">Email preview</strong><span style="margin-left:auto; color:var(--muted); font-size:var(--text-xs);">Built live from the template + spec library</span></div>
      <div id="apPreview" class="ap-preview"></div>
    </div>`;
  const sel = document.getElementById("apSponsor");
  sel.addEventListener("change", () => { apState.sponsorId = sel.value; const r = getRecord(sel.value); if (r) apPrefillFromSponsor(r); renderApRun(body); });
  document.getElementById("apStatus").addEventListener("change", e => { apState.status = e.target.value; apUpdatePreview(); });
  document.getElementById("apTiming").addEventListener("change", e => { apState.timing = e.target.value; apUpdatePreview(); });
  document.getElementById("apRecipients").addEventListener("input", e => { apState.recipients = e.target.value; apUpdatePreview(); });
  document.getElementById("apAssets").addEventListener("input", e => { apState.assets = e.target.value; apUpdatePreview(); });
  document.getElementById("apNotes").addEventListener("input", e => { apState.notes = e.target.value; apUpdatePreview(); });
  document.getElementById("apCopy").addEventListener("click", () => {
    if (!apState.sponsorId) { toast("Pick a sponsor", "Choose who this prep email is for first."); return; }
    const o = apRequestObj();
    const bodyText = buildAssetPrepEmail(o);
    const text = `${assetPrepSubject(o.sponsorName)}\n\n` + assetPrepPlainEmail(bodyText);
    copyRichToClipboard(assetPrepRichEmailHTML(bodyText), text)
      .then(() => toast("Copied", "Asset prep email copied with bold section headings — paste it into your composer.", true))
      .catch(() => toast("Couldn't copy", "Select the preview text and copy it manually."));
  });
  document.getElementById("apSaveOnly").addEventListener("click", () => {
    if (!apState.sponsorId) { toast("Pick a sponsor", "Choose the sponsor first."); return; }
    const w = persistPrepToSponsor(apState.sponsorId, apState.recipients, apState.assets);
    const r = getRecord(apState.sponsorId);
    toast("Saved to sponsor", `${w.contacts} contact${w.contacts === 1 ? "" : "s"} and ${w.assets} asset${w.assets === 1 ? "" : "s"} added to ${r ? r.sponsor : "the sponsor"}${(!w.contacts && !w.assets) ? " — nothing new to add" : ""}.`, true);
  });
  document.getElementById("apOpenMail").addEventListener("click", () => {
    if (!apState.sponsorId) { toast("Pick a sponsor", "Choose who this prep email is for first."); return; }
    const o = apRequestObj();
    const sponsorRecord = apState.sponsorId ? getRecord(apState.sponsorId) : null;
    const subject = assetPrepSubject(o.sponsorName);
    const bodyText = buildAssetPrepEmail(o);
    const mailBody = assetPrepPlainEmail(bodyText);
    const to = assetPrepToList(sponsorRecord, apState.recipients);
    const cc = assetPrepCcList(sponsorRecord);
    const _copy = copyAssetPrepEmail(bodyText);
    const w = persistPrepToSponsor(apState.sponsorId, apState.recipients, apState.assets);
    if (typeof openMailDraft === "function") openMailDraft(to, subject, mailBody, cc);
    /* index242 — this claimed "copied" whether or not the clipboard accepted it. */
    _copy.then(copied => {
      const saved = (w.contacts || w.assets) ? ` Saved ${w.contacts} contact${w.contacts === 1 ? "" : "s"} and ${w.assets} asset${w.assets === 1 ? "" : "s"} to the sponsor.` : "";
      toast("Asset Prep drafted", `Opened in your composer${copied ? " and copied the email body to your clipboard" : " — this browser blocked the clipboard copy, so use the preview below"}.${saved} ${assetPrepAttachmentNote()}.`, true);
    });
  });
  apUpdatePreview();
}
function renderApTemplates(body) {
  if (!apState.tplDraft) apState.tplDraft = loadPrepTemplates();
  const statusTabs = PREP_STATUSES.map(s => `<button type="button" class="secondary-button${s === apState.tplStatus ? " is-on" : ""}" data-ap-tplstatus="${esc(s)}" style="${s === apState.tplStatus ? "border-color:var(--blue-text); color:var(--blue-text);" : ""}">${esc(s)}</button>`).join("");
  const timingTabs = PREP_TIMINGS.map(t => `<button type="button" class="secondary-button${t === apState.tplTiming ? " is-on" : ""}" data-ap-tpltiming="${esc(t)}" style="${t === apState.tplTiming ? "border-color:var(--blue-text); color:var(--blue-text);" : ""}">${esc(t)}${t === currentPrepTiming() ? " • now" : ""}</button>`).join("");
  const val = (apState.tplDraft[apState.tplStatus] && apState.tplDraft[apState.tplStatus][apState.tplTiming]) || "";
  body.innerHTML = `
    <div class="table-card" style="padding:var(--space-18);">
      <div class="readonly-note" style="margin-bottom:var(--space-10);">Edit the intro paragraph for each partner type and time of year. Use <strong>{sponsor}</strong> to drop in the sponsor's name. The rest of the email (logos line, per-asset specs, your notes) is assembled from the spec library.</div>
      <div style="display:flex; flex-wrap:wrap; gap:var(--space-6); margin-bottom:var(--space-8);">${statusTabs}</div>
      <div style="display:flex; flex-wrap:wrap; gap:var(--space-6); margin-bottom:var(--space-12);">${timingTabs}</div>
      <div class="sfield"><label for="apTplText">${esc(apState.tplStatus)} · ${esc(apState.tplTiming)} intro</label><textarea id="apTplText" style="min-height:180px;">${esc(val)}</textarea></div>
      <div style="display:flex; flex-wrap:wrap; gap:var(--space-8); margin-top:var(--space-12);">
        <button class="primary-button" id="apTplSave" type="button">Save templates</button>
        <button class="secondary-button" id="apTplReset" type="button">Reset all to defaults</button>
      </div>
    </div>`;
  body.querySelectorAll("[data-ap-tplstatus]").forEach(b => b.addEventListener("click", () => { apState.tplStatus = b.dataset.apTplstatus; renderApTemplates(body); }));
  body.querySelectorAll("[data-ap-tpltiming]").forEach(b => b.addEventListener("click", () => { apState.tplTiming = b.dataset.apTpltiming; renderApTemplates(body); }));
  document.getElementById("apTplText").addEventListener("input", e => {
    if (!apState.tplDraft[apState.tplStatus]) apState.tplDraft[apState.tplStatus] = {};
    apState.tplDraft[apState.tplStatus][apState.tplTiming] = e.target.value;
  });
  document.getElementById("apTplSave").addEventListener("click", () => { savePrepTemplates(apState.tplDraft); toast("Templates saved", "Your asset prep intros are stored on this browser.", true); });
  document.getElementById("apTplReset").addEventListener("click", async () => { if (!(await bcConfirm("Reset all asset prep email templates back to the built-in defaults?", {title:"Reset templates", ok:"Reset", danger:true}))) return; resetPrepTemplates(); apState.tplDraft = loadPrepTemplates(); renderApTemplates(body); /* index242: the fields visibly repaint — no toast needed */ });
}
function alStatusMeta(s) {
  return s === 'complete' ? { label: 'Complete ✓', bd: 'var(--blue)', bg: '#e7f0fb', fg: 'var(--blue-text)' }
       : s === 'verify'   ? { label: 'Prep language saved', bd: 'var(--gold)', bg: '#fff7db', fg: '#7a5b00' }
       :                    { label: 'No spec', bd: 'var(--red)', bg: '#fbeaec', fg: 'var(--red)' };
}
function alDetail(a) {
  const catM = String(a.incat || '').match(/^(\d+)\s*\/\s*(\d+)\s*\/\s*(\d+)$/);
  const catStr = catM ? `${catM[1]} available · ${catM[2]} reserved · ${catM[3]} confirmed` : (a.incat || '');
  const fields = [['Description', a.desc], ['Specs', a.specs], ['Artwork', a.art], ['Asset date', a.adate], ['Due', a.due], ['Gameday dates', a.gdates], ['Rate', a.rate], ['Frequency', a.freq], ['Inclusions', a.incl], ['# sponsors', a.sponsors], ['In catalog', catStr]];
  const rows = fields.filter(r => r[1]).map(r => `<div style="margin-bottom:6px;"><span style="color:var(--muted); font-size:var(--text-xs); text-transform:uppercase; letter-spacing:.04em;">${esc(r[0])}</span><div style="white-space:pre-wrap;">${esc(String(r[1]))}</div></div>`).join('');
  let vh = '';
  if (a.variants && a.variants.length) {
    vh = `<div style="margin-top:8px;"><span style="color:var(--muted); font-size:var(--text-xs); text-transform:uppercase; letter-spacing:.04em;">${a.variants.length} options in this asset</span>`
       + `<div style="display:flex; flex-wrap:wrap; gap:6px; margin-top:6px;">`
       + a.variants.map(v => { const m = alStatusMeta(v.status); return `<span class="type-tag" style="background:${m.bg}; color:${m.fg}; border-color:${m.bd};" title="${esc([v.rate, v.freq].filter(Boolean).join(' · '))}">${esc(v.name)}</span>`; }).join('')
       + `</div></div>`;
  }
  return `<div class="table-card" style="padding:14px; margin-top:0; border:none; border-top:1px solid var(--line); border-radius:0;">${rows || '<div class="readonly-note">No spec details in the sheet yet.</div>'}${vh}</div>`;
}
/* index185: Asset Spec Library rebuilt to mirror the BlueClaws master sheet's Assets tab.
   Data source is window.ASSET_LIBRARY_SEED (built from the audit CSV, one tile per asset
   family — variants like "In Game Promotion: Cow Race" fold into one "In Game Promotion"
   tile with the variants shown as options). A collapsible accordion by the sheet's 8 asset
   categories (expand a category to see its assets + prep notes), thin rows, 3 spec-status
   colors (Spec saved=blue, Prep language saved=gold, Needs spec=red), plus sort + filter. */
function renderApSpecs(body) {
  const st = apState;
  if (st.specSearch == null) st.specSearch = '';
  if (st.specGroup == null) st.specGroup = 'all';
  if (st.specStat == null) st.specStat = 'all';
  if (st.specSort == null) st.specSort = 'category';
  if (!st.specOpen) st.specOpen = {};
  if (!st.specCatOpen) st.specCatOpen = {};
  const data = (window.ASSET_LIBRARY_SEED || []);
  const GROUPS = ['Signage', 'Gameday', 'Naming / Entitlement', 'Weekly Promotion', 'Marketing / Digital', 'Hospitality / Tickets', 'Food & Beverage', 'Other'];
  const catCols = ['var(--blue)', 'var(--gold)', 'var(--red)', 'var(--navy)'];
  const q = String(st.specSearch || '').trim().toLowerCase();
  const tot = data.length;
  const cc = data.filter(a => a.status === 'complete').length;
  const cv = data.filter(a => a.status === 'verify').length;
  const cn = data.filter(a => a.status === 'none').length;
  let list = data.slice();
  if (st.specGroup !== 'all') list = list.filter(a => a.group === st.specGroup);
  if (st.specStat !== 'all') list = list.filter(a => a.status === st.specStat);
  if (q) list = list.filter(a => (a.name || '').toLowerCase().includes(q) || (a.variants || []).some(v => (v.name || '').toLowerCase().includes(q)) || (a.desc || '').toLowerCase().includes(q));
  const rank = { complete: 0, verify: 1, none: 2 };
  const money = r => { const m = String(r || '').replace(/[^0-9.]/g, ''); return m ? parseFloat(m) : -1; };
  if (st.specSort === 'az') list.sort((a, b) => a.name.localeCompare(b.name));
  else if (st.specSort === 'status') list.sort((a, b) => rank[a.status] - rank[b.status] || a.name.localeCompare(b.name));
  else if (st.specSort === 'rate') list.sort((a, b) => money(b.rate) - money(a.rate) || a.name.localeCompare(b.name));
  else list.sort((a, b) => { const ga = GROUPS.indexOf(a.group), gb = GROUPS.indexOf(b.group); return (ga < 0 ? 99 : ga) - (gb < 0 ? 99 : gb) || a.name.localeCompare(b.name); });
  const rowHtml = a => {
    const i = data.indexOf(a);
    const open = !!st.specOpen[i];
    const m = alStatusMeta(a.status);
    const meta = [a.rate, a.freq, a.cat].filter(Boolean).join(' · ');
    const pill = `<span class="type-tag" style="background:${m.bg}; color:${m.fg}; border-color:${m.bd};">${m.label}${a.nvar > 1 ? ` · ${a.nvar}` : ''}</span>`;
    return `<div class="table-card" style="padding:0; margin-bottom:6px; border-left:3px solid ${m.bd};">
      <div class="renewal-row" style="grid-template-columns:1fr auto auto; align-items:center; cursor:pointer; padding:8px 14px;" data-al-toggle="${i}">
        <div style="min-width:0;"><strong style="display:block;">${esc(a.name)}</strong>${meta ? `<small style="color:var(--muted);">${esc(meta)}</small>` : ''}</div>
        ${pill}
        <button type="button" class="row-action" aria-label="Expand" style="transform:rotate(${open ? '90' : '0'}deg); transition:transform .12s;">→</button>
      </div>${open ? alDetail(a) : ''}</div>`;
  };
  let listHtml;
  if (st.specSort === 'category') {
    // Collapsible accordion: one section per asset category (like the sidebar workspace nav).
    const byg = {}; list.forEach(a => { (byg[a.group] = byg[a.group] || []).push(a); });
    const order = [...GROUPS.filter(g => byg[g]), ...Object.keys(byg).filter(g => !GROUPS.includes(g)).sort()];
    listHtml = order.map((g, gi) => {
      const items = byg[g];
      // auto-open a category when a search or a specific status filter is narrowing results
      const forced = !!q || st.specStat !== 'all';
      const open = forced || !!st.specCatOpen[g];
      const gc = items.filter(a => a.status === 'complete').length;
      const gv = items.filter(a => a.status === 'verify').length;
      const gn = items.filter(a => a.status === 'none').length;
      const breakdown = `<span style="color:var(--muted); font-size:var(--text-xs);"><span style="color:var(--blue-text);">${gc}</span> · <span style="color:#7a5b00;">${gv}</span> · <span style="color:var(--red);">${gn}</span></span>`;
      return `<div class="table-card" style="padding:0; margin-bottom:8px; border-left:4px solid ${catCols[gi % 4]};">
        <div class="renewal-row" style="grid-template-columns:auto 1fr auto auto; align-items:center; cursor:pointer; padding:13px 14px; gap:10px;" data-al-cat="${esc(g)}">
          <button type="button" class="row-action" aria-label="Expand category" style="transform:rotate(${open ? '90' : '0'}deg); transition:transform .12s;">→</button>
          <strong style="font-family:var(--font-display, inherit); letter-spacing:.02em; font-size:var(--text-md, 1rem);">${esc(g)}</strong>
          <span class="type-tag" style="opacity:.75;">${items.length}</span>
          ${breakdown}
        </div>
        ${open ? `<div style="padding:0 10px 10px;">${items.map(rowHtml).join('')}</div>` : ''}
      </div>`;
    }).join('');
  } else {
    listHtml = list.map(rowHtml).join('');
  }
  if (!list.length) listHtml = `<div class="readonly-note">No assets match your filters.</div>`;
  const opt = (v, cur, lbl) => `<option value="${esc(v)}"${v === cur ? ' selected' : ''}>${esc(lbl)}</option>`;
  body.innerHTML = `
    <div class="readonly-note" style="margin-bottom:var(--space-10);">Display only — this library shows each asset's spec as reference and can't be edited here. Rates, quantities, details, and contract language are edited in the <button type="button" class="glance-link" style="display:inline; padding:0;" onclick="showView('assetledger')">Asset Ledger →</button></div>
    <div class="filter-bar">
      <div class="search-box">⌕ <input id="alSearch" type="search" placeholder="Search assets…" value="${esc(st.specSearch)}"></div>
      <select id="alGroup" aria-label="Category">${opt('all', st.specGroup, `All categories (${tot})`)}${GROUPS.map(g => opt(g, st.specGroup, g)).join('')}</select>
      <select id="alStat" aria-label="Spec status">${opt('all', st.specStat, 'All statuses')}${opt('complete', st.specStat, `Spec saved (${cc})`)}${opt('verify', st.specStat, `Prep language saved (${cv})`)}${opt('none', st.specStat, `Needs spec (${cn})`)}</select>
      <select id="alSort" aria-label="Sort">${opt('category', st.specSort, 'Sort: category')}${opt('status', st.specSort, 'Sort: status (color)')}${opt('az', st.specSort, 'Sort: A–Z')}${opt('rate', st.specSort, 'Sort: rate')}</select>
      <span style="margin-left:auto; color:var(--muted); font-size:var(--text-xs); align-self:center;">${tot} assets · <span style="color:var(--blue-text);">${cc} specs saved</span> · <span style="color:#7a5b00;">${cv} prep language</span> · <span style="color:var(--red);">${cn} needs spec</span></span>
    </div>
    ${st.specSort === 'category' ? `<div style="display:flex; gap:8px; margin-bottom:10px;"><button type="button" class="secondary-button" id="alExpandAll">Expand all</button><button type="button" class="secondary-button" id="alCollapseAll">Collapse all</button></div>` : ''}
    <div id="alList">${listHtml}</div>`;
  const s = document.getElementById('alSearch');
  if (s) s.addEventListener('input', e => { st.specSearch = e.target.value; renderApSpecs(body); const n = document.getElementById('alSearch'); if (n) { n.focus(); n.setSelectionRange(n.value.length, n.value.length); } });
  const gg = document.getElementById('alGroup'); if (gg) gg.addEventListener('change', e => { st.specGroup = e.target.value; renderApSpecs(body); });
  const ss = document.getElementById('alStat'); if (ss) ss.addEventListener('change', e => { st.specStat = e.target.value; renderApSpecs(body); });
  const so = document.getElementById('alSort'); if (so) so.addEventListener('change', e => { st.specSort = e.target.value; renderApSpecs(body); });
  const ea = document.getElementById('alExpandAll'); if (ea) ea.addEventListener('click', () => { data.forEach(a => { st.specCatOpen[a.group] = true; }); renderApSpecs(body); });
  const ca = document.getElementById('alCollapseAll'); if (ca) ca.addEventListener('click', () => { st.specCatOpen = {}; renderApSpecs(body); });
  body.querySelectorAll('[data-al-cat]').forEach(row => row.addEventListener('click', () => { const g = row.dataset.alCat; st.specCatOpen[g] = !st.specCatOpen[g]; renderApSpecs(body); }));
  body.querySelectorAll('[data-al-toggle]').forEach(row => row.addEventListener('click', () => { const i = row.dataset.alToggle; st.specOpen[i] = !st.specOpen[i]; renderApSpecs(body); }));
}

/* ================= REQUESTS & TASKS (Phase 1 + Phase 2) =================
   Phase 1 built the spine: one request, one owner, one status, one activity log.
   Phase 2 adds the three things that actually make it a workflow:
     1. Approval chains (configurable, with an explicit answer to every edge case)
     2. Revision loops with version history
     3. Automatic deal-stage advancement (forward only, override always allowed)

   Decisions made explicit here, because guessing would have produced silent bugs:
     - An approver who is unavailable can be SKIPPED by anyone, but the skip is
       logged with a reason and the name of who skipped them. There is no silent
       bypass. Approvals can also be delegated to a named person.
     - A revision resets EVERY approval back to pending. A deck that changed is not
       the deck anyone approved.
     - The requesting rep IS an approver by design (they're reviewing the service
       team's work). But whoever BUILT it (the owner) cannot approve it, even if
       they're also on the approver list. Self-approval is blocked.
     - There is no automatic escalation or timeout, because that needs email.
       Instead, approvals pending more than APPROVAL_STALE_DAYS get flagged in red
       and surface in their own KPI so nothing rots quietly.

   Phase 3 — Contract Signed cascade: BUILT (index143). Completing an Agreement
   request fires runContractSignedCascade(): advances the deal stage to Signed,
   sets Renewal Outlook to "N/A - New Partner" (unless set by hand), generates
   fulfillment items from the signed assets (default Need To Do), writes a
   structured payment schedule, ensures the signing season record + contract
   total, and tags the named signer as "Agreement Signer" on contacts[].
   Idempotent via r.cascadeRan. (Renewal Outlook was already a real field —
   r.outlook / OUTLOOK_LABELS — so that older note was stale.)

   Still NOT built — and NOT a code change:
     - Real email delivery. "Draft notification email" builds a mailto and copies
       to the clipboard; a static Netlify file cannot send mail. Automated send
       needs a Netlify Function + provider (Resend/SendGrid) + a verified
       @blueclaws.com domain — an IT task, not a code task.
     - Permission levels — the identity picker is attribution, not auth. */

