/* Configurable approval chains — the spec asked for approvers to be changeable
   without rebuilding the app, so this lives in synced storage, not in code.
   "__requester" resolves at runtime to whoever submitted the request. */
const APPROVAL_CONFIG_KEY = "bciq_approval_config";
const DEFAULT_APPROVAL_CONFIG = {
  serviceTeam: ["Zack Nicol", "Tommy Shara", "Greg Millaway"],
  contract_signed: ["__requester"],
  confirm_partner_details: ["__requester"],
  upload_agreement: ["__requester"],
  create_breakdown: ["Rob Vota"],
  first_meeting: ["__requester", "Rob Vota"],
  sponsor_task: ["__requester"],
  custom_options: ["__requester", "Rob Vota", "Bob McLane"],
  custom_presentation: ["__requester", "Rob Vota", "Bob McLane"],
  term_sheet: ["__requester", "Rob Vota", "Bob McLane"],
  agreement: ["__requester", "Rob Vota", "Bob McLane"],
  asset_prep: ["__requester"]
};
function loadApprovalConfig() {
  try {
    const v = JSON.parse(memStore.getItem(APPROVAL_CONFIG_KEY));
    if (v && typeof v === "object") {
      const cfg = Object.assign({}, DEFAULT_APPROVAL_CONFIG, v);
      const svc = Array.isArray(cfg.serviceTeam) ? cfg.serviceTeam.slice() : [];
      const has = n => svc.some(x => String(x || "").trim().toLowerCase() === n.toLowerCase());
      if (!svc.length) cfg.serviceTeam = DEFAULT_APPROVAL_CONFIG.serviceTeam.slice();
      else if (!has("Greg Millaway") && (has("Cap") || has("Zack Nicol") || has("Tommy Shara"))) {
        cfg.serviceTeam = svc.filter(n => String(n || "").trim().toLowerCase() !== "cap");
        if (!cfg.serviceTeam.some(n => String(n || "").trim().toLowerCase() === "greg millaway")) cfg.serviceTeam.push("Greg Millaway");
      }
      return cfg;
    }
  } catch {}
  return Object.assign({}, DEFAULT_APPROVAL_CONFIG);
}
function saveApprovalConfig(cfg) {
  memStore.setItem(APPROVAL_CONFIG_KEY, JSON.stringify(cfg));
  pushSharedData("approvalConfig", { value: JSON.stringify(cfg) });
}

function loadRequests() { try { const v = JSON.parse(memStore.getItem(REQUESTS_KEY)); return Array.isArray(v) ? v : []; } catch { return []; } }
function saveRequests(arr) {
  const payload = JSON.stringify(arr);
  memStore.setItem(REQUESTS_KEY, payload);
  return pushSharedData("requests", { value: payload });
}
let requestLivePulling = false;
function requestTaskViewIsActive() {
  const id = document.querySelector(".view.active")?.id || "";
  return ["requestsView", "mytasksView", "serviceView"].includes(id);
}
async function pullSharedRequestsData(opts = {}) {
  if (!SHARED_SYNC_ENABLED || requestLivePulling) return false;
  requestLivePulling = true;
  try {
    await flushSharedQueue();
    const res = await fetch(SHARED_DATA_ENDPOINT + "?bucket=overrides", { cache: "no-store" });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const shared = await res.json();
    const incoming = shared.requests;
    if (!incoming || incoming.value === undefined || hasPendingWrite("requests", "overrides") || recentlyPushed("requests", "overrides")) return false;
    const serverValue = incoming.value == null ? null : String(incoming.value);
    const current = memStore.getItem(REQUESTS_KEY);
    if (serverValue !== null && serverValue !== current) {
      memStore.setItem(REQUESTS_KEY, serverValue);
      if (!opts.silent) refreshRequestViews();
      return true;
    }
  } catch (e) {
    if (!opts.silent) console.warn("BlueClaws IQ request live pull failed", e);
  } finally {
    requestLivePulling = false;
  }
  return false;
}
function refreshRequestViews() {
  if (document.getElementById("requestsView")?.classList.contains("active")) renderRequestsView();
  if (document.getElementById("mytasksView")?.classList.contains("active")) renderMyTasksView();
  if (document.getElementById("serviceView")?.classList.contains("active")) renderServiceView();
  updateRequestsCount();
}
function currentUser() { try { return memStore.getItem(IDENTITY_KEY) || ""; } catch { return ""; } }
function setCurrentUser(name) {
  const clean = String(name || "").trim();
  try {
    memStore.setItem(IDENTITY_KEY, clean);
    if (clean && typeof registerPresenceName === "function") registerPresenceName(clean);
  } catch {}
}
function ensureCurrentUserPicked() {
  if (currentUser() || document.documentElement.classList.contains("bciq-locked") || ensureCurrentUserPicked._open) return;
  ensureCurrentUserPicked._open = true;
  const save = name => {
    ensureCurrentUserPicked._open = false;
    const clean = String(name || "").trim();
    if (clean) {
      setCurrentUser(clean);
      if (typeof renderRequestsView === "function") renderRequestsView();
      if (typeof renderMyTasksView === "function") renderMyTasksView();
      if (typeof refreshIqOrb === "function") refreshIqOrb();
    }
  };
  const msg = "Who is using BlueClaws IQ on this browser? This sets My Tasks and My Alerts.";
  if (typeof bcPrompt === "function") {
    bcPrompt(msg, "", { title: "Continue as", placeholder: "Full name" }).then(save).catch(() => { ensureCurrentUserPicked._open = false; });
  } else {
    save(window.prompt(msg, ""));
  }
}
window.addEventListener("bciq-unlocked", () => setTimeout(ensureCurrentUserPicked, 150));
setTimeout(ensureCurrentUserPicked, 900);

/* Presence roster: every browser that has picked a name in Settings broadcasts it into
   a small synced list, so @-tagging and assignee pickers reflect who is actually using
   the app — not just the seeded rep list. "Mitchell Zavoda" is always taggable. */
const PRESENCE_KEY = "bciq_presence_names";
const PRESENCE_SEED = ["Mitchell Zavoda"];
function loadPresenceNames() { try { const v = JSON.parse(memStore.getItem(PRESENCE_KEY)); return Array.isArray(v) ? v : []; } catch { return []; } }
function registerPresenceName(name) {
  const n = String(name || "").trim();
  if (!n) return;
  const list = loadPresenceNames();
  if (list.some(x => x.toLowerCase() === n.toLowerCase())) return;
  list.push(n);
  memStore.setItem(PRESENCE_KEY, JSON.stringify(list));
  if (typeof pushSharedData === "function") pushSharedData("presenceNames", { value: JSON.stringify(list) }, "overrides");
}
function reqPeople() {
  const set = [];
  const add = n => { const t = String(n || "").trim(); if (t && !set.some(x => x.toLowerCase() === t.toLowerCase())) set.push(t); };
  try { serviceTeamNames().forEach(add); } catch (e) {}
  loadServiceReps().forEach(add);
  loadReps().forEach(add);
  PRESENCE_SEED.forEach(add);
  loadPresenceNames().forEach(add);
  try { add(currentUser()); } catch (e) {}
  return set.sort((a, b) => a.localeCompare(b));
}
/* Emails are first initial + last name @blueclaws.com (per the department's convention). */
function blueclawsEmail(name) {
  const parts = String(name || "").trim().split(/\s+/).filter(Boolean);
  if (parts.length < 2) return "";
  return (parts[0][0] + parts[parts.length - 1]).toLowerCase().replace(/[^a-z]/g, "") + "@blueclaws.com";
}
function nowStamp() { return new Date().toISOString(); }
function today() { return new Date().toISOString().slice(0, 10); }
function fmtStamp(iso) {
  if (!iso) return "—";
  const d = new Date(iso);
  if (isNaN(d)) return esc(iso);
  return d.toLocaleDateString("en-US", { month: "short", day: "numeric" }) + " " + d.toLocaleTimeString("en-US", { hour: "numeric", minute: "2-digit" });
}
function daysSince(iso) {
  if (!iso) return 0;
  const d = new Date(iso);
  if (isNaN(d)) return 0;
  return Math.floor((Date.now() - d.getTime()) / 86400000);
}
function reqLog(req, action, note) {
  req.log = Array.isArray(req.log) ? req.log : [];
  req.log.unshift({ ts: nowStamp(), who: currentUser() || "Unknown", action, note: note || "" });
}
