let invAvailState = { search: "", filter: "all" };
function renderInventoryAvailability() {
  const wrap = document.getElementById("invAvailRows");
  if (!wrap) return;
  const q = invAvailState.search.trim().toLowerCase();
  let list = INVENTORY_2026.slice();
  if (q) list = list.filter(d => d.a.toLowerCase().includes(q));
  if (invAvailState.filter === "limited") list = list.filter(d => d.av <= 2);
  if (invAvailState.filter === "multi") list = list.filter(d => d.t > 1);
  // Most-constrained first: sold out, then fewest available, then biggest books.
  list.sort((a, b) => (a.av - b.av) || (b.c - a.c) || a.a.localeCompare(b.a));
  if (!list.length) { wrap.innerHTML = `<tr><td colspan="6" style="text-align:center; color:var(--muted); padding:var(--space-20);">No assets match.</td></tr>`; return; }
  wrap.innerHTML = list.map(d => {
    const st = inventoryStatus(d);
    const cls = st.key === "soldout" ? "soldout" : (st.key === "limited" ? "limited" : "available");
    const rate = (d.rt || d.rt === 0) && String(d.rt).length ? fmtMoney(Number(d.rt)) : "—";
    return `<tr>
      <td><strong>${esc(d.a)}</strong></td>
      <td style="text-align:right;">${d.t.toLocaleString()}</td>
      <td style="text-align:right;">${d.c.toLocaleString()}</td>
      <td style="text-align:right; font-weight:700; color:${d.av <= 0 ? "var(--red)" : (d.av <= 2 ? "var(--navy-700, var(--ink))" : "var(--ink)")};">${d.av.toLocaleString()}</td>
      <td><span class="avail-badge ${cls}">${esc(st.label)}</span></td>
      <td style="text-align:right;">${rate}</td>
    </tr>`;
  }).join("");
}
