/* ---- Agreement / Term Sheet request: picked assets, each with a note --------------------------
   Assets used to be a free-text box, which is how a contract ends up with a mis-typed asset name
   in it. They are now rows chosen from the catalogue, and the whole list can be imported off an
   approved Options Creator so the paperwork inherits what was actually signed off. */
const agrAssetRows = {};                       // fieldId -> [{ id, asset, qty, note }]
function agrRowsFor(fieldId) { return agrAssetRows[fieldId] || (agrAssetRows[fieldId] = []); }
function renderAgrAssetRows(fieldId) {
  const host = document.getElementById(fieldId + "_rows");
  const hidden = document.getElementById(fieldId);
  if (!host) return;
  const rows = agrRowsFor(fieldId);
  const catalog = getFullCatalog();
  host.innerHTML = rows.length ? rows.map((r, i) => `
    <div class="agr-asset-row" data-i="${i}">
      <select class="agr-asset-pick" data-i="${i}" aria-label="Asset ${i + 1}">
        <option value="">— Choose an asset —</option>
        ${catalog.map(a => `<option value="${esc(a.id)}"${a.id === r.id ? " selected" : ""}>${esc(a.asset)}</option>`).join("")}
      </select>
      <input class="agr-asset-qty" type="number" min="1" step="1" value="${esc(String(r.qty || 1))}" data-i="${i}" aria-label="Quantity for asset ${i + 1}">
      <input class="agr-asset-note" type="text" placeholder="Note for this asset" value="${esc(r.note || "")}" data-i="${i}" aria-label="Note for asset ${i + 1}">
      <button type="button" class="row-action" data-agr-del="${i}" aria-label="Remove asset ${i + 1}">&times;</button>
    </div>`).join("")
    : `<p class="agr-asset-empty">No assets yet. Import them from a saved Options Creator, or add them one at a time.</p>`;
  // The stored value stays human-readable text, so the agreement generator and the emails that
  // already read this field keep working unchanged.
  if (hidden) hidden.value = rows.filter(r => r.asset).map(r =>
    `${quantityHouseStyle(r.qty || 1)} ${r.asset}${r.note ? ` — ${r.note}` : ""}`).join("\n");
  host.querySelectorAll(".agr-asset-pick").forEach(sel => sel.onchange = e => {
    const row = agrRowsFor(fieldId)[+e.target.dataset.i];
    const a = catalog.find(x => x.id === e.target.value);
    row.id = a ? a.id : ""; row.asset = a ? a.asset : "";
    renderAgrAssetRows(fieldId);
  });
  host.querySelectorAll(".agr-asset-qty").forEach(inp => inp.onchange = e => {
    agrRowsFor(fieldId)[+e.target.dataset.i].qty = Math.max(1, parseInt(e.target.value) || 1);
    renderAgrAssetRows(fieldId);
  });
  host.querySelectorAll(".agr-asset-note").forEach(inp => inp.oninput = e => {
    agrRowsFor(fieldId)[+e.target.dataset.i].note = e.target.value;
    if (hidden) hidden.value = agrRowsFor(fieldId).filter(r => r.asset).map(r =>
      `${quantityHouseStyle(r.qty || 1)} ${r.asset}${r.note ? ` — ${r.note}` : ""}`).join("\n");
  });
  host.querySelectorAll("[data-agr-del]").forEach(btn => btn.onclick = () => {
    agrRowsFor(fieldId).splice(+btn.dataset.agrDel, 1);
    renderAgrAssetRows(fieldId);
  });
}
/* House style from Tab 4: one to ten written out with the numeral in brackets, above ten the
   numeral alone. Reused here so the contract text is right from the start. */
function quantityHouseStyle(n) {
  const words = ["zero","one","two","three","four","five","six","seven","eight","nine","ten"];
  const q = Number(n) || 1;
  return q >= 1 && q <= 10 ? `${words[q]} (${q})` : String(q);
}
/* ---- N31: payment schedule -----------------------------------------------------------------
   Was a free-text box, so nothing stopped a schedule that did not add up to the contract value.
   Now: choose 1-12 payments, get that many date/amount lines split evenly off Pricing, override
   any of them, and the total turns red the moment it stops matching. */
const agrPayRows = {};
function agrPayFor(id) { return agrPayRows[id] || (agrPayRows[id] = []); }
function agrPricingValue() {
  const el = document.getElementById("reqf_pricing");
  if (!el) return 0;
  return parseFloat(String(el.value).replace(/[^\d.]/g, "")) || 0;
}
function splitEvenly(total, n) {
  // Cents are put on the FIRST payment rather than smeared, so the lines stay round numbers and
  // the sum is still exact.
  /* index257: WHOLE DOLLARS ONLY. Every money field in this app strips the decimal point on
     input, so a line rendered as 1,166.68 became 116,668 on the first keystroke and inflated
     the contract 100x. The remainder still lands on payment one, so the sum stays exact. */
  const whole = Math.round(total);
  const base = Math.floor(whole / n);
  const rem = whole - base * n;
  return Array.from({length: n}, (_, i) => (base + (i === 0 ? rem : 0)));
}
function renderAgrPayRows(id) {
  const host = document.getElementById(id + "_rows");
  const totalEl = document.getElementById(id + "_total");
  const hidden = document.getElementById(id);
  if (!host) return;
  const rows = agrPayFor(id);
  host.innerHTML = rows.length ? `
    <div class="agr-pay-head"><span>Date</span><span>Amount</span><span></span></div>
    ${rows.map((r, i) => `
      <div class="agr-pay-row">
        <input type="date" value="${esc(r.date || "")}" data-pay-date="${i}" aria-label="Payment ${i + 1} date">
        <span class="money-wrap">$<input type="text" inputmode="numeric" class="money-input" value="${r.amount ? Number(r.amount).toLocaleString("en-US") : ""}" data-pay-amt="${i}" aria-label="Payment ${i + 1} amount"></span>
        <span class="agr-pay-num">${i + 1} of ${rows.length}</span>
      </div>`).join("")}` : `<p class="agr-asset-empty">Choose a number of payments and the lines will be split from the pricing.</p>`;
  const sum = rows.reduce((a, r) => a + (parseFloat(r.amount) || 0), 0);
  const priced = agrPricingValue();
  const matches = Math.abs(sum - priced) < 0.005;
  if (totalEl) {
    totalEl.className = "agr-pay-total" + (rows.length && !matches ? " is-off" : "");
    totalEl.textContent = !rows.length ? ""
      : matches ? `Total ${fmtMoney(sum)} — matches the pricing.`
      : `Total ${fmtMoney(sum)} vs pricing ${fmtMoney(priced)} — off by ${fmtMoney(Math.abs(sum - priced))}.`;
  }
  if (hidden) hidden.value = rows.filter(r => r.date || r.amount)
    .map((r, i) => `${r.date || "date TBD"} — ${r.amount ? fmtMoney(r.amount) : "amount TBD"}`).join("\n");
  host.querySelectorAll("[data-pay-date]").forEach(inp => inp.onchange = e => {
    agrPayFor(id)[+e.target.dataset.payDate].date = e.target.value;
    renderAgrPayRows(id);
  });
  host.querySelectorAll("[data-pay-amt]").forEach(inp => {
    inp.addEventListener("input", e => {
      const d = e.target.value.replace(/[^\d]/g, "");
      e.target.value = d ? Number(d).toLocaleString("en-US") : "";
    });
    inp.addEventListener("change", e => {
      agrPayFor(id)[+e.target.dataset.payAmt].amount = parseFloat(e.target.value.replace(/[^\d.]/g, "")) || 0;
      renderAgrPayRows(id);
    });
  });
}
function wirePaymentFields() {
  document.querySelectorAll('[id$="_count"]').forEach(sel => {
    const id = sel.id.replace(/_count$/, "");
    if (!document.getElementById(id + "_rows") || !document.getElementById(id + "_total")) return;
    if (!agrPayRows[id]) agrPayRows[id] = [];
    renderAgrPayRows(id);
    sel.onchange = () => {
      const n = parseInt(sel.value) || 0;
      if (!n) { agrPayRows[id] = []; renderAgrPayRows(id); return; }
      const priced = agrPricingValue();
      const amounts = priced ? splitEvenly(priced, n) : Array(n).fill(0);
      agrPayRows[id] = amounts.map(a => ({ date: "", amount: a }));
      renderAgrPayRows(id);
      if (!priced) toast("Pricing not set", "Enter the pricing and re-pick the number of payments to split it automatically.");
    };
    // Re-split when the pricing changes, unless someone has already overridden a line.
    const pricing = document.getElementById("reqf_pricing");
    if (pricing && !pricing.dataset.payHooked) {
      pricing.dataset.payHooked = "1";
      pricing.addEventListener("change", () => {
        const rows = agrPayFor(id);
        if (!rows.length) return;
        const touched = rows.some(r => r._touched);
        if (touched) { renderAgrPayRows(id); return; }
        const amounts = splitEvenly(agrPricingValue(), rows.length);
        rows.forEach((r, i) => r.amount = amounts[i]);
        renderAgrPayRows(id);
      });
    }
  });
}
function wireAssetListFields() {
  document.querySelectorAll('[id$="_rows"]').forEach(host => {
    const fieldId = host.id.replace(/_rows$/, "");
    if (!document.getElementById(fieldId + "_import")) return;
    if (!agrAssetRows[fieldId]) agrAssetRows[fieldId] = [];
    renderAgrAssetRows(fieldId);
    document.getElementById(fieldId + "_add").onclick = () => {
      agrRowsFor(fieldId).push({ id: "", asset: "", qty: 1, note: "" });
      renderAgrAssetRows(fieldId);
    };
    document.getElementById(fieldId + "_import").onchange = e => {
      const p = loadOptions().find(x => x.id === e.target.value);
      e.target.value = "";
      if (!p) return;
      // Import the richest option — that is the one people build first and trim down from.
      const best = (p.options || []).slice().sort((a, b) => (b.items || []).length - (a.items || []).length)[0];
      if (!best || !(best.items || []).length) { toast("Nothing to import", "That proposal has no assets on it."); return; }
      agrAssetRows[fieldId] = sortByCategoryThenRate(best.items, optLineTotal)
        .map(it => ({ id: it.id, asset: it.asset, qty: it.qty || 1, note: it.notes || "" }));
      renderAgrAssetRows(fieldId);
      /* index242 — routine-success toast removed. The action it announced is already visible: the list re-renders, the row updates, or the panel closes. */
    };
  });
}
