  try { e.dataTransfer.setData("DownloadURL", urls.map(x => x.mime + ":" + x.name + ":" + x.url).join("\n")); } catch (err) {}
  try { e.dataTransfer.setData("text/uri-list", urls.map(x => x.url).join("\r\n")); } catch (err) {}
  try { e.dataTransfer.setData("text/plain", plain.join(", ")); } catch (err) {}
