  if (q) list = list.filter(r => (r.sponsor || "").toLowerCase().includes(q) || parseSponsorAssetLines(r.assets).some(l => l.text.toLowerCase().includes(q)));
  if (pcState.gap === "nophotos") list = list.filter(r => parseSponsorAssetLines(r.assets).some(l => photosForSponsorAssetLineByReport(r.id, l.text, reportTag).length < 5));
  if (pcState.gap === "nologo") list = list.filter(r => !r.logoDataUrl);
