    if (pcState.sort === "sponsor") return (a.sponsor || "").localeCompare(b.sponsor || "");
    if (pcState.sort === "rep") return (a.rep || "").localeCompare(b.rep || "") || (a.sponsor || "").localeCompare(b.sponsor || "");
    if (pcState.sort === "category") return (a.category || "").localeCompare(b.category || "") || (a.sponsor || "").localeCompare(b.sponsor || "");
    if (pcState.sort === "asset") return (parseSponsorAssetLines(a.assets)[0]?.text || "").localeCompare(parseSponsorAssetLines(b.assets)[0]?.text || "") || (a.sponsor || "").localeCompare(b.sponsor || "");
