  const searchText = [raw, assetLabel, line && line.text].filter(Boolean).join(" ");

  /* index257 — 0. NOTHING TO PHOTOGRAPH BEATS EVERYTHING.
     This test used to sit at step 6, so an entitlement line whose name happened to match a theme
     night ("Friends & Family Plan Sponsor") or whose catalog group read as permanent signage
     ("Parking Lot Storage") was classified before it was ever asked whether a camera could see
     it. When the answer is no, none of the timing rules matter. The physical override inside the
     test still rescues "Suite Sign", "Ticket Back Advertising" and the naming-rights lines. */
  if (ASSET_NOT_A_DISPLAY_RE.test(searchText) && !ASSET_IS_PHYSICAL_RE.test(searchText)) return { kind: "nodisplay", note: "nothing installed to photograph" };
  if (ASSET_OFFSITE_RE.test(searchText) && !ASSET_IN_PARK_SCREEN_RE.test(searchText)) return { kind: "offsite", note: "delivered online, not in the park" };

