    if(!total)return;
    const release=await bcConfirm(`${name} still holds ${total} ballpark placement${total===1?"":"s"} — ${slotHits.length} display slot${slotHits.length===1?"":"s"} and ${utgHits.length} Upper Tier block${utgHits.length===1?"":"s"}. Release them so the space reads Available again? "Keep + flag" leaves them placed, marked "Sponsor is hidden" for review.`,{title:"Ballpark placements",ok:"Release placements",cancel:"Keep + flag"});
