  if(slot.sponsorId){const rec=displayRecord(slot.sponsorId);if(rec){const list=(rec.inventoryPlacements||[]).filter(p=>p.slotId!==slot.id&&!(p.asset===slot.asset&&p.position===slot.position));list.push({slotId:slot.id,asset:slot.asset,position:slot.position,sponsor:rec.sponsor,status:slot.status,source:"Ballpark Displays user assignment",sponsorId:rec.id,artwork:slot.artwork?true:null});updateOverride(rec.id,{inventoryPlacements:list});}}
