function contractedUpperPanels(sponsorId, sponsorName){
  try{
    const all = (typeof getAllRecords === "function") ? getAllRecords() : [];
    const rec = all.find(r => (sponsorId && r.id === sponsorId))
             || (sponsorName ? all.find(r => (r.sponsor || "").trim().toLowerCase() === String(sponsorName).trim().toLowerCase()) : null);
    if(!rec) return null;
    const lines = (typeof dealAssetsFor === "function") ? (dealAssetsFor(rec) || []) : [];
    for(const a of lines){
      const n = a.name || a.asset || "";
      if(/upper tier billboard/i.test(n)){
        const panels = upperPanelsFromAssetName(n);
        if(panels) return panels;
      }
    }
  }catch(e){}
  return null;
}
