/* ---- Ballpark Displays: locate, flash, occupancy ------------------------------------------ */
let bpLocated = "";
function locateSponsorPanels(sponsorId) {
  const st = completeBallparkState(loadBallparkDisplays());
  const rec = displayRecord(sponsorId);
  const name = rec ? rec.sponsor : sponsorId;
  document.querySelectorAll(".bp-located").forEach(el => el.classList.remove("bp-located"));
  if (bpLocated === sponsorId) { bpLocated = ""; document.body.classList.remove("bp-locating"); return; }   /* index242: the highlight visibly clears */
  bpLocated = sponsorId;
  const mine = st.placements.filter(p => p.sponsorId === sponsorId || (rec && p.sponsor === rec.sponsor));
  const ids = new Set(mine.map(p => p.id));
  /* index213: Upper Tier grid blocks are their own markup (data-utg-block) — the highlight used
     to skip the biggest board entirely and report "no panels placed". */
  const utgIds = new Set();
  try { Object.values(st.upperGrid || {}).forEach(list => (list || []).forEach(b => { if (b.sponsorId === sponsorId) utgIds.add(b.id); })); } catch (e) {}
  let first = null, panels = 0;
  document.querySelectorAll("[data-slot-id]").forEach(el => {
    if (!ids.has(el.dataset.slotId)) return;
    el.classList.add("bp-located");
    panels += 1;
    if (!first) first = el;
  });
  document.querySelectorAll("[data-utg-block]").forEach(el => {
    if (!utgIds.has(el.dataset.utgBlock)) return;
    el.classList.add("bp-located");
    panels += 1;
    if (!first) first = el;
  });
  document.body.classList.toggle("bp-locating", panels > 0);
  if (first) first.scrollIntoView({ behavior: prefersReducedMotion() ? "auto" : "smooth", block: "center" });
  toast(panels ? `${name} — ${panels} panel${panels === 1 ? "" : "s"}` : `${name} has no panels placed`,
        panels ? "Highlighted across every board. Click the sponsor again to clear." : "Drag them onto a board to place one.");
}
/* A stepper press on a dense board needs to be visibly attached to a result. */
