/* Panels used out of six, per Upper Tier board. */
function renderBoardOccupancy() {
  const st = completeBallparkState(loadBallparkDisplays());
  document.querySelectorAll("[data-board-occupancy]").forEach(host => {
    const boardPosition = host.dataset.boardOccupancy;
    const rows = st.placements.filter(p => p.position === boardPosition && !p.filler);
    const used = rows.filter(p => p.sponsorId || p.sponsor || p.nonPaying || p.manualAssigned).reduce((sum, p) => sum + (p.span || 0), 0);
    const open = Math.max(0, UPPER_TIER_PANELS_PER_BOARD - used);
    const unsettledBoard = st.placements.some(p => p.position === boardPosition && p.filler && p.unsettled);
    const pct = Math.max(0, Math.min(100, Math.round((used / UPPER_TIER_PANELS_PER_BOARD) * 100)));
    const tone = used >= UPPER_TIER_PANELS_PER_BOARD ? "full" : used === 0 ? "empty" : "part";
    const unsized = rows.filter(p => p.sizeUnset).length;
    host.title = `${used} of ${UPPER_TIER_PANELS_PER_BOARD} panels sold · ${open / UPPER_TIER_SLOT_PANELS} slot(s) open`
      + (unsized ? ` · ${unsized} sponsor${unsized === 1 ? "" : "s"} the rule does not settle` : "");
    host.innerHTML = `<span class="bp-occ-label">${used} of ${UPPER_TIER_PANELS_PER_BOARD} panels${open ? (unsettledBoard ? ` · ${open / UPPER_TIER_SLOT_PANELS} slot split not set` : ` · ${open / UPPER_TIER_SLOT_PANELS} slot${open / UPPER_TIER_SLOT_PANELS === 1 ? "" : "s"} open`) : ""}</span>
      <span class="bp-occ-track"><span class="bp-occ-fill ${tone}" style="width:${pct}%"></span></span>`;
  });
}
function sectionSlug(v){return String(v).toLowerCase().replace(/['\u2019]/g,"").replace(/[^a-z0-9]+/g,"-").replace(/(^-|-$)/g,"");}
// Strips common corporate suffixes so a short display name (e.g. "Church & Dwight", as
// used in Ballpark Displays/Stadium Map screenshots) still resolves to the full legal
