/* ---- Contract language per asset (Assets & Inventory) ----
   Writes into the same store the Agreement Generator reads (agFindTemplate /
   agUpsertTemplate), so there is one library of clause text, editable from
   whichever screen you happen to be on. */
let assetContractEditing = null;
function normalizeAssetSectionOption(section) {
  const raw = String(section || "").trim();
  const low = raw.toLowerCase();
  if (!raw) return "";
  if (/entitlement|naming/.test(low)) return "Entitlement Areas";
  if (/signage|display|brand|ballpark|scoreboard|marquee|wall|tier/.test(low)) return "Ballpark Branding";
  if (/gameday|game day|promotion|pa read|table|plaza/.test(low)) return "Gameday";
  if (/marketing|digital|broadcast|social|newsletter|print|event/.test(low)) return "Marketing & Events";
  if (/fan|ticket promotion|program|slugger|club/.test(low)) return "Fan & Ticket Promotions";
  if (/ticket|hospitality|suite|picnic|deck|experience/.test(low)) return "Tickets & Experiences";
  return ["Entitlement Areas","Ballpark Branding","Gameday","Marketing & Events","Fan & Ticket Promotions","Tickets & Experiences","Other"].includes(raw) ? raw : "Other";
}
function openAssetContractModal(assetName) {
  // assetName === null means "adding language for an asset I'll name myself" —
  // used by the library card, so custom line items that never appear in the fixed
  // catalog can still have clause text written for them.
  const naming = !assetName;
  assetContractEditing = assetName || null;
  const tpl = assetName ? (agFindTemplate(assetName) || {}) : {};
  const detail = assetName ? assetDetailsFor(assetName) : {};
  document.getElementById("assetContractTitle").textContent = naming ? "New asset details" : assetName;
  const displayNameInput = document.getElementById("assetContractDisplayName");
  if (displayNameInput) {
    displayNameInput.value = assetName ? (detail.displayName || assetName || "") : "";
    document.getElementById("assetContractDisplayNameField").hidden = naming;
  }
  const nameField = document.getElementById("assetContractNameField");
  nameField.hidden = !naming;
  const nameInput = document.getElementById("assetContractName");
  nameInput.value = "";
  if (naming) {
    const names = [...new Set(getFullCatalog().map(a => a.asset).filter(Boolean))].sort();
    document.getElementById("assetContractChoices").innerHTML = names.map(n => `<option value="${esc(n)}"></option>`).join("");
  }
  document.getElementById("assetContractSection").value = normalizeAssetSectionOption(tpl.section || (assetName ? agAssetCategory(assetName) : "") || "");
  document.getElementById("assetContractHeadline").value = tpl.headline || "";
  document.getElementById("assetContractPurpose").value = tpl.purpose || "";
  document.getElementById("assetContractDetails").value = tpl.details || "";
  const catalog = assetName ? getFullCatalog().find(a => assetNameMatch(a.asset, assetName)) : null;
  const fallbackRate = catalog ? lookupRate(catalog) : fulfillmentAssetRate(assetName);
  document.getElementById("assetContractRateCard").value = detail.rateCard !== undefined && detail.rateCard !== null && detail.rateCard !== "" ? Number(detail.rateCard).toLocaleString("en-US") : (fallbackRate ? Number(fallbackRate).toLocaleString("en-US") : "");
  const fallbackRate2027 = catalog && catalog.rate2027 !== undefined && catalog.rate2027 !== null && catalog.rate2027 !== "" ? Number(catalog.rate2027) : "";
  const rate2027Input = document.getElementById("assetContractRateCard2027");
  if (rate2027Input) rate2027Input.value = detail.rateCard2027 !== undefined && detail.rateCard2027 !== null && detail.rateCard2027 !== "" ? Number(detail.rateCard2027).toLocaleString("en-US") : (fallbackRate2027 ? fallbackRate2027.toLocaleString("en-US") : "");
  document.getElementById("assetContractHardCost").value = detail.hardCost !== undefined && detail.hardCost !== null && detail.hardCost !== "" ? Number(detail.hardCost).toLocaleString("en-US") : "";
  document.getElementById("assetContractInventoryQty").value = detail.totalQty ?? "";
  document.getElementById("assetContractDelete").style.display = (assetName && agFindTemplate(assetName)) ? "" : "none";
  /* index212: second clear section — the asset's spec from the library, display-only.
     Editable data (rate, cost, qty, contract language) lives in the section above; the spec
     text itself is maintained in the library seed and shown read-only here and on the
     Asset Prep Hub's spec tab. */
  try {
    const pillEl = document.getElementById("assetContractSpecPill");
    const bodyEl = document.getElementById("assetContractSpecBody");
    if (pillEl && bodyEl) {
      const lib = assetName ? alLibEntryFor(assetName) : null;
      const st = assetName ? alSpecStatusFor(assetName) : "none";
      const m = alStatusMeta(st);
      pillEl.innerHTML = `<span class="type-tag" style="background:${m.bg}; color:${m.fg}; border-color:${m.bd}; margin-left:6px; vertical-align:1px;">${m.label}</span>`;
      if (lib) {
        bodyEl.innerHTML = alDetail(lib).replace('class="table-card"', 'class=""').replace(/style="padding:14px;[^"]*"/, 'style="padding:0;"')
          + `<div style="margin-top:8px; color:var(--muted); font-size:var(--text-xs);">Display only — this spec text lives in the spec library (Asset Prep Hub → Asset Specs shows the same thing).</div>`;
      } else {
        const s = assetName && typeof assetSpecFor === "function" ? assetSpecFor(assetName) : null;
        bodyEl.innerHTML = s && assetSpecHasDetail(s)
          ? [["Description", s.description], ["Specs", s.specs], ["Artwork", s.artwork], ["Asset date", s.assetDate], ["Due", s.due]].filter(r => r[1]).map(r => `<div style="margin-bottom:6px;"><span style="color:var(--muted); font-size:var(--text-xs); text-transform:uppercase; letter-spacing:.04em;">${esc(r[0])}</span><div style="white-space:pre-wrap;">${esc(String(r[1]))}</div></div>`).join("")
          : `No spec in the library for this asset yet — it shows as <b style="color:var(--red);">No spec</b> on the ledger until one is added to the library seed.`;
      }
    }
  } catch (e) { console.error("asset spec section", e); }
  document.getElementById("assetContractBackdrop").classList.add("show");
  if (naming) nameInput.focus();
}
function closeAssetContractModal() {
  assetContractEditing = null;
  document.getElementById("assetContractBackdrop").classList.remove("show");
}
document.getElementById("assetContractClose").addEventListener("click", closeAssetContractModal);
document.getElementById("assetContractCancel").addEventListener("click", closeAssetContractModal);
document.getElementById("assetContractBackdrop").addEventListener("click", e => {
  if (e.target.id === "assetContractBackdrop") closeAssetContractModal();
});
document.getElementById("assetContractSave").addEventListener("click", () => {
  if (!assetContractEditing) {
    const typed = document.getElementById("assetContractName").value.trim();
    if (!typed) { toast("Name the asset first", "Type which asset this language belongs to"); return; }
    /* index214: a near-miss name ("Concourse Banner" vs "Concourse Banners") used to mint orphan
       rate + clause records the real asset would never find. An exact catalog match snaps to the
       catalog spelling; anything else becomes a REAL catalog entry so nothing is ever orphaned. */
    const catHit = getFullCatalog().find(a => assetNameMatch(a.asset, typed) || assetNameMatch(assetDisplayName(a.asset), typed));
    if (catHit) {
      assetContractEditing = catHit.asset;
    } else {
      const baseId = "custom--" + slugify(typed);
      let newId = baseId, n = 2;
      while (getFullCatalog().some(a => a.id === newId)) { newId = `${baseId}-${n++}`; }
      CUSTOM_ASSETS.push({ id: newId, asset: typed, category: "Miscellaneous & Other", frequency: null, notes: null, _custom: true });
      saveCustomAssets(CUSTOM_ASSETS);
      toast("New asset created", `${typed} added to the catalog (Miscellaneous & Other) so its rate and language stay findable`);
      assetContractEditing = typed;
    }
  }
  const headline = document.getElementById("assetContractHeadline").value.trim();
  const details = document.getElementById("assetContractDetails").value;
  const rateCard = parseFloat(document.getElementById("assetContractRateCard").value.replace(/[^\d.]/g, ""));
  const rateCard2027Input = document.getElementById("assetContractRateCard2027");
  const rateCard2027 = rateCard2027Input ? parseFloat(rateCard2027Input.value.replace(/[^\d.]/g, "")) : NaN;
  const hardCost = parseFloat(document.getElementById("assetContractHardCost").value.replace(/[^\d.]/g, ""));
  const totalQtyRaw = document.getElementById("assetContractInventoryQty").value.trim();
  saveAssetDetail(assetContractEditing, {
    displayName: document.getElementById("assetContractDisplayName")?.value.trim() || assetContractEditing,
    rateCard: Number.isFinite(rateCard) ? rateCard : "",
    rateCard2027: Number.isFinite(rateCard2027) ? rateCard2027 : "",
    hardCost: Number.isFinite(hardCost) ? hardCost : "",
    totalQty: totalQtyRaw === "" ? "" : Number(totalQtyRaw)
  });
  if (headline || details.trim()) {
    agUpsertTemplate({
      asset: assetContractEditing,
      section: document.getElementById("assetContractSection").value.trim() || null,
      headline: headline || null,
      purpose: document.getElementById("assetContractPurpose").value.trim() || null,
      details
    });
  }
  const saved = assetContractEditing;
  closeAssetContractModal();
  /* index242 — routine-success toast removed. The action it announced is already visible: the list re-renders, the row updates, or the panel closes. */
  if (document.getElementById("assetFileList")) renderAssetTable();
  if (typeof renderAssetLedger === "function" && document.getElementById("assetledgerView") && document.getElementById("assetledgerView").classList.contains("active")) renderAssetLedger();
  if (typeof renderContractLanguageLibrary === "function") renderContractLanguageLibrary();
});
