/* ---- Settings panel ---- */
/* One switch for both the drifting waves and the sidebar texture — they are the same decision,
   so splitting them into two settings would be two questions for one preference. The OS wins:
   prefers-reduced-motion stops the drift regardless of what is set here. */
function applyAmbient(mode) {
  document.body.classList.toggle("no-ambient", mode === "off");
}
function renderSettingsModal() {
  const st = loadSettings();
  document.getElementById("setUserName").value = currentUser() || "";
  document.querySelectorAll("#setLedgerView button").forEach(b => b.classList.toggle("active", b.dataset.setLedger === st.ledgerView));
  document.querySelectorAll("#setTheme button").forEach(b => b.classList.toggle("active", b.dataset.setTheme === st.theme));
  document.querySelectorAll("#setFulfillMath button").forEach(b => b.classList.toggle("active", b.dataset.setMath === st.fulfillMath));
  document.querySelectorAll("#setAmbient button").forEach(b => b.classList.toggle("active", b.dataset.setAmbient === (st.ambient || "on")));
  document.querySelectorAll("#setDesktopNotif button").forEach(b => b.classList.toggle("active", b.dataset.setDesktopNotif === (st.desktopNotif || "off")));
  document.querySelectorAll("#setEmailProvider button").forEach(b => b.classList.toggle("active", b.dataset.setEmailProvider === (st.emailProvider || "gmail")));
  const sitePassInput = document.getElementById("setSitePassword");
  const siteAdminInput = document.getElementById("setSiteAdminPassword");
  const sitePassHint = document.getElementById("setSitePasswordHint");
  if (sitePassInput) sitePassInput.value = "";
  if (siteAdminInput) siteAdminInput.value = "";
  if (sitePassHint) sitePassHint.textContent = "Current default password is set. Use the admin password to change it.";
  const sel = document.getElementById("setSeason");
  const years = currentSeasonYears();
  sel.innerHTML = `<option value="">Whatever's current (${esc(sState.season)})</option>` +
    years.map(y => `<option value="${esc(y)}">${esc(y)}</option>`).join("");
  sel.value = years.includes(String(st.season)) ? String(st.season) : "";
  const spWrap = document.getElementById("setStageProbs");
  if (spWrap) {
    spWrap.innerHTML = Object.keys(DEAL_STAGES).filter(k => k !== "lost").map(k =>
      `<label style="display:grid; grid-template-columns:1fr 58px; gap:var(--space-8); align-items:center; font-size:var(--text-xs); color:var(--muted);">
        <span>${esc(DEAL_STAGES[k].label)}</span>
        <input type="number" min="0" max="100" step="5" data-stage-prob="${k}" value="${dealStageProb(k)}" ${k === "signed" ? "disabled title='Signed is always 100%'" : ""} style="width:54px; text-align:right;">
      </label>`).join("");
  }
}
