  if (!admin || admin.value !== SITE_ADMIN_PASSWORD) { fail("Admin password is incorrect."); if (admin) admin.select(); return; }
  if (!next || !next.value.trim()) { fail("Enter a new site password."); if (next) next.focus(); return; }
  if (!saveSitePassword(next.value)) { fail("Could not save the new site password."); return; }
  admin.value = "";
