document.getElementById("settingsSave").addEventListener("click", () => {
  const name = document.getElementById("setUserName").value.trim();
  // Save the name first: the settings record is keyed to it, so a rename here
  // should write the preferences under the new name rather than the old one.
  setCurrentUser(name);
  try { registerPresenceName(name); } catch (e) {}
  const patch = {
    ledgerView: document.querySelector("#setLedgerView button.active")?.dataset.setLedger || "3",
    theme: document.querySelector("#setTheme button.active")?.dataset.setTheme || "light",
    fulfillMath: document.querySelector("#setFulfillMath button.active")?.dataset.setMath || "asset",
    ambient: document.querySelector("#setAmbient button.active")?.dataset.setAmbient || "on",
    desktopNotif: document.querySelector("#setDesktopNotif button.active")?.dataset.setDesktopNotif || "off",
    emailProvider: document.querySelector("#setEmailProvider button.active")?.dataset.setEmailProvider || "gmail",
    season: document.getElementById("setSeason").value || ""
  };
  saveSettings(patch);
  // T7: persist edited pipeline stage close-%s (Signed forced to 100).
  const probMap = {};
  document.querySelectorAll("#setStageProbs [data-stage-prob]").forEach(inp => {
    probMap[inp.dataset.stageProb] = Math.max(0, Math.min(100, Number(inp.value) || 0));
  });
  probMap.signed = 100; probMap.lost = 0;
  saveStageProbs(probMap);
  maybeRequestDesktopNotifications(patch.desktopNotif).then(ok => {
    if (patch.desktopNotif === "on" && ok) sendDesktopNotice("BlueClaws IQ notifications on", "You'll get desktop alerts for mentions, assignments, and approvals.", "settings");
    if (patch.desktopNotif === "on" && !ok) toast("Notifications blocked", "Browser permission was not granted, so alerts will stay in-app.", true);
  });
  applyTheme(patch.theme);
  applyAmbient(patch.ambient);
  applySeasonalPaper();
  sState.view = patch.ledgerView;
  if (/^\d{4}$/.test(patch.season)) { sState.season = patch.season; updateSeasonBadges(); }
  document.getElementById("settingsBackdrop").classList.remove("show");
  /* index242 — routine-success toast removed. The action it announced is already visible: the list re-renders, the row updates, or the panel closes. */
  refreshCurrentView();
});
