document.getElementById("agLoadProposal").addEventListener("change", e => {
  const which = document.getElementById("agLoadWhichOption");
  const p = loadOptions().find(x => x.id === e.target.value);
  if (!p) { which.innerHTML = '<option value="">Then pick an option…</option>'; which.disabled = true; return; }
  which.disabled = false;
  which.innerHTML = (p.options || []).map((o, i) => {
    const n = (o.items || []).length;
    const price = o.askingPrice ? fmtMoney(parseFloat(o.askingPrice)) : "no asking price";
    return `<option value="${i}">Option ${i + 1} — ${n} asset${n === 1 ? "" : "s"} · ${esc(price)}</option>`;
  }).join("") || '<option value="">No options on this proposal</option>';
});
document.getElementById("agLoadProposalBtn").addEventListener("click", () => {
  const pid = document.getElementById("agLoadProposal").value;
  if (!pid) { toast("Pick a proposal first", "Choose one from the dropdown, then pick which option"); return; }
  const p = loadOptions().find(x => x.id === pid);
  if (!p) return;
  const idx = parseInt(document.getElementById("agLoadWhichOption").value);
  const chosen = (p.options || [])[isFinite(idx) ? idx : 0];
  const items = chosen && chosen.items ? chosen.items.filter(a => (a.asset || "").trim()) : [];
  if (!items.length) { toast("That option is empty", `${p.sponsorName || "This proposal"} has no assets in Option ${(isFinite(idx) ? idx : 0) + 1}`); return; }
  // Quantity AND the note come across, so the agreement inherits what was actually agreed.
  items.forEach(a => {
    const existing = agState.selected.find(s => s.asset.toLowerCase() === a.asset.toLowerCase());
    const qty = Number(a.qty) || 1;
    if (existing) { existing.qty = qty; if (a.notes) existing.note = a.notes; }
    else agState.selected.push({ asset: a.asset, qty, note: a.notes || "" });
  });
  renderAgAssetResults(); renderAgSelectedRows(); renderAgOutput();
  // Proposals match sponsors by name only (no shared id yet) — if there's an exact match,
  // pre-select it as the Sync to Sponsor target so that button works without extra steps.
  const matchedSponsor = (p.sponsorId && getRecord(p.sponsorId)) || getAllRecords().find(r => (r.sponsor || "").trim().toLowerCase() === (p.sponsorName || "").trim().toLowerCase());
  if (matchedSponsor) { const t = document.getElementById("agSyncSponsor"); if (t) t.value = matchedSponsor.id; }
  toast("Loaded", `${items.length} asset${items.length === 1 ? "" : "s"} from Option ${(isFinite(idx) ? idx : 0) + 1} of ${p.sponsorName || "this proposal"}`);
});
