/* ---- Contract viewer (inline PDF/image preview, not a forced download) ---- */
let _contractViewUrl = null;
function dataUrlToBlob(dataUrl) {
  const s = String(dataUrl || "");
  const comma = s.indexOf(",");
  const head = s.slice(0, comma);
  const mime = (head.match(/data:([^;]+)/) || [, "application/octet-stream"])[1];
  const bin = atob(s.slice(comma + 1));
  const arr = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) arr[i] = bin.charCodeAt(i);
  return new Blob([arr], { type: mime });
}
function closeContractViewer() {
  const bd = document.getElementById("contractViewBackdrop");
  if (bd) bd.classList.remove("show");
  const body = document.getElementById("contractViewBody");
  if (body) body.innerHTML = "";
  if (_contractViewUrl) { try { URL.revokeObjectURL(_contractViewUrl); } catch (e) {} _contractViewUrl = null; }
}
function viewContract(id, name) {
  const bodyEl = document.getElementById("contractViewBody");
  const nameEl = document.getElementById("contractViewName");
  const backdrop = document.getElementById("contractViewBackdrop");
  const dlBtn = document.getElementById("contractViewDownload");
  if (!bodyEl || !backdrop) return downloadContract(id, name);   // fallback if markup is missing
  if (_contractViewUrl) { try { URL.revokeObjectURL(_contractViewUrl); } catch (e) {} _contractViewUrl = null; }
  if (nameEl) nameEl.textContent = name || "Agreement";
  if (dlBtn) { dlBtn.onclick = () => downloadContract(id, name); dlBtn.style.display = "none"; }
  bodyEl.innerHTML = `<div class="cv-msg">Loading…</div>`;
  backdrop.classList.add("show");
  loadContractBody(id).then(file => {
    if (!file || !file.dataUrl) {
      if (nameEl) nameEl.textContent = (file && file.name) || name || "Agreement";
      bodyEl.innerHTML = `<div class="cv-msg">This agreement's details are saved, but the file itself isn't on this browser. If it was uploaded on another computer, open it there — otherwise re-upload it from the drawer and it'll open here.</div>`;
      return;
    }
    if (nameEl) nameEl.textContent = file.name || name || "Agreement";
    if (dlBtn) { dlBtn.onclick = () => downloadContract(id, file.name); dlBtn.style.display = ""; }
    const ext = String(file.name || "").split(".").pop().toLowerCase();
    const isPdf = ext === "pdf" || /^data:application\/pdf/i.test(file.dataUrl);
    const isImg = /^data:image\//i.test(file.dataUrl) || ["png", "jpg", "jpeg", "gif", "webp", "svg"].includes(ext);
    if (isPdf) {
      _contractViewUrl = URL.createObjectURL(dataUrlToBlob(file.dataUrl));
      bodyEl.innerHTML = `<iframe title="${esc(file.name || "Agreement")}" src="${esc(_contractViewUrl)}#toolbar=1&navpanes=0"></iframe>`;
    } else if (isImg) {
      bodyEl.innerHTML = `<div style="height:100%; overflow:auto; display:grid; place-items:center; background:#f2f3f5;"><img src="${esc(file.dataUrl)}" alt="${esc(file.name || "Agreement")}" style="max-width:100%; height:auto;"></div>`;
    } else {
      bodyEl.innerHTML = `<div class="cv-msg">This file type (${esc(file.name || "document")}) can't be shown in the browser's viewer. Use Download to open it in Word or another app.</div>`;
    }
  }).catch(() => {
    bodyEl.innerHTML = `<div class="cv-msg">Couldn't read this file from the browser's storage.</div>`;
  });
}
