/* ---- 1. On the clock -------------------------------------------------------------------------
   Homestands are derived from the staff schedule: a rostered day is a gameday, and consecutive
   rostered days are one homestand. That is a derivation, not a schedule feed, so the tooltip says
   so. If a real schedule ever lands, only homestandsFromSchedule() changes. */
function homestandsFromSchedule() {
  let rows = [];
  try { rows = loadStaffSchedule() || []; } catch (e) { return []; }
  const dates = [...new Set(rows.filter(r => r.working && r.date).map(r => r.date))].sort();
  if (!dates.length) return [];
  const stands = [];
  let run = [dates[0]];
  for (let i = 1; i < dates.length; i++) {
    const gap = (Date.parse(dates[i]) - Date.parse(dates[i - 1])) / 86400000;
    if (gap <= 1) run.push(dates[i]);
    else { stands.push(run); run = [dates[i]]; }
  }
  stands.push(run);
  return stands.map(d => ({ start: d[0], end: d[d.length - 1], days: d,
                            label: (rows.find(r => r.date === d[0]) || {}).week || "" }));
}
function dayDiff(a, b) { return Math.round((Date.parse(b) - Date.parse(a)) / 86400000); }
function renderOnClock() {
  const host = document.getElementById("onClock");
  if (!host) return;
  const stands = homestandsFromSchedule();
  if (!stands.length) { host.hidden = true; return; }
  const today = new Date().toISOString().slice(0, 10);
  const current = stands.find(st => st.start <= today && today <= st.end);
  const next = stands.find(st => st.start > today);
  let line1, line2, tone = "";
  if (current) {
    const idx = current.days.filter(d => d <= today).length;
    const left = current.days.filter(d => d > today).length;
    line1 = "Homestand \u00b7 " + (current.label || (current.start + "\u2013" + current.end));
    line2 = "Day " + idx + " of " + current.days.length + (left ? " \u00b7 " + left + " left" : " \u00b7 last one");
    tone = "is-live";
  } else if (next) {
    const d = dayDiff(today, next.start);
    line1 = "Next homestand \u00b7 " + (next.label || next.start);
    line2 = d === 1 ? "Gates open tomorrow" : d + " days out";
  } else {
    line1 = "Season complete";
    line2 = "Renewal season — " + stands.length + " homestands on file";
  }
  host.hidden = false;
  host.className = "onclock " + tone;
  host.title = "Derived from the staff schedule — rostered days are treated as gamedays";
  host.innerHTML = '<strong>' + esc(line1) + '</strong><span>' + esc(line2) + '</span>';
}

/* ---- 2. Count-up on the numbers a view leads with -------------------------------------------
   animateNumberEl already existed and was only used on one chart. Reused here rather than
   written again. It no-ops under prefers-reduced-motion, and it only runs once per view visit so
   switching tabs does not re-roll every figure. */
const countUpDone = new Set();
function runCountUps(viewId) {
  if (prefersReducedMotion() || countUpDone.has(viewId)) return;
  countUpDone.add(viewId);
  const view = document.getElementById(viewId + "View");
  if (!view) return;
  const targets = view.querySelectorAll(".kpi-card strong, .mini-kpi strong, .cross-kpi strong, .call-kpi strong, .context-stat strong, .prospect-stat strong, .pipeline-card strong");
  targets.forEach((el, i) => setTimeout(() => animateNumberEl(el), Math.min(i * 22, 180)));
}

/* ---- 4. Seasonal paper ----------------------------------------------------------------------
   The paper warms through the season and cools in the off-season. Two or three points of hue at
   most — it should never be the thing you notice, only something that makes February feel unlike
   July. Skipped entirely in dark mode, where it would fight the theme. */
function applySeasonalPaper() {
  if (document.body.classList.contains("no-ambient")) { document.documentElement.style.removeProperty("--paper"); return; }
  if ((loadSettings().theme || "light") !== "light") { document.documentElement.style.removeProperty("--paper"); return; }
  const m = new Date().getMonth();                     // 0-11
  // April-September is in-season and warmer; the shoulder months cool toward grey.
  const warm = [0.15,0.2,0.45,0.7,0.9,1,1,0.95,0.8,0.5,0.3,0.15][m];
  const r = Math.round(243 + 3 * warm), g = Math.round(242 + 1 * warm), bl = Math.round(240 - 6 * warm);
  document.documentElement.style.setProperty("--paper", `rgb(${r},${g},${bl})`);
}

/* ---- 6. Wave speed follows fulfillment ------------------------------------------------------
   Ahead on fulfillment, the water moves faster. Deliberately a narrow range — the waves should
   never look agitated, and a slow day should not read as broken. */
function applyWaveTempo() {
  let pct = null;
  try {
    const rows = getAllRecords().filter(r => isActiveForSelectedSeason(r));
    const vals = rows.map(r => fulfillmentPercent(r)).filter(v => v !== null);
    if (vals.length) pct = vals.reduce((a, b) => a + b, 0) / vals.length;
  } catch (e) {}
  if (pct === null) return;
  // 0% -> 78s, 100% -> 42s. One band runs reverse, so relative speeds stay varied.
  const base = 78 - (pct / 100) * 36;
  const root = document.documentElement;
  root.style.setProperty("--wave-1", base.toFixed(0) + "s");
  root.style.setProperty("--wave-2", (base * 1.45).toFixed(0) + "s");
  root.style.setProperty("--wave-3", (base * 0.78).toFixed(0) + "s");
  // The three interleaved fill bands ride the same tempo at their own ratios so the whole field
  // speeds up and slows down together, never in lockstep.
  root.style.setProperty("--wave-4", (base * 1.18).toFixed(0) + "s");
  root.style.setProperty("--wave-5", (base * 1.62).toFixed(0) + "s");
  root.style.setProperty("--wave-6", (base * 0.90).toFixed(0) + "s");
  const el = document.getElementById("ambientWaves");
  if (el) el.title = "Wave speed follows average fulfillment — currently " + Math.round(pct) + "%";
}

/* ---- 5. Something changed on another browser ------------------------------------------------
   The sync poll already knows when the request list changed. This just makes the count say so,
   once, quietly — a nudge, not an alert. */
let lastRequestSignature = null;
function pulseOnRemoteChange() {
  let sig = "";
  try { sig = loadRequests().map(r => r.id + ":" + r.status + ":" + (r.owner || "")).join("|"); } catch (e) { return; }
  if (lastRequestSignature === null) { lastRequestSignature = sig; return; }
  if (sig === lastRequestSignature) return;
  lastRequestSignature = sig;
  ["requestsCount", "mytasksCount"].forEach(id => {
    const el = document.getElementById(id);
    if (!el) return;
    el.classList.remove("just-changed");
    void el.offsetWidth;
    el.classList.add("just-changed");
    setTimeout(() => el.classList.remove("just-changed"), 1600);
  });
}

/* ---- Team chat wiring ---- */
(function wireSideChat(){
  const form = document.getElementById("sideChatForm");
  const input = document.getElementById("sideChatInput");
  const shell = document.getElementById("sideChat");
  const toggle = document.getElementById("sideChatToggle");
  if (!form) return;
  form.addEventListener("submit", e => {
    e.preventDefault();
    if (!currentUser()) { toast("Pick your name first", "Use the \u201cActing as\u201d picker in Requests & Tasks."); return; }
    const v = input.value;
    if (!v.trim()) return;
    input.value = "";
    chatCloseAc();
    postChat(v);
    markChatSeen();
  });
  input.addEventListener("input", chatUpdateAc);
  input.addEventListener("blur", () => setTimeout(chatCloseAc, 120));
  input.addEventListener("keydown", e => {
    if (!chatState.acItems.length) return;
    if (e.key === "ArrowDown") { e.preventDefault(); chatMoveAc(1); }
    else if (e.key === "ArrowUp") { e.preventDefault(); chatMoveAc(-1); }
    else if (e.key === "Escape") { e.preventDefault(); chatCloseAc(); }
    else if (e.key === "Enter" || e.key === "Tab") { e.preventDefault(); chatAcceptAc(chatState.acIndex); }
  });
  toggle.addEventListener("click", () => {
    const collapsed = shell.classList.toggle("collapsed");
    toggle.setAttribute("aria-expanded", String(!collapsed));
    if (!collapsed) markChatSeen();
  });
  document.getElementById("sideChatLog").addEventListener("click", markChatSeen);
  renderChatRooms();
  renderSideChat(true);
  markChatSeen();
  // Repaint on the same cadence the sync pull runs, so messages from other browsers show up
  // without anyone reloading.
  setInterval(() => { if (document.hidden || !bciqLiveUpdatesEnabled()) return; renderChatRooms(); renderSideChat(false); }, 12000);
})();
