// One-time, self-healing across every browser: moves the base64 board-artwork blob out of the
// ~5MB localStorage and into IndexedDB, then deletes the localStorage copy. This is what clears
// the "storage over 80%" state on machines that had been filling up. Runs on every load; a no-op
// once the key is already in IndexedDB.
migrateMediaKeyToIndexedDb(BALLPARK_KEY, v => { ballparkMemCache = v; });
// Every browser self-tidies to a small, uniform localStorage on load — clears leftover local
// contract bodies, dead letters, and any legacy inline-PDF sync-queue entries (files are on the
// server now). Safe/idempotent; a no-op once a browser is already clean.
try { bciqAutoTidyStorage(); } catch (e) {}
/* ================= AUTO-PURGE: erase all photo-library photos on every browser =================
   The Photo Library was retired (nav tab removed) and the mass reference photos are being wiped
   for good. This runs once per browser: it clears this browser's local copy immediately, then
   fetches the shared photos bucket and marks every record deleted so the server bucket empties
   and NO browser (this one or a teammate's) re-pulls them. Logos, graphics, and all non-photo
   data are untouched — this only touches the "photos" bucket. The flag is only set after the
   server clear succeeds, so an offline browser retries on its next load instead of giving up. */
(function autoPurgeAllPhotos() {
  return; // Photo Library is active again for Partner Reports; never purge uploaded report photos on refresh.
  var FLAG = "bciq_photo_masspurge_v1";
  try { if (memStore.getItem(FLAG)) return; } catch (e) { return; }
  function clearLocal() {
    try { photoLibraryMemCache = []; } catch (e) {}
    try { if (typeof savePhotoLibraryLocalOnly === "function") savePhotoLibraryLocalOnly([]); } catch (e) {}
    try { if (typeof mediaDbPut === "function") mediaDbPut(PHOTO_LIBRARY_KEY, []).catch(function(){}); } catch (e) {}
    try { memStore.removeItem(PHOTO_LIBRARY_KEY); } catch (e) {}
    try { if (typeof updatePhotoLibraryCount === "function") updatePhotoLibraryCount(); } catch (e) {}
  }
  try { if (typeof markPhotoSeedsConsumed === "function") markPhotoSeedsConsumed(); } catch (e) {}
  clearLocal();
  if (typeof SHARED_SYNC_ENABLED !== "undefined" && SHARED_SYNC_ENABLED && typeof SHARED_DATA_ENDPOINT !== "undefined") {
    fetch(SHARED_DATA_ENDPOINT + "?bucket=photos", { cache: "no-store" })
      .then(function (r) { return r.ok ? r.json() : null; })
      .then(function (shared) {
        if (shared) {
          Object.keys(shared).forEach(function (id) {
            if (shared[id] && !shared[id].deleted) { try { pushSharedData(id, { deleted: true }, "photos"); } catch (e) {} }
          });
        }
        clearLocal();
        try { memStore.setItem(FLAG, "1"); } catch (e) {}
      })
      .catch(function () { /* offline / blocked — leave flag unset so it retries next load */ });
  } else {
    try { memStore.setItem(FLAG, "1"); } catch (e) {}
  }
  // Belt-and-suspenders: for a few seconds after load, keep this browser's local photo list empty
  // so a poll that lands before the server clear finishes can't briefly repopulate the library.
  var guardUntil = 0;
  try { guardUntil = (typeof performance !== "undefined" ? performance.now() : 0) + 8000; } catch (e) {}
  var guard = setInterval(function () {
    try {
      if (typeof loadPhotoLibrary === "function" && loadPhotoLibrary().length) clearLocal();
      var now = (typeof performance !== "undefined" ? performance.now() : guardUntil + 1);
      if (now >= guardUntil) clearInterval(guard);
    } catch (e) { clearInterval(guard); }
  }, 1000);
})();
setInterval(() => { if (document.hidden || !bciqLiveUpdatesEnabled()) return; runWhenIdle(pullSharedLogos); }, LOGO_SYNC_INTERVAL_MS);
setInterval(() => { if (document.hidden || !bciqLiveUpdatesEnabled()) return; runWhenIdle(pullSharedContracts); }, LOGO_SYNC_INTERVAL_MS);
setInterval(() => { if (document.hidden || !bciqLiveUpdatesEnabled()) return; runWhenIdle(pullSharedDisplays); }, LOGO_SYNC_INTERVAL_MS);
/* index211: photos were PUSH-ONLY — pullSharedPhotos existed (with the same pending-write and
   recently-pushed race guards as every other pull) but nothing ever called it, so a photo tagged
   on one computer never appeared on another until a manual reload. It now polls on the same
   60-second cadence as logos, displays, and contracts. */
/* index256: one delegated drag handler for every photo on every surface, present or future. */
try { wireGlobalPhotoDragOut(); wireDragEdgeWatch(); } catch (e) { console.error("global photo drag wiring", e); }
/* index237: after the first pull has settled, sweep up anything this browser is holding that the
   shared store never received. Deliberately last in the boot order and on a long delay so it never
   competes with the initial render or the first sync. */
runWhenIdle(() => { if (bciqLiveUpdatesEnabled()) bciqAutoReconcilePhotos(); }, 9000);
/* And again when a machine comes back online — that is exactly when a backlog is most likely. */
window.addEventListener("online", function(){ if (bciqLiveUpdatesEnabled()) setTimeout(bciqAutoReconcilePhotos, 4000); });
setInterval(() => { if (document.hidden || !bciqLiveUpdatesEnabled()) return; runWhenIdle(pullSharedPhotos); }, LOGO_SYNC_INTERVAL_MS);

