const SB_SITE_URL = "https://blueclaws26.netlify.app";

function nt_load(key){ try { return JSON.parse(memStore.getItem(key)) || {}; } catch { return {}; } }
function nt_save(key, channel, obj){
  try { durableSet(key, JSON.stringify(obj), "your " + channel + " change"); } catch(e){ try { memStore.setItem(key, JSON.stringify(obj)); } catch(e2){} }
  if (typeof pushSharedData === "function") pushSharedData(channel, { value: JSON.stringify(obj) }, "overrides");
}
function nt_logoHTML(r, size){
  size = size || 26;
  if (!r) return "";
  const logo = r.logoDataUrl || (typeof getLogo === "function" ? getLogo(r.id) : null);
  if (logo) return `<span class="nt-logo" style="width:${size}px;height:${size}px;"><img src="${esc(logo)}" alt="" loading="lazy"></span>`;
  return `<span class="nt-logo nt-logo-fallback" style="width:${size}px;height:${size}px;font-size:${Math.round(size*0.4)}px;">${esc(initials(r.sponsor||"?"))}</span>`;
}
function nt_assetLabels(r){
  /* index214: scoreboard / marquee / e-news eligibility now reads the canonical deal-asset rows
     (picked from the catalog in the drawer). dealAssetsFor falls back to parsing the old notes
     text only when a sponsor has no picked rows yet, so nothing goes dark — but a typo in the
     notes box can no longer change who is eligible for a slot once real rows exist. */
  try { return dealAssetsFor(r).map(a => (a.label || a.asset || "")); } catch(e){}
  try { return parseSponsorAssetLines(r.assets).map(l => (l.label||l.text||"")); } catch(e){ return []; }
}
function nt_sponsorsWithAsset(pred){ return getAllRecords().filter(r => nt_assetLabels(r).some(l => pred(l, r))); }
function nt_countAsset(r, pred){ return nt_assetLabels(r).filter(pred).length; }

/* ---- drag helpers ---- */
let nt_dragSp = null;
function nt_dragStart(e, id){ nt_dragSp = id; try { e.dataTransfer.setData("text/plain", id); e.dataTransfer.effectAllowed = "copy"; } catch(_){} }
function nt_wireDrop(el, onDrop){
  el.addEventListener("dragover", e => { e.preventDefault(); el.classList.add("nt-dragover"); try{ e.dataTransfer.dropEffect="copy"; }catch(_){} });
  el.addEventListener("dragleave", () => el.classList.remove("nt-dragover"));
  el.addEventListener("drop", e => { e.preventDefault(); el.classList.remove("nt-dragover"); const id = (function(){ try { return e.dataTransfer.getData("text/plain"); } catch(_){ return ""; } })() || nt_dragSp; if (id) onDrop(id); nt_dragSp = null; });
}

/* ---- floating sponsor picker ---- */
let nt_menuEl = null;
function nt_closeMenu(){ if (nt_menuEl){ nt_menuEl.remove(); nt_menuEl = null; document.removeEventListener("mousedown", nt_menuOutside, true); } }
function nt_menuOutside(e){ if (nt_menuEl && !nt_menuEl.contains(e.target)) nt_closeMenu(); }
function nt_pickSponsor(anchor, candidates, onPick, opts){
  nt_closeMenu();
  opts = opts || {};
  const menu = document.createElement("div");
  menu.className = "nt-menu";
  menu.innerHTML = `<input type="search" class="nt-menu-search" placeholder="Search sponsor…" aria-label="Search sponsor"><div class="nt-menu-list"></div>` + (opts.allowClear ? `<button type="button" class="nt-menu-clear">Clear this slot</button>` : "");
  document.body.appendChild(menu);
  nt_menuEl = menu;
  const rect = anchor.getBoundingClientRect();
  const vw = document.documentElement.clientWidth;
  menu.style.top = (rect.bottom + window.scrollY + 4) + "px";
  menu.style.left = Math.max(8, Math.min(rect.left + window.scrollX, window.scrollX + vw - 286)) + "px";
  const listEl = menu.querySelector(".nt-menu-list");
  const draw = (q) => {
    const ql = (q||"").toLowerCase();
    const items = candidates.filter(r => !ql || (r.sponsor||"").toLowerCase().includes(ql)).slice(0, 120);
    listEl.innerHTML = items.length ? items.map(r => `<button type="button" class="nt-menu-item" data-sp="${esc(r.id)}">${nt_logoHTML(r,22)}<span>${esc(r.sponsor)}</span></button>`).join("") : `<div class="nt-menu-empty">No matching sponsors</div>`;
    listEl.querySelectorAll(".nt-menu-item").forEach(b => b.onclick = () => { const r = getRecord(b.dataset.sp); nt_closeMenu(); onPick(r); });
  };
  draw("");
  const search = menu.querySelector(".nt-menu-search");
  search.oninput = () => draw(search.value);
  if (opts.allowClear) menu.querySelector(".nt-menu-clear").onclick = () => { nt_closeMenu(); onPick(null); };
  setTimeout(() => { try { search.focus(); } catch(_){} document.addEventListener("mousedown", nt_menuOutside, true); }, 0);
}

/* ---- image picker ---- */
function nt_pickImage(onLoad){
  const inp = document.createElement("input");
  inp.type = "file"; inp.accept = "image/*";
  inp.onchange = () => {
    const f = inp.files && inp.files[0]; if (!f) return;
    if (f.size > 6 * 1024 * 1024) { toast("File too large", "Keep artwork under 6 MB so it can sync."); return; }
    const rd = new FileReader();
    rd.onload = () => onLoad({ name: f.name, dataUrl: rd.result });
    rd.readAsDataURL(f);
  };
  inp.click();
}

/* ============================ SCOREBOARD LAYOUT ============================ */
const SCOREBOARD_KEY = "bciq_scoreboard_layout";
const SB_INNINGS = ["1","2","3","4","5","6","7","8","9","Extra"];
const SB_COLS = [
  { k:"inning",   label:"Inning Sponsor",   match:/inning sponsor/i },
  { k:"elite",    label:"Elite Rotator",    match:/elite rotator/i },
  { k:"premiere", label:"Premiere Rotator", match:/premiere (digital )?rotator/i }
];
let sbMode = "sponsor";
function sbData(){ const d = nt_load(SCOREBOARD_KEY); if (!d.sponsor) d.sponsor = {}; if (!d.artwork) d.artwork = {}; return d; }
function sbPersist(d){ nt_save(SCOREBOARD_KEY, "scoreboardLayout", d); }
function sbSponsorsForCol(col){ return nt_sponsorsWithAsset(l => col.match.test(l)); }
function sbAllScoreboardSponsors(){ return nt_sponsorsWithAsset(l => /inning sponsor|elite rotator|premiere (digital )?rotator|inning takeover|deluxe rotator/i.test(l)); }
function sbIsTakeover(r){ return r && nt_assetLabels(r).some(l => /inning takeover/i.test(l)); }
function sbCellSponsor(d, key){ const id = d.sponsor[key]; return id ? getRecord(id) : null; }
function sbInningLabel(inn){ return inn === "Extra" ? "Extra Innings" : "Inning " + inn; }

function renderScoreboardView(){
  const badge = document.getElementById("scoreboardSeasonBadge"); if (badge) badge.textContent = sState.season;
  document.querySelectorAll("#scoreboardModeSwitch .sb-mode-btn").forEach(b => {
    b.classList.toggle("is-active", b.dataset.sbMode === sbMode);
    b.onclick = () => { sbMode = b.dataset.sbMode; renderScoreboardView(); };
  });
  const note = document.getElementById("scoreboardModeNote");
  if (note) note.textContent = sbMode === "sponsor"
    ? "Drag a sponsor into an inning slot, or click a slot to assign. Takeover sponsors carry a Takeover tag."
    : "Load each sponsor's artwork. A cell only opens once its sponsor is placed on the Sponsor grid.";
  const tray = document.getElementById("scoreboardTray");
  const sponsors = sbAllScoreboardSponsors();
  tray.innerHTML = `<div class="sb-tray-head">Scoreboard sponsors <span>${sponsors.length}</span></div>` +
    (sponsors.length ? sponsors.map(r => `<div class="nt-card" draggable="true" data-sp="${esc(r.id)}">${nt_logoHTML(r,26)}<span class="nt-card-name">${esc(r.sponsor)}</span>${sbIsTakeover(r)?'<span class="sb-takeover-tag">Takeover</span>':''}</div>`).join("")
                       : `<div class="nt-empty">No sponsors carry a scoreboard asset (Inning Sponsor, Elite/Premiere Rotator or Takeover) yet.</div>`);
  tray.querySelectorAll(".nt-card").forEach(c => c.addEventListener("dragstart", e => nt_dragStart(e, c.dataset.sp)));
  const wrap = document.getElementById("scoreboardGridWrap");
  const d = sbData();
  wrap.innerHTML = sbMode === "sponsor" ? sbSponsorGridHTML(d) : sbArtworkGridHTML(d);
  if (sbMode === "sponsor") sbWireSponsorGrid(); else sbWireArtworkGrid();
}
function sbGridHead(){ return `<thead><tr><th class="sb-inning-col">Inning</th>${SB_COLS.map(c=>`<th>${c.label}</th>`).join("")}</tr></thead>`; }
function sbSponsorGridHTML(d){
  return `<table class="sb-grid">${sbGridHead()}<tbody>${SB_INNINGS.map(inn=>`<tr><th class="sb-inning-col">${sbInningLabel(inn)}</th>${SB_COLS.map(c=>{
    const key = inn+"|"+c.k; const r = sbCellSponsor(d,key);
    return `<td class="sb-cell" data-key="${key}">${r
      ? `<div class="sb-placed">${nt_logoHTML(r,22)}<span>${esc(r.sponsor)}</span>${sbIsTakeover(r)?'<span class="sb-takeover-tag">Takeover</span>':''}<button class="sb-x" data-clear="${key}" title="Remove">×</button></div>`
      : `<span class="sb-empty-cell">＋ add</span>`}</td>`;
  }).join("")}</tr>`).join("")}</tbody></table>`;
}
function sbWireSponsorGrid(){
  const d = sbData();
  document.querySelectorAll("#scoreboardGridWrap .sb-cell").forEach(cell => {
    const key = cell.dataset.key;
    const col = SB_COLS.find(c => key.endsWith("|"+c.k));
    nt_wireDrop(cell, id => { const dd = sbData(); dd.sponsor[key] = id; sbPersist(dd); renderScoreboardView(); });
    cell.addEventListener("click", e => {
      if (e.target.closest(".sb-x")) return;
      nt_pickSponsor(cell, sbSponsorsForCol(col), r => { const dd = sbData(); if (r) dd.sponsor[key] = r.id; else delete dd.sponsor[key]; sbPersist(dd); renderScoreboardView(); }, { allowClear: !!d.sponsor[key] });
    });
  });
  document.querySelectorAll("#scoreboardGridWrap [data-clear]").forEach(b => b.addEventListener("click", e => {
    e.stopPropagation(); const dd = sbData(); delete dd.sponsor[b.dataset.clear]; delete dd.artwork[b.dataset.clear]; sbPersist(dd); renderScoreboardView();
  }));
}
function sbArtworkGridHTML(d){
  return `<table class="sb-grid">${sbGridHead()}<tbody>${SB_INNINGS.map(inn=>`<tr><th class="sb-inning-col">${sbInningLabel(inn)}</th>${SB_COLS.map(c=>{
    const key = inn+"|"+c.k; const r = sbCellSponsor(d,key); const art = d.artwork[key];
    if (!r) return `<td class="sb-cell sb-art-cell sb-art-locked" data-key="${key}"><span class="sb-empty-cell">Place a sponsor first</span></td>`;
    return `<td class="sb-cell sb-art-cell" data-key="${key}">${art
      ? `<div class="sb-art"><img src="${esc(art.dataUrl)}" alt=""><div class="sb-art-foot">${nt_logoHTML(r,16)}<span>${esc(r.sponsor)}</span><button class="sb-x" data-artclear="${key}">×</button></div></div>`
      : `<button class="sb-art-add" data-artadd="${key}">＋ Add ${esc(r.sponsor)} artwork</button>`}</td>`;
  }).join("")}</tr>`).join("")}</tbody></table>`;
}
function sbWireArtworkGrid(){
  document.querySelectorAll("#scoreboardGridWrap [data-artadd]").forEach(b => b.addEventListener("click", () => {
    const key = b.dataset.artadd; nt_pickImage(img => { const dd = sbData(); dd.artwork[key] = img; sbPersist(dd); renderScoreboardView(); });
  }));
  document.querySelectorAll("#scoreboardGridWrap [data-artclear]").forEach(b => b.addEventListener("click", () => {
    const dd = sbData(); delete dd.artwork[b.dataset.artclear]; sbPersist(dd); renderScoreboardView();
  }));
}

/* ============================ DIGITAL MARQUEE ============================ */
const MARQUEE_KEY = "bciq_marquee_schedule";
const MARQUEE_SLOTS = 32;
/* index257: two places printed "32" as prose beside a live board built from this constant.
   Typed counts drift the moment the constant does; these now read it. */
(function stampMarqueeCounts(){
  function go(){
    var b=document.getElementById("marqueeSlotBadge"); if(b) b.textContent = MARQUEE_SLOTS + " SLOTS";
    var h=document.getElementById("marqueeSlotHint"); if(h) h.textContent = MARQUEE_SLOTS + " fixed slots — assign a sponsor, run window, artwork and history.";
  }
  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", go); else go();
})();
function mqData(){ const d = nt_load(MARQUEE_KEY); if (!d.slots) d.slots = {}; if (!d.tray) d.tray = {}; return d; }
function mqPersist(d){ nt_save(MARQUEE_KEY, "marqueeSchedule", d); }
function mqSponsors(){ return nt_sponsorsWithAsset(l => /digital marquee/i.test(l)); }
function mqContracted(r){ return nt_countAsset(r, l => /digital marquee/i.test(l)) || 1; }
function mqScheduled(d, id){ let n = 0; for (let i=1;i<=MARQUEE_SLOTS;i++){ if (d.slots[i] && d.slots[i].sponsorId === id) n++; } return n; }
function mqAutoHistory(r, s){ if (r && (s.start || s.end)) return `${r.sponsor}: ${s.start||'?'} - ${s.end||'?'}`; return ""; }
function renderMarqueeView(){
  const d = mqData();
  const pq = (document.getElementById("marqueePartnerSearch")?.value || "").toLowerCase().trim();
  const sponsors = mqSponsors().filter(r => !pq || (r.sponsor || "").toLowerCase().includes(pq));
  const psearch = document.getElementById("marqueePartnerSearch");
  if (psearch && !psearch.dataset.wired) { psearch.dataset.wired = "1"; psearch.addEventListener("input", renderMarqueeView); }
  const tray = document.getElementById("marqueeTray");
  tray.innerHTML = sponsors.length ? sponsors.map(r => {
    const sched = mqScheduled(d, r.id), con = mqContracted(r), done = con > 0 && sched >= con, t = d.tray[r.id] || {};
    return `<div class="sched-card ${done?'is-complete':''}" draggable="true" data-sp="${esc(r.id)}">
      <div class="sched-card-top">${nt_logoHTML(r,28)}<span class="nt-card-name">${esc(r.sponsor)}</span><span class="sched-qty ${done?'ok':''}">${sched} / ${con}</span></div>
      <div class="sched-card-fields"><input class="nt-inp" data-mqnote="${esc(r.id)}" placeholder="Notes" value="${esc(t.notes||'')}"><input class="nt-inp" data-mqtiming="${esc(r.id)}" placeholder="Timing (if any)" value="${esc(t.timing||'')}"></div>
    </div>`;
  }).join("") : `<div class="nt-empty">No sponsors carry a Digital Marquee asset yet.</div>`;
  tray.querySelectorAll(".sched-card").forEach(c => c.addEventListener("dragstart", e => nt_dragStart(e, c.dataset.sp)));
  tray.querySelectorAll("[data-mqnote]").forEach(inp => inp.addEventListener("change", () => { const dd = mqData(); (dd.tray[inp.dataset.mqnote] = dd.tray[inp.dataset.mqnote] || {}).notes = inp.value; mqPersist(dd); }));
  tray.querySelectorAll("[data-mqtiming]").forEach(inp => inp.addEventListener("change", () => { const dd = mqData(); (dd.tray[inp.dataset.mqtiming] = dd.tray[inp.dataset.mqtiming] || {}).timing = inp.value; mqPersist(dd); }));

  const wrap = document.getElementById("marqueeSlots");
  let html = "";
  for (let i=1;i<=MARQUEE_SLOTS;i++){
    const s = d.slots[i] || {}; const r = s.sponsorId ? getRecord(s.sponsorId) : null;
    html += `<div class="mq-slot" data-slot="${i}">
      <div class="mq-slot-head"><span class="mq-slot-num">SLOT ${i}</span>${r?`<button class="sb-x" data-mqclear="${i}" title="Clear slot">×</button>`:''}</div>
      <div class="mq-slot-body ${r?'':'mq-slot-empty'}" data-mqdrop="${i}">${r?`<div class="sb-placed">${nt_logoHTML(r,22)}<span>${esc(r.sponsor)}</span></div>`:`<button class="mq-assign" data-mqadd="${i}">＋ Assign sponsor</button>`}</div>
      <div class="mq-slot-dates"><label>Start<input type="date" data-mqstart="${i}" value="${esc(s.start||'')}"></label><label>End<input type="date" data-mqend="${i}" value="${esc(s.end||'')}"></label></div>
      <div class="mq-slot-art">${s.art?`<img src="${esc(s.art.dataUrl)}" alt=""><button class="sb-x mq-art-x" data-mqartclear="${i}">×</button>`:`<button class="mq-art-add" data-mqartadd="${i}">＋ Add ad graphic</button>`}</div>
      <input class="nt-inp" data-mqslotnote="${i}" placeholder="Notes" value="${esc(s.notes||'')}">
      <input class="nt-inp mq-history" data-mqhist="${i}" placeholder="History summary" value="${esc(s.history || mqAutoHistory(r, s))}">
    </div>`;
  }
  wrap.innerHTML = html;
  mqWireSlots();
}
function mqSlotObj(d, i){ if (!d.slots[i]) d.slots[i] = {}; return d.slots[i]; }
function mqWireSlots(){
  document.querySelectorAll("#marqueeSlots [data-mqdrop]").forEach(el => nt_wireDrop(el, id => { const dd = mqData(); mqSlotObj(dd, el.dataset.mqdrop).sponsorId = id; mqPersist(dd); renderMarqueeView(); }));
  document.querySelectorAll("#marqueeSlots [data-mqadd]").forEach(b => b.addEventListener("click", () => nt_pickSponsor(b, mqSponsors(), r => { if (!r) return; const dd = mqData(); mqSlotObj(dd, b.dataset.mqadd).sponsorId = r.id; mqPersist(dd); renderMarqueeView(); })));
  document.querySelectorAll("#marqueeSlots [data-mqclear]").forEach(b => b.addEventListener("click", () => { const dd = mqData(); delete dd.slots[b.dataset.mqclear]; mqPersist(dd); renderMarqueeView(); }));
  /* index213: a run window ending before it starts is refused with a toast, and a date edit no
     longer rebuilds all 32 slots (which reset scroll and focus) — nothing else on screen
     depends on the dates. */
  document.querySelectorAll("#marqueeSlots [data-mqstart]").forEach(inp => inp.addEventListener("change", () => {
    const dd = mqData(); const s = mqSlotObj(dd, inp.dataset.mqstart);
    if (s.end && inp.value && inp.value > s.end) { toast("Check the dates", "The start date is after the end date"); inp.value = s.start || ""; return; }
    s.start = inp.value; mqPersist(dd);
  }));
  document.querySelectorAll("#marqueeSlots [data-mqend]").forEach(inp => inp.addEventListener("change", () => {
    const dd = mqData(); const s = mqSlotObj(dd, inp.dataset.mqend);
    if (s.start && inp.value && inp.value < s.start) { toast("Check the dates", "The end date is before the start date"); inp.value = s.end || ""; return; }
    s.end = inp.value; mqPersist(dd);
  }));
  document.querySelectorAll("#marqueeSlots [data-mqartadd]").forEach(b => b.addEventListener("click", () => nt_pickImage(img => { const dd = mqData(); mqSlotObj(dd, b.dataset.mqartadd).art = img; mqPersist(dd); renderMarqueeView(); })));
  document.querySelectorAll("#marqueeSlots [data-mqartclear]").forEach(b => b.addEventListener("click", () => { const dd = mqData(); delete mqSlotObj(dd, b.dataset.mqartclear).art; mqPersist(dd); renderMarqueeView(); }));
  document.querySelectorAll("#marqueeSlots [data-mqslotnote]").forEach(inp => inp.addEventListener("change", () => { const dd = mqData(); mqSlotObj(dd, inp.dataset.mqslotnote).notes = inp.value; mqPersist(dd); }));
  document.querySelectorAll("#marqueeSlots [data-mqhist]").forEach(inp => inp.addEventListener("change", () => { const dd = mqData(); mqSlotObj(dd, inp.dataset.mqhist).history = inp.value; mqPersist(dd); }));
}

/* ============================ E-NEWSLETTER ============================ */
const ENEWS_KEY = "bciq_enews_schedule";
const ENE_COLS = [ { k:"s1", label:"Sponsor #1", cls:"ene-g1" }, { k:"s2", label:"Sponsor #2", cls:"ene-g2" }, { k:"pp", label:"Presenting Partner", cls:"ene-g3" } ];
let eneYear = null;
function eneData(){ return nt_load(ENEWS_KEY); }
function enePersist(d){ nt_save(ENEWS_KEY, "enewsSchedule", d); }
function eneYD(d, year){ if (!d[year]) d[year] = { tray:{}, weeks:{} }; if (!d[year].tray) d[year].tray = {}; if (!d[year].weeks) d[year].weeks = {}; return d[year]; }
function eneSponsors(){ return nt_sponsorsWithAsset(l => /e-?newsletter/i.test(l)); }
function eneContracted(r){ return nt_countAsset(r, l => /e-?newsletter/i.test(l)) || 1; }
function eneScheduled(yd, id){ let n = 0; Object.values(yd.weeks).forEach(w => ENE_COLS.forEach(c => { if (w[c.k] && w[c.k].id === id) n++; })); return n; }
function eneMondays(year){
  const res = []; const d = new Date(Date.UTC(year, 0, 1));
  d.setUTCDate(d.getUTCDate() + ((1 - d.getUTCDay() + 7) % 7));
  while (d.getUTCFullYear() === year){ res.push(d.toISOString().slice(0,10)); d.setUTCDate(d.getUTCDate() + 7); }
  return res;
}
function eneFmtWeek(iso){ const [y,m,dd] = iso.split("-"); return `${parseInt(m,10)}/${parseInt(dd,10)}`; }
function renderEnewsView(){
  const sel = document.getElementById("enewsYear");
  if (sel && !sel.dataset.filled){
    const cur = parseInt(sState.season,10) || 2026; let opts = "";
    for (let y = cur+1; y >= cur-3; y--) opts += `<option value="${y}">${y}</option>`;
    sel.innerHTML = opts; sel.value = String(cur); sel.dataset.filled = "1";
    sel.onchange = () => { eneYear = parseInt(sel.value,10); renderEnewsView(); };
  }
  eneYear = parseInt(sel ? sel.value : sState.season, 10) || (parseInt(sState.season,10)||2026);
  const badge = document.getElementById("enewsSeasonBadge"); if (badge) badge.textContent = eneYear;
  const alertBtn = document.getElementById("enewsAlertBtn"); if (alertBtn) alertBtn.onclick = eneAlertGreg;

  const d = eneData(); const yd = eneYD(d, eneYear);
  const sponsors = eneSponsors();
  const tray = document.getElementById("enewsTray");
  tray.innerHTML = sponsors.length ? sponsors.map(r => {
    const sched = eneScheduled(yd, r.id), con = eneContracted(r), done = con > 0 && sched >= con, t = yd.tray[r.id] || {};
    return `<div class="sched-card ${done?'is-complete':''}" draggable="true" data-sp="${esc(r.id)}">
      <div class="sched-card-top">${nt_logoHTML(r,28)}<span class="nt-card-name">${esc(r.sponsor)}</span><span class="sched-qty ${done?'ok':''}">${sched} / ${con}</span></div>
      <div class="sched-card-fields"><input class="nt-inp" data-enenote="${esc(r.id)}" placeholder="Notes" value="${esc(t.notes||'')}"><input class="nt-inp" data-enetiming="${esc(r.id)}" placeholder="Timing (if any)" value="${esc(t.timing||'')}"></div>
    </div>`;
  }).join("") : `<div class="nt-empty">No sponsors carry an E-Newsletter asset yet.</div>`;
  tray.querySelectorAll(".sched-card").forEach(c => c.addEventListener("dragstart", e => nt_dragStart(e, c.dataset.sp)));
  tray.querySelectorAll("[data-enenote]").forEach(inp => inp.addEventListener("change", () => { const D = eneData(); (eneYD(D,eneYear).tray[inp.dataset.enenote] = eneYD(D,eneYear).tray[inp.dataset.enenote] || {}).notes = inp.value; enePersist(D); }));
  tray.querySelectorAll("[data-enetiming]").forEach(inp => inp.addEventListener("change", () => { const D = eneData(); (eneYD(D,eneYear).tray[inp.dataset.enetiming] = eneYD(D,eneYear).tray[inp.dataset.enetiming] || {}).timing = inp.value; enePersist(D); }));

  const mondays = eneMondays(eneYear);
  const head = `<thead><tr><th class="ene-week">Week Of</th>${ENE_COLS.map(c=>`<th class="${c.cls}">${c.label} Name</th><th class="${c.cls}">${c.label} Ad</th><th class="${c.cls}">${c.label} Link</th>`).join("")}</tr></thead>`;
  const body = mondays.map(m => {
    const w = yd.weeks[m] || {};
    const cells = ENE_COLS.map(c => {
      const cell = w[c.k] || {}; const r = cell.id ? getRecord(cell.id) : null;
      const nameCell = `<td class="ene-name-cell"><div class="ene-name-slot ${r?'filled':''}" data-enename="${m}|${c.k}">${r?`${nt_logoHTML(r,20)}<span class="nt-card-name">${esc(r.sponsor)}</span><button class="sb-x" data-eneclear="${m}|${c.k}">×</button>`:`<button class="ene-add" data-eneadd="${m}|${c.k}">＋ Add</button>`}</div></td>`;
      const adCell = `<td class="ene-ad-cell"><div class="ene-ad" data-enead="${m}|${c.k}">${cell.art?`<img src="${esc(cell.art.dataUrl)}" alt=""><button class="sb-x mq-art-x" data-eneadclear="${m}|${c.k}">×</button>`:`<span class="ene-ad-empty">＋ ad</span>`}</div></td>`;
      const linkCell = `<td class="ene-link-cell"><input class="nt-inp" data-enelink="${m}|${c.k}" placeholder="https://" value="${esc(cell.link||'')}"></td>`;
      return nameCell + adCell + linkCell;
    }).join("");
    /* index213: the current week gets a gold anchor and the grid opens scrolled to it —
       every visit used to start at January 5 with the season half a page away. */
    const monday = new Date(); monday.setDate(monday.getDate() - ((monday.getDay() + 6) % 7));
    const curIso = monday.toISOString().slice(0, 10);
    const isCur = m === curIso;
    return `<tr${isCur ? ' class="is-current-week"' : ''}><td class="ene-week">${eneFmtWeek(m)}${isCur ? ' <span class="micro-tag">this week</span>' : ''}</td>${cells}</tr>`;
  }).join("");
  const grid = document.getElementById("enewsGrid");
  grid.innerHTML = `<table class="ene-grid">${head}<tbody>${body}</tbody></table>`;
  const curRow = grid.querySelector(".is-current-week");
  if (curRow) { try { curRow.scrollIntoView({ block: "center" }); } catch (e) {} }
  eneWireGrid();
}
function eneCellObj(D, key){ const yd = eneYD(D, eneYear); const [m, k] = key.split("|"); if (!yd.weeks[m]) yd.weeks[m] = {}; if (!yd.weeks[m][k]) yd.weeks[m][k] = {}; return { yd, cell: yd.weeks[m][k] }; }
function eneWireGrid(){
  document.querySelectorAll("#enewsGrid [data-enename]").forEach(el => nt_wireDrop(el, id => { const D = eneData(); eneCellObj(D, el.dataset.enename).cell.id = id; enePersist(D); renderEnewsView(); }));
  document.querySelectorAll("#enewsGrid [data-eneadd]").forEach(b => b.addEventListener("click", e => { e.stopPropagation(); nt_pickSponsor(b, eneSponsors(), r => { if (!r) return; const D = eneData(); eneCellObj(D, b.dataset.eneadd).cell.id = r.id; enePersist(D); renderEnewsView(); }); }));
  document.querySelectorAll("#enewsGrid [data-eneclear]").forEach(b => b.addEventListener("click", e => { e.stopPropagation(); const D = eneData(); const { cell } = eneCellObj(D, b.dataset.eneclear); delete cell.id; enePersist(D); renderEnewsView(); }));
  document.querySelectorAll("#enewsGrid [data-enead]").forEach(el => el.addEventListener("click", e => { if (e.target.closest("[data-eneadclear]")) return; nt_pickImage(img => { const D = eneData(); eneCellObj(D, el.dataset.enead).cell.art = img; enePersist(D); renderEnewsView(); }); }));
  document.querySelectorAll("#enewsGrid [data-eneadclear]").forEach(b => b.addEventListener("click", e => { e.stopPropagation(); const D = eneData(); const { cell } = eneCellObj(D, b.dataset.eneadclear); delete cell.art; enePersist(D); renderEnewsView(); }));
  document.querySelectorAll("#enewsGrid [data-enelink]").forEach(inp => inp.addEventListener("change", () => { const D = eneData(); eneCellObj(D, inp.dataset.enelink).cell.link = inp.value; enePersist(D); }));
}
function eneAlertGreg(){
  const year = eneYear; const D = eneData(); const yd = eneYD(D, year); const mondays = eneMondays(year);
  const nm = (w, k) => { const c = w[k]; if (!c || !c.id) return "—"; const r = getRecord(c.id); return r ? r.sponsor : "—"; };
  let rows = "";
  mondays.forEach(m => { const w = yd.weeks[m] || {}; if (w.s1 || w.s2 || w.pp) rows += `${m}  |  ${nm(w,'s1')}  |  ${nm(w,'s2')}  |  ${nm(w,'pp')}\n`; });
  if (!rows) rows = "(no weeks scheduled yet)\n";
  const body = `Hi Greg,\n\nHere is the current e-newsletter schedule for ${year}, pulled from BlueClaws IQ.\n\nWeek Of  |  Sponsor #1  |  Sponsor #2  |  Presenting Partner\n${rows}\nLive schedule (open the E-Newsletter tab): ${SB_SITE_URL}/#enews\n\nThanks,\n${(typeof currentUser === "function" && currentUser()) || "BlueClaws Partnerships"}`;
  const url = `mailto:ggiombarrese@blueclaws.com?subject=${encodeURIComponent("E-Newsletter schedule update — " + year)}&body=${encodeURIComponent(body)}`;
  try { window.location.href = url; toast("Opening email", "Drafting the schedule to Greg in your mail app."); } catch(e){ toast("Could not open email", "Copy the schedule manually."); }
}

/* ===================== ASSET ALLOCATION HUB =====================
   One place for every asset category. Two reusable dropper concepts:
   • Left/Right Asset Dropper — searchable signed-partner grid on the left, allocation slots on the
     right (this engine). • Top/Bottom — the E-Newsletter / Marquee style (their own views).
   Categories that already have a dedicated visual board (Upper Tier, Home Run Wall, Digital Marquee,
   Scoreboard, E-Newsletters) link out to that board so nothing is lost or duplicated. New categories
   are allocated inline here. State: bciq_asset_alloc_v1, synced like the other shared stores. */
const AA_STORE_KEY = "bciq_asset_alloc_v1";
const AA_CHANNEL = "assetAlloc";
function aaData(){ return nt_load(AA_STORE_KEY); }
function aaPersist(d){ nt_save(AA_STORE_KEY, AA_CHANNEL, d); }
function aaCat(d, key){ if (!d[key]) d[key] = {}; return d[key]; }
function aaKeywords(c){
  if (!c) return [];
  const specific = {
    uppertier: ["upper tier", "upper home run wall banner"],
    homerun: ["home run wall", "hr wall", "home run banner"],
    concourse: ["concourse", "alcove"],
    suites: ["suite"],
    sections: ["section sign", "section signage"],
    ddn: ["digital display network"],
    tableplaza: ["table display", "plaza display"],
    gamesponsors: ["game sponsor", "fireworks game sponsor"],
    gamedayscript: ["pa read", "commercial", "in-game", "pre-game", "post-game", "gameday"],
    weekly: ["weekly", "kids club", "kids eat free", "silver sluggers", "thirsty thursday", "pups in the park", "summer concert"],
    tickets: ["ticket", "outing", "suite", "picnic", "party deck", "champions club"],
    website: ["website", "blueclaws.com"],
    social: ["social media", "linkedin"],
    broadcast: ["broadcast", "podcast", "radio"],
    marquee: ["digital marquee", "marquee"],
    scoreboard: ["scoreboard", "rotator", "inning sponsor"],
    enews: ["e-newsletter", "enewsletter", "newsletter"]
  };
  const base = specific[c.key] || [c.label, c.key].concat((c.slots || []).map(s => s.label), c.groups || []);
  return base.map(x => String(x || "").toLowerCase()).filter(Boolean);
}
function aaHasAssetForCat(r, c){
  const hay = [r.assets || "", r.assetsReports || "", ...(Array.isArray(r.dealAssets) ? r.dealAssets.map(a => `${a.asset || ""} ${a.notes || ""}`) : [])].join(" ").toLowerCase();
  const words = aaKeywords(c);
  return words.length ? words.some(w => hay.includes(w)) : true;
}
function aaCandidates(c){ return (typeof activeSeasonRecords === "function" ? activeSeasonRecords() : getAllRecords()).filter(r => aaHasAssetForCat(r, c)).slice().sort((a,b)=>(a.sponsor||"").localeCompare(b.sponsor||"")); }
